window.COURSE = {"title":"B1 revised scripts — six lessons (English)","version":"3.0.1-owner-reset-R1-2026-10-06","documents":{"DOC-REQ":{"title":"NDT request (teaching sample)","pages":1,"fields":["Request / job reference (fictional: TS-V2)","Planned examination (day only, no calendar date)","Site / contact role (client's maintenance manager — Bram)","Component / drawing and weld IDs (vessel V-2; welds W-07, W-08; drawing V2-GA rev C)","Material (carbon steel)","Thickness / dimensions (12 mm / 1 200 mm — fictional sample values)","Examination extent (100 % of both welds)","NDT method (RT)","Examination technique standard (ISO 17636-2:2022, digital detectors)","Acceptance criteria (ISO 10675-1:2021; level per fictional project specification PS-V2 §6.5)","Attachments","Responsibility / confirmation (role only, no signature)"],"rules":"No default-standard fallback; method standard, acceptance criteria and legal justification are separate fields."},"DOC-TECH-JUST":{"title":"Justification of the technique (teaching sample)","pages":1,"fields":["Job / type of assignment (vessel V-2 shell welds, repair)","3a — Standard issued by a recognised standardisation organisation requiring radiography for this type of assignment: 'none identified'","3b — Contractual / project requirement: fictional PS-V2 rev C §6.3 'All circumferential butt welds in pressure-retaining shell plates shall be examined by radiographic testing over 100 % of their length.' (fictional teaching document — not a standard)","3c — Risk analysis of undetected fabrication defects: attached; RT selected for these welds (summary only, no values)","Prepared by (role: client's welding/NDT engineer — competent in NDT techniques)","Attachments"],"rules":"The selected legal route is 3c (KB IR art 3 §2); 3b alone never suffices; nothing is quoted from a real standard."},"DOC-LOC-JUST":{"title":"Justification of the irradiation location (teaching sample)","pages":1,"fields":["Workpiece / context (installed vessel on saddles; not movable)","Bunker — assessed: dismantling and transport for two repair welds assessed and rejected (reasons recorded) → not reasonably feasible","Irradiation infrastructure — none present; arranging fixed shielding around the vessel for these welds assessed (access on three sides only, crane traffic, duration) → not reasonably feasible","Conclusion for this type of assignment: another place (the hall), after risk analyses by client and company","Client's risk-analysis information for the company (hall occupancy, walkways, store behind the hall, crane use)","Associated evidence / attachments"],"rules":"Immobility, absence of infrastructure or ownership alone are never the stated reason; no transitional flowchart branch."},"DOC-LICENCE":{"title":"Establishment and operating licence — teaching excerpt","pages":2,"fields":["Authorised establishment / practice (industrial radiography in the company bunker and on clients' sites)","Installations covered","Equipment scope / inventory (placeholders, no numeric inventory)","Sources (placeholders)","Conditions","Evidence fields (acceptance, security acceptance where applicable)"],"rules":"Placeholders instead of real reference numbers; not blanket evidence that a job, site or person is ready."},"DOC-CERT-BUNKER":{"title":"Bunker conformity certificate — teaching excerpt","pages":1,"fields":["Description of the bunker and its location on the site","Permitted isotopes / maximum activity; maximum X-ray voltage and current (placeholders)","Permitted working configurations","Safety-logic reference (document with electrical diagram — referenced, not shown)","Validity (maximum 10 years)","Drawn up by: recognised expert in physical control (role only)"],"rules":"No stamp, signature, number or shielding dimension; this example has a roof; no universal roof rule."},"DOC-EXT-WORKER-FILE":{"title":"Pre-assignment information — external worker (teaching sample)","pages":2,"fields":["Page 1 — Sending employer: name / establishment unit / enterprise number (placeholders)","Page 1 — Worker: first name Clara; other identity fields as placeholders","Page 2 — Doses, last five calendar years, per year: 'provided' ×5","Page 2 — Doses, last twelve rolling months with monitoring period: 'NOT PROVIDED'","Page 2 — Non-uniform exposure / internal contamination: none declared","Page 2 — Assignment abroad: not applicable","Instruction / assignment scope (added by the operator): bunker and bunker X-ray set"],"rules":"'provided' / 'not provided' / placeholders only; a missing section is an evidence gap, not zero dose."},"DOC-AGREEMENT":{"title":"Signed agreement — external undertaking and operator (teaching sample)","pages":1,"fields":["Parties (roles only)","Clause A — Individual dosimetric monitoring and transfer of results to the exposure register: external undertaking","Clause B — Personal protective equipment: external undertaking","Clause C — Specific training on the controlled area and task: operator (not allocated)","Signature area: illustrative placeholders, no names"],"rules":"Allocates only what it names."},"DOC-CHECK-SHEET":{"title":"Pre-use check sheet — current version (teaching sample)","pages":1,"fields":["Instrument / device","Function check result","Date","Checked by (role)","Ambiguous sentence: 'Check the meter's response before/after positioning the device' (the sentence Daniel proposes to clarify)"],"rules":"The proposed revision sits beside it marked PROPOSED — not approved."},"DOC-CERT-AGENT":{"title":"Agent-course certificate (teaching sample)","pages":1,"fields":["Holder: Daniel","Theoretical training — knowledge test passed","Training body (placeholder)","Date (placeholder)"],"rules":"Proves the passed knowledge test only."},"DOC-PLANNING":{"title":"Worksite planning sheet (teaching sample)","pages":1,"fields":["Worksite / day","Team","Designated radiation protection agent (line)","Equipment","Client contact person"],"rules":"Designation is a recorded company decision."},"DOC-CONTROL-TEST-PROGRAMME":{"title":"Control and test programme — bunker safety devices (teaching sample)","pages":1,"fields":["Device: door interlock","Columns: Result · Date · Tested by","Previous month: satisfactory · date · name (placeholders)","This month: — · — · — (empty)"],"rules":"Result, date and operator name as KB IR art 15 §4 requires."},"DOC-HOLD-CARD":{"title":"Hold card (teaching sample)","pages":1,"fields":["BUNKER USE ON HOLD","Reason: this month's interlock test result not established","Placed by (role) / informed (roles)"],"rules":"The visible held-work state; not tiny status text."},"DOC-CHANGE-REGISTER":{"title":"Change register of the physical control service (teaching sample)","pages":1,"fields":["Change description (additional X-ray set, type not in licence inventory)","Approvals given / still needed (expert countersignature; Agency decision)","Implementation status (proposal)"],"rules":"Per TR 6 Dec 2021 art 10; not every change shares one signature route."},"DOC-EVENT-RECORD":{"title":"Event account / handover record (teaching sample)","pages":1,"fields":["Observation (time, place, equipment, what happened)","Work / protective status","Contacted — and whether contact succeeded","Unknowns (cause; dose)"],"rules":"Unknowns are never converted into a cause, a dose or a permission."},"DOC-NOTIFICATION":{"title":"Written notification to the Agency — teaching sample (initial)","pages":1,"fields":["What / where / when; when discovered","Equipment and sources involved","Actual consequences incl. doses where known — 'dose under assessment'","Suspected causes (labelled suspected)","Urgent measures taken","Who manages the event","Physician follow-up / proposed INES level where applicable","Notifier (role)"],"rules":"Facts known at that moment; no zero for an unknown."},"DOC-CRITERION-EXTRACT":{"title":"Criterion extract — significant events (teaching card)","pages":1,"fields":["Criterion 1.5 — loss or failure of equipment fulfilling a safety function: direct contact by the next working day; INES evaluation yes","Criterion 1.4 — non-compliance with / unsuitable safety logic leading or possibly leading to unforeseen behaviour: direct contact immediately; INES evaluation yes","Written notification within 48 h for every event meeting a criterion","Source and date of the extract"],"rules":"Learning card; the procedure holds the complete current table."},"DOC-ASSIGNMENT-SLIP":{"title":"Changed assignment slip (teaching sample)","pages":1,"fields":["Worker: Clara","Requested: assist with gamma exposures, hall two, this afternoon","Requested by (role)"],"rules":"Shown beside the instruction record."},"DOC-INSTRUCTION-RECORD":{"title":"Specific instruction record — Clara (teaching sample)","pages":1,"fields":["Area: company bunker","Equipment: bunker X-ray set","Task: X-ray radiography of castings","Given by (role) / date (placeholder)"],"rules":"Scope is the evidence; a different area/equipment/task is outside it."},"DOC-PLANNER":{"title":"Job planner — week view (teaching sample)","pages":1,"fields":["Tuesday: client request received; written justifications received","Wednesday: company risk analysis completed; planning","Thursday (current day): worksite — vessel V-2, welds W-07/W-08"],"rules":"Current day clearly marked; plays automatically, not an exercise."},"DOC-SITE-PLAN":{"title":"Site drawing — client's hall (teaching sample)","pages":1,"fields":["Vessel V-2 position","Protection perimeter line (conceptual; no distances)","Walkway route (agreed) and changed route","Store behind the hall","Gate","Supervision positions"],"rules":"Conceptual planning drawing; no exclusion distances or dose values."},"DOC-FINAL-REPORT":{"title":"Final report — teaching sample (structure only)","pages":1,"fields":["Established causes","Doses","Detailed description","Preventive measures / lessons learned / action plan","Approvals where applicable (recognised expert; class 7 safety adviser)"],"rules":"Structure only; no content invented for the case."},"DOC-REG-EXTRACT":{"title":"Regulation extract page (teaching reader)","pages":1,"fields":["Article reference and short verbatim extract (Dutch) with English gloss"],"rules":"Used in the B1.1 exploration and reference readers."},"DOC-PROCEDURE-RECORD":{"title":"Approved procedure page with its approval line, and a record line (teaching sample)","pages":1,"fields":["Procedure title and version","Approved by: recognised expert (role)","Record line: what was checked · result · date · by whom"],"rules":"Procedure = method; record = evidence of a check on a day."}},"lessons":[{"id":"B1.1","title":"Getting started: radiation protection in Belgian industry","scenes":[{"id":"S01","title":"Welcome to the course","paragraphs":[{"cue":"B1.1-S01-P1","speaker":"Emilia","text":"Hello, I'm Emilia. I lead the physical control service in an industrial radiography company. In this course we'll follow the decisions that make radiation protection part of an ordinary working day: how a job is prepared, who checks what, and what happens when something changes.","screen_text":["Emilia — head of the physical control service"],"start_visual":"At the first word: approved Emilia fully composed on the stage (head, arms, hands inside the frame), beside the supplied workplace image EQ-WORKPLACE-HALL with the portable X-ray generator EQ-XRAY-GENERATOR in it. No empty board.","beats":[{"at":"how a job is prepared","show":"The workplace image gains a soft focus on the generator on its stand","screen":"A job prepared"},{"at":"who checks what","show":"Focus moves to the perimeter kit in the image","screen":"Checks"},{"at":"what happens when something changes","show":"Focus returns wide","screen":"When something changes"}],"equipment":["EQ-WORKPLACE-HALL","EQ-XRAY-GENERATOR","EQ-PERIMETER-KIT"],"characters":["Emilia"],"clip":"B1.1-S01-P1"},{"cue":"B1.1-S01-P2","speaker":"Emilia","text":"We'll return to the same people and the same kinds of work. You'll meet Daniel preparing an inspection, Clara arriving with her file, and Bram arranging a job at his site. Their examples will help us connect the Belgian rules with the information and equipment in front of us.","screen_text":["Daniel","Clara","Bram"],"start_visual":"Emilia stays; a preview area beside her shows one participant at a time.","beats":[{"at":"Daniel preparing an inspection","show":"Daniel (handheld instrument visible, EPD left chest, TLD right upper chest) beside the X-ray generator image","screen":"Daniel — radiographer"},{"at":"Clara arriving with her file","show":"Clara in her file-carrying pose replaces Daniel","screen":"Clara — visiting radiographer"},{"at":"Bram arranging a job at his site","show":"Bram with the NDT request page DOC-REQ (overview only, not readable yet)","screen":"Bram — client contact"},{"at":"information and equipment in front of us","show":"Preview area clears to the workplace image"}],"documents":["DOC-REQ"],"characters":["Emilia","Daniel","Clara","Bram"],"clip":"B1.1-S01-P2"},{"cue":"B1.1-S01-P3","speaker":"Emilia","text":"We begin with the framework and the people. Later, we'll build the physics and apply it to more detailed situations. You can pause, replay an explanation and keep your own notes. The practice questions help you understand the decisions; the final assessment is separate.","screen_text":["Framework and people","Radiation science","Applied situations"],"start_visual":"A clean three-stop course route appears beside Emilia; stop 1 active.","beats":[{"at":"framework and the people","show":"Stop 1 highlighted","screen":"1 · Framework and people"},{"at":"build the physics","show":"Stop 2 highlighted briefly","screen":"2 · Radiation science"},{"at":"more detailed situations","show":"Stop 3 highlighted briefly, then stop 1 active again","screen":"3 · Applied situations"},{"at":"keep your own notes","show":"Notes control indicated once (player UI), no panel opened"}],"clip":"B1.1-S01-P3"},{"cue":"B1.1-S01-P4","speaker":"Emilia","text":"One boundary before we start. This is theoretical training for people who work with radioactive sources and radiation-generating devices in Belgian class II industry. Practical experience, instruction for the actual installation and the responsibilities assigned to you still come from your workplace; completing lessons on a screen does not by itself appoint you to a function or authorise you to use a particular piece of equipment.","screen_text":["Theoretical training — class II industry","Practical instruction and designation: your workplace"],"start_visual":"Emilia to camera; route fades to the two labels.","beats":[{"at":"theoretical training","show":"Label 1 appears"},{"at":"still come from your workplace","show":"Label 2 appears"}],"clip":"B1.1-S01-P4"}],"sequence":{"cues_before_interaction":["B1.1-S01-P1","B1.1-S01-P2","B1.1-S01-P3","B1.1-S01-P4"],"interaction_after_cue":null,"interaction_id":null,"post_interaction_cues":[]}},{"id":"S02","title":"Where the course will take you","paragraphs":[{"cue":"B1.1-S02-P1","speaker":"Emilia","text":"We begin with the Belgian framework: who is responsible for what, and why protection has to be considered before work starts. From there, we'll explore radiation itself—where it comes from, how it behaves and what the different quantities mean. Those ideas will help us make sense of shielding, exposure, biological effects and personal dosimetry.","screen_text":["Framework and people","Radiation: sources, behaviour, quantities"],"start_visual":"Three-stop route visible, stop 1 active; Emilia beside it.","beats":[{"at":"Belgian framework","show":"Stop 1 label","screen":"Framework and people"},{"at":"explore radiation itself","show":"Stop 2 becomes active","screen":"Radiation science"}],"clip":"B1.1-S02-P1"},{"cue":"B1.1-S02-P2","speaker":"Emilia","text":"Later in the foundations, you'll meet instruments and safety checks, then follow the routines around sources and contamination. Each part of the course is taught by a different colleague whose work fits the subject. I'll stay with you throughout this first module, so we can build on our conversation from one lesson to the next.","screen_text":["Instruments and safety checks","Sources and contamination routines"],"start_visual":"Stop 2 active with two short sub-labels appearing in turn.","beats":[{"at":"instruments and safety checks","show":"Sub-label 1"},{"at":"sources and contamination","show":"Sub-label 2"},{"at":"different colleague","show":"Small presenter marker on later stops (no names)"}],"clip":"B1.1-S02-P2"},{"cue":"B1.1-S02-P3","speaker":"Emilia","text":"The additional class II modules take that foundation into more detailed situations: the authorised activity, equipment and safety systems, radioactive sources, more demanding measurements, worksite arrangements and transport, and the response when something unusual happens. We won't ask you to solve all of that today. Each module gives you something the next one can use.","screen_text":["Class II modules: applied situations"],"start_visual":"Stop 3 active; the detailed module list is NOT shown on stage — a separate 'Course map' reader is indicated.","beats":[{"at":"additional class II modules","show":"Stop 3 active","screen":"Applied situations"},{"at":"Each module gives you something the next one can use","show":"Route shown complete, stop 1 active again"}],"clip":"B1.1-S02-P3"},{"cue":"B1.1-S02-P4","speaker":"Emilia","text":"Along the way, we'll combine explanation with situations from the workplace. Sometimes I'll invite you to explore a detail or choose a response. If a choice isn't right, you'll hear why that particular answer doesn't fit. These practice questions are there to help you learn; the final assessment is separate.","screen_text":["Explanation → example → your decision → feedback"],"start_visual":"Emilia to camera; a small rhythm line appears once.","beats":[{"at":"choose a response","show":"Rhythm line shown"},{"at":"final assessment is separate","show":"Line fades"}],"clip":"B1.1-S02-P4"}],"sequence":{"cues_before_interaction":["B1.1-S02-P1","B1.1-S02-P2","B1.1-S02-P3","B1.1-S02-P4"],"interaction_after_cue":null,"interaction_id":null,"post_interaction_cues":[]}},{"id":"S03","title":"The Belgian system: people with different responsibilities","paragraphs":[{"cue":"B1.1-S03-P1","speaker":"Emilia","text":"Before we talk about rules, it helps to know who the names refer to. You've probably heard FANC mentioned at work. It is Belgium's Federal Agency for Nuclear Control, the regulator. Its job is to protect the public, workers and the environment against the risks of ionising radiation, and in companies like mine it supervises how the radiation-protection organisation does its work. On our picture, FANC sits outside the company. It is not a member of the inspection team.","screen_text":["FANC — the regulator, outside the company"],"start_visual":"Compact company scene (office with a window to the hall) on the right; the actual FANC logo EQ-FANC-LOGO appears OUTSIDE the company frame at 'You've probably heard FANC'.","beats":[{"at":"You've probably heard FANC","show":"FANC logo appears outside the company frame","screen":"FANC — Federal Agency for Nuclear Control"},{"at":"FANC sits outside the company","show":"A thin boundary line separates the logo from the company scene"},{"at":"not a member of the inspection team","show":"Daniel visible inside the company scene, logo stays outside"}],"equipment":["EQ-FANC-LOGO"],"characters":["Emilia","Daniel"],"clip":"B1.1-S03-P1"},{"cue":"B1.1-S03-P2","speaker":"Emilia","text":"Now look at the company. An NDT company is the holder of the licence to carry out non-destructive testing by industrial radiography. In the regulation it is called the operator, and every operator must organise a physical control service. Physical control here means the organised radiation-protection function of the company—the people, checks and procedures that keep exposure under control. It is not a medical examination of a worker.","screen_text":["The company = operator","Physical control service"],"start_visual":"Company frame highlighted; the word 'operator' appears on the frame.","beats":[{"at":"called the operator","show":"Label 'operator' on the company frame"},{"at":"organise a physical control service","show":"A service area inside the frame","screen":"Physical control service"},{"at":"not a medical examination","show":"Small crossed-out stethoscope? NO — plain text only: 'not a medical examination'"}],"clip":"B1.1-S03-P2"},{"cue":"B1.1-S03-P3","speaker":"Emilia","text":"This is where I fit in. I am the head of the physical control service of our company. I coordinate and organise the work of the service, and I have direct access to the head of the company. If a responsibility is unclear, or an issue needs to reach management, the organisation has to let me do that. My title does not make me a recognised expert, though. That is a different function, and the difference matters.","screen_text":["Emilia — head of the service","Direct access to the head of the company"],"start_visual":"Emilia steps into the service area of the scene (supplied pose: standing, open hand).","beats":[{"at":"This is where I fit in","show":"Emilia marker in the service area"},{"at":"direct access to the head of the company","show":"Line from the service to the company management position"},{"at":"does not make me a recognised expert","show":"Text label: 'not a recognised expert'"}],"clip":"B1.1-S03-P3"},{"cue":"B1.1-S03-P4","speaker":"Emilia","text":"A recognised expert in physical control is an individual with a formal recognition. Certain specified tasks belong to that expert—for example, examining and approving the radiation-protection risk analysis and the procedures our people work from. Our company has no recognised expert on its own staff, so, as the regulation requires, we have a contract with a recognised physical-control organisation, and its expert carries out those specified tasks for us. Other companies have an expert on staff and are organised differently; the picture shows our arrangement.","screen_text":["Recognised expert — external organisation under contract"],"start_visual":"A second frame appears beside the company: the recognised physical-control organisation; a contract line connects the two frames.","beats":[{"at":"recognised expert in physical control","show":"External organisation frame appears"},{"at":"contract with a recognised physical-control organisation","show":"Contract line drawn between the frames","screen":"Contract"},{"at":"the picture shows our arrangement","show":"Label: 'our arrangement'"}],"clip":"B1.1-S03-P4"},{"cue":"B1.1-S03-P5","speaker":"Emilia","text":"Now the people in the field: the industrial radiographers, sometimes called RT technicians, who actually carry out the radiography. In industrial radiography this is not optional: every radiographer follows the training for radiation protection agents early in their employment, and a radiographer who has not followed it may not operate gamma or X-ray equipment at all. So the radiographer and the radiation protection agent are not two separate groups of people.","screen_text":["Industrial radiographers — all trained as agents"],"start_visual":"Daniel in the hall area of the scene with his handheld instrument.","beats":[{"at":"industrial radiographers","show":"Daniel highlighted"},{"at":"not two separate groups","show":"Label under Daniel: 'radiographer · trained as agent'"}],"equipment":["EQ-HANDHELD-SURVEY","EQ-EPD-LEFT-CHEST","EQ-TLD-RIGHT-UPPER-CHEST"],"characters":["Daniel"],"clip":"B1.1-S03-P5"},{"cue":"B1.1-S03-P6","speaker":"Emilia","text":"What happens on a worksite is this: from the trained radiographers present who belong to our own staff, the company designates one as the radiation protection agent for that worksite. For those tasks, the agent works under our service. The agent's tasks are the frequent, systematic checks of everyday protection—for example, checking that the protection rules and work procedures are being followed, checking that the protective equipment, instruments and dosimeters are available, working and used correctly, and telling me and the recognised expert about any abnormal situation. Those checks are done according to instructions and procedures approved by the recognised expert.","screen_text":["One agent designated per worksite","Checks under expert-approved procedures"],"start_visual":"Planning sheet DOC-PLANNING close-up: the 'designated agent' line with Daniel's name for Thursday.","beats":[{"at":"designates one as the radiation protection agent","show":"DOC-PLANNING line 'Designated agent: Daniel' highlighted"},{"at":"frequent, systematic checks","show":"Back to the scene: Daniel with check sheet DOC-CHECK-SHEET"},{"at":"approved by the recognised expert","show":"Approval line on the procedure page DOC-PROCEDURE-RECORD highlighted"}],"documents":["DOC-PLANNING","DOC-CHECK-SHEET","DOC-PROCEDURE-RECORD"],"clip":"B1.1-S03-P6"},{"cue":"B1.1-S03-P7","speaker":"Emilia","text":"So don't memorise the picture as a ladder of job titles. Think of different kinds of responsibility that have to connect: the regulator supervises; the company organises; the head of service coordinates; the recognised expert examines and approves; the designated agent checks and reports. Contracting an outside expert does not make the company's own responsibility disappear, and designating an agent on a worksite does not take the other radiographers' duties away.","screen_text":["Supervises · organises · coordinates · approves · checks and reports"],"start_visual":"Wide scene: each party pulses once at its verb; no ladder, no arrows of command.","beats":[{"at":"the regulator supervises","show":"FANC logo pulses"},{"at":"the company organises","show":"Company frame pulses"},{"at":"the head of service coordinates","show":"Emilia marker pulses"},{"at":"the recognised expert examines and approves","show":"External frame pulses"},{"at":"the designated agent checks and reports","show":"Daniel pulses"}],"clip":"B1.1-S03-P7"}],"sequence":{"cues_before_interaction":["B1.1-S03-P1","B1.1-S03-P2","B1.1-S03-P3","B1.1-S03-P4","B1.1-S03-P5","B1.1-S03-P6","B1.1-S03-P7"],"interaction_after_cue":null,"interaction_id":null,"post_interaction_cues":[]}},{"id":"S04","title":"A moment to make sense of the map","paragraphs":[{"cue":"B1.1-S04-P1","speaker":"Emilia","text":"There are several new names there, so let's give them a moment to settle. You don't need to recall every duty yet. I'd like you to hold on to one distinction: the regulator, the recognised organisation with its expert, and our own company are three different things, even though they all work on protection.","screen_text":["Regulator · recognised organisation · our company"],"start_visual":"The S03 scene stays, simplified to three frames.","beats":[{"at":"three different things","show":"Three frames pulse once"}],"clip":"B1.1-S04-P1"},{"cue":"B1.1-S04-P2","speaker":"Emilia","text":"Here is a question a colleague once asked me. On my desk are two pieces of paper that look alike at first: a visit notice from the expert of our recognised organisation, and a letter with the FANC logo announcing an inspection. The expert visits us every few months.","screen_text":["Expert visit notice","FANC inspection letter"],"start_visual":"Two document thumbnails side by side: visit notice (organisation header placeholder) and an Agency letter with the actual FANC logo; headers readable, bodies not.","beats":[{"at":"visit notice from the expert","show":"Left thumbnail highlighted"},{"at":"letter with the FANC logo","show":"Right thumbnail highlighted"}],"documents":["DOC-REG-EXTRACT"],"equipment":["EQ-FANC-LOGO"],"clip":"B1.1-S04-P2"}],"interaction":{"id":"B1.1-I00","type":"single_choice","prompt_spoken_once":"Is the recognised expert's visit the same as a FANC inspection?","behaviour":"The prompt is spoken automatically exactly once when the activity opens; the narration lead-in never reads it. Manual 'Hear the question' replay. Each option has its own spoken and written feedback (evidence, then next step). Retry without replaying narration; keyboard equivalents (labelled radio controls, Check, Try again, Continue); no auto-advance; no colour-only cues; no timer. Feedback never invents a dose, cause, approval or successful contact.","situation_visible_text":"Two documents: the expert's visit notice (our contracted organisation) and an inspection letter from FANC.","options":[{"id":"same","text":"Yes — the expert carries out FANC's inspections on its behalf.","correct":false,"feedback":{"spoken":"The visit notice does tell us something real: the expert of our contracted organisation is coming to do the expert tasks we have entrusted to that organisation, under a contract the regulation requires. What it is not is an inspection by the regulator. FANC supervises separately, and its letter is the evidence of that. Two documents, two senders, two functions.","screen":"Expert visit = our contracted organisation's expert tasks. FANC inspection = the regulator, separately."},"clip":"B1.1-I00-same"},{"id":"separate","text":"No — the expert works for our company under contract; FANC supervises us separately.","correct":true,"feedback":{"spoken":"That's it. The expert's visits are part of our own physical-control arrangement, contracted by the company; the FANC letter is the regulator's own supervision. Having an expert does not make the inspection go away, and the inspection does not replace the expert. Now we can use the picture without treating everyone as interchangeable.","screen":"Correct: contracted expert ≠ regulator. Both remain."},"clip":"B1.1-I00-separate"},{"id":"no_fanc","text":"No — because we have an expert, FANC no longer supervises our company.","correct":false,"feedback":{"spoken":"The first half is right: the visit is not a FANC inspection, and the expert really does carry out the specified tasks for us. But look at the second document: FANC still supervises how our physical control service does its job, and the company's own responsibility remains. Contracting an expert adds a function; it does not remove the regulator.","screen":"Expert visit ≠ inspection, but FANC's supervision continues."},"clip":"B1.1-I00-no_fanc"}],"placement":"After S04-P2; both document thumbnails stay visible beside the options.","clip":"B1.1-I00-prompt"},"sequence":{"cues_before_interaction":["B1.1-S04-P1","B1.1-S04-P2"],"interaction_after_cue":"B1.1-S04-P2","interaction_id":"B1.1-I00","post_interaction_cues":[],"rule":"Play cues_before_interaction in order; open the interaction immediately after interaction_after_cue (it speaks its prompt once); post_interaction_cues play only when their condition is met; nothing in post_interaction_cues is spoken before the interaction."}},{"id":"S05","title":"Bram arrives with a request","paragraphs":[{"cue":"B1.1-S05-P1","speaker":"Emilia","text":"Now that we have a picture of the people involved, let's use it in a situation. A request like this reaches our planning desk most weeks. Today it is Bram, the maintenance manager at a client's plant, and he brings it in person. Three parties are involved: the client who asks for the inspection, our company that would carry it out, and the radiographers who would do the work on the client's site. Sometimes the client is also the employer who runs that site; sometimes the site belongs to someone else, and then the site employer has duties of its own.","screen_text":["Client · our company · the radiographers on site"],"start_visual":"Office scene: Bram enters and places the NDT request page DOC-REQ on the desk; Emilia receives it (supplied poses). The page is a recognisable one-page form at ordinary density.","beats":[{"at":"Today it is Bram","show":"Bram enters with the page","screen":"Bram — client's maintenance manager"},{"at":"Three parties are involved","show":"Three labels appear in turn beside the desk"},{"at":"the site employer has duties of its own","show":"Fourth label: 'site employer (where different)'"}],"documents":["DOC-REQ"],"characters":["Emilia","Bram"],"clip":"B1.1-S05-P1"},{"cue":"B1.1-S05-P2","speaker":"Emilia","text":"The request tells us what is to be inspected and when the result is wanted. Look at the component field: vessel V-2, two circumferential welds, W-07 and W-08—and there is the vessel itself. That is useful planning information. It does not yet tell us why radiography is the right method here, or where the exposures would be made. In industrial radiography the client has to put those two things in writing for this type of assignment, give us correct information about the job at the latest twenty-four hours in advance, and name a contact person we can reach throughout the work—that is Bram. And a deadline, however real, is not allowed to push the work into conditions in which it cannot be done safely.","screen_text":["Component: vessel V-2 · welds W-07, W-08","Still open: why radiography · where"],"start_visual":"Full-page overview of DOC-REQ, then a controlled close-up on the component/weld field, then the supplied hall/vessel image EQ-WORKPLACE-HALL, then back to the page.","beats":[{"at":"Look at the component field","show":"Close-up: component / drawing / weld IDs"},{"at":"there is the vessel itself","show":"Supplied workplace image with the vessel; chalk-marked welds"},{"at":"does not yet tell us why","show":"Back to the full page; the 'justification' attachments field shown empty-for-now"},{"at":"that is Bram","show":"Contact-role field highlighted"},{"at":"cannot be done safely","show":"Page returns to the desk"}],"documents":["DOC-REQ"],"equipment":["EQ-WORKPLACE-HALL"],"clip":"B1.1-S05-P2"},{"cue":"B1.1-S05-P3","speaker":"Emilia","text":"So this first lesson is about the reasoning that comes before a job: why use radiation, how will exposure be kept down, and where do dose limits fit? Who does what in detail comes in the next lessons. For now, listen to the request with me and notice what it tells us—and what it leaves open.","screen_text":["Why use radiation? · How is exposure kept down? · Where do limits fit?"],"start_visual":"Emilia to camera with the three questions appearing as short labels.","beats":[{"at":"why use radiation","show":"Label 1"},{"at":"how will exposure be kept down","show":"Label 2"},{"at":"where do dose limits fit","show":"Label 3"}],"clip":"B1.1-S05-P3"}],"sequence":{"cues_before_interaction":["B1.1-S05-P1","B1.1-S05-P2","B1.1-S05-P3"],"interaction_after_cue":null,"interaction_id":null,"post_interaction_cues":[]}},{"id":"S06","title":"Three connected questions","paragraphs":[{"cue":"B1.1-S06-P1","speaker":"Emilia","text":"Belgian radiation protection rests on three connected principles. I find them easier to remember as three different questions. First: why is this use of radiation justified? Second: how do we keep exposure as low as reasonably achievable? Third: are the applicable dose limits respected? One answer cannot stand in for all three.","screen_text":["Justified? · As low as reasonably achievable? · Limits respected?"],"start_visual":"The three labels from S05 remain; each brightens at its question.","beats":[{"at":"why is this use of radiation justified","show":"Label 1 bright"},{"at":"as low as reasonably achievable","show":"Label 2 bright"},{"at":"applicable dose limits respected","show":"Label 3 bright"}],"clip":"B1.1-S06-P1"},{"cue":"B1.1-S06-P2","speaker":"Emilia","text":"Justification weighs the benefits of a practice against all its disadvantages, including those for health. Optimisation means keeping every exposure as low as reasonably achievable, with economic and social factors taken into account. Dose limitation sets boundaries that the doses of workers, apprentices and students, and members of the public may not exceed. Today we're discussing ordinary planned work. Medical exposure and emergency situations follow their own rules.","screen_text":["Justification","Optimisation","Dose limitation"],"start_visual":"Labels take their formal names one at a time.","beats":[{"at":"Justification weighs","show":"Label 1 renamed 'Justification'"},{"at":"Optimisation means","show":"Label 2 renamed"},{"at":"Dose limitation sets","show":"Label 3 renamed"},{"at":"Medical exposure and emergency situations","show":"Small text: 'planned work only here'"}],"clip":"B1.1-S06-P2"},{"cue":"B1.1-S06-P3","speaker":"Emilia","text":"Listen to how the question changes. 'Why are we using this method?' isn't the same as 'How will we control exposure?' And neither is answered by saying 'We expect to stay below a limit.' In a moment, I'll give you three workplace replies to our request. Your task will be to recognise which part of the reasoning each one leaves out, rather than memorise a slogan.","screen_text":[],"start_visual":"Emilia to camera; labels dim.","beats":[{"at":"three workplace replies","show":"Three empty speech-line placeholders appear under the request page (filled in S07)"}],"clip":"B1.1-S06-P3"}],"sequence":{"cues_before_interaction":["B1.1-S06-P1","B1.1-S06-P2","B1.1-S06-P3"],"interaction_after_cue":null,"interaction_id":null,"post_interaction_cues":[]}},{"id":"S07","title":"Justification — who justifies what","paragraphs":[{"cue":"B1.1-S07-P1","speaker":"Emilia","text":"Before we look at a single job, one thing is settled: industrial radiography as a practice was justified before it was ever authorised, and our company's licence—with its scope and conditions—is the proof of that. Nobody on a worksite has to re-argue whether radiography may exist. But for each assignment, the industrial-radiography rules ask three further justification questions, and they are divided between the client and us.","screen_text":["Practice justified: our licence is the proof","Per assignment: technique · location · equipment"],"start_visual":"Licence excerpt DOC-LICENCE thumbnail beside Emilia; then three short labels.","beats":[{"at":"our company's licence","show":"DOC-LICENCE thumbnail (authorised practice field readable)"},{"at":"three further justification questions","show":"Labels: technique (client) · location (client) · equipment (company)"}],"documents":["DOC-LICENCE"],"clip":"B1.1-S07-P1"},{"cue":"B1.1-S07-P2","speaker":"Emilia","text":"The first question is the technique, and it belongs to the client. For each type of assignment, the client justifies in writing why radiography is the right method, and the decree gives two routes. Route one: a specific industrial standard issued by a recognised standardisation organisation requires radiography—then that standard, its issuing body and the clause go in the first field of Bram's justification. His first field says: none identified for these welds. Route two: where the client asks more than the applicable standard, or no standard provides for radiography as the method, the client shows the justification with a risk analysis of what undetected fabrication defects would mean. Read his next two fields together. The project specification for this vessel—a fictional one for our lesson—says that all circumferential shell welds shall be radiographed over their full length. That is Bram's own project requirement; it tells me why he wants RT, and it is not a standard of a standardisation body. What makes it a justification in the decree's sense is the third field: his risk analysis of the consequences of undetected defects in pressure-retaining welds, prepared by a person competent in the testing techniques.","screen_text":["Technique — route 1: standard of a recognised standardisation organisation requiring RT: none identified","Route 2: project requirement + risk analysis of undetected defects"],"start_visual":"Full-page overview of DOC-TECH-JUST (page-shaped, fields in proportion) → close-up on field 3a → 3b → 3c → back to the page.","beats":[{"at":"two routes","show":"Full page DOC-TECH-JUST"},{"at":"His first field says","show":"Close-up field 3a: 'none identified'"},{"at":"Read his next two fields together","show":"Close-up field 3b: the fictional PS-V2 sentence with its 'fictional teaching document' tag"},{"at":"the third field","show":"Close-up field 3c: risk analysis attached; prepared-by role"},{"at":"competent in the testing techniques","show":"Back to the full page"}],"documents":["DOC-TECH-JUST"],"clip":"B1.1-S07-P2"},{"cue":"B1.1-S07-P3","speaker":"Emilia","text":"One sentence on the other standards named in Bram's request. The examination technique standard says how the radiographs are made; the acceptance standard says which indications are acceptable; and a personnel certification scheme says how our radiographers are certified. All three apply to this job because the project specification calls for them. Whether a legal provision, our licence or a design code also requires one of them is a separate check I make for each job—I do not assume it either way. Law, contract, technique, acceptance and personnel certification are five different questions, and I read the actual field for each.","screen_text":["Technique standard · acceptance criteria · personnel certification — named by the project","Legal / licence / design-code requirement: checked separately per job"],"start_visual":"DOC-REQ close-up on the three standard fields in turn, then a two-line label.","beats":[{"at":"examination technique standard","show":"DOC-REQ field: examination technique standard"},{"at":"acceptance standard","show":"DOC-REQ field: acceptance criteria"},{"at":"personnel certification scheme","show":"DOC-REQ field: personnel"},{"at":"separate check I make","show":"Label line 2 appears"}],"documents":["DOC-REQ"],"clip":"B1.1-S07-P3"},{"cue":"B1.1-S07-P4","speaker":"Emilia","text":"The second question is the irradiation location, and the client justifies that in writing too. A shielded bunker is the preferred place; where that is not reasonably feasible, an irradiation infrastructure on the site; and only where neither is reasonably feasible, another place, after risk analyses by the client and by us. Look at how Bram's form handles it: it does not stop at 'the vessel cannot be moved'. For the bunker it records what was assessed and why that was judged unreasonable; for an irradiation infrastructure it records that none is present and, separately, that arranging fixed shielding around the vessel for these two welds was assessed and judged not reasonably feasible. The decision rests on that documented assessment of both options. The conditions themselves we will read in the licence lesson.","screen_text":["Location — bunker: assessed, reasons recorded","Irradiation infrastructure: none present AND arranging one assessed","Conclusion: the hall, after both risk analyses"],"start_visual":"Full page DOC-LOC-JUST → close-up on the bunker assessment block → infrastructure block → conclusion → back to page.","beats":[{"at":"Look at how Bram's form handles it","show":"Full page DOC-LOC-JUST"},{"at":"For the bunker it records","show":"Close-up: bunker assessment with reasons"},{"at":"for an irradiation infrastructure","show":"Close-up: infrastructure assessment with reasons"},{"at":"documented assessment of both options","show":"Close-up: conclusion line; then back to the page"}],"documents":["DOC-LOC-JUST"],"clip":"B1.1-S07-P4"},{"cue":"B1.1-S07-P5","speaker":"Emilia","text":"The third question is the equipment, and that one is our company's. Where it is feasible without extra risk, an X-ray generator is preferred over a gamma projector, and if a gamma source is used, its radiation has to suit the inspection. My task as head of the service is to make sure that someone competent in the testing techniques actually justified the technique, the isotope and the activity for each assignment. And if we cannot accept the client's justification of the technique or the location, the company refuses the assignment.","screen_text":["Equipment — our company's question: X-ray preferred where feasible without extra risk","Head of service: a competent person justified technique, isotope, activity"],"start_visual":"Supplied equipment images: X-ray generator EQ-XRAY-GENERATOR and gamma projector EQ-GAMMA-PROJECTOR side by side, clearly labelled; then Emilia.","beats":[{"at":"The third question is the equipment","show":"Two equipment images with labels 'X-ray generator' / 'gamma projector'"},{"at":"X-ray generator is preferred","show":"X-ray image highlighted"},{"at":"My task as head of the service","show":"Emilia to camera"},{"at":"the company refuses the assignment","show":"Text: 'justification not accepted → assignment refused'"}],"equipment":["EQ-XRAY-GENERATOR","EQ-GAMMA-PROJECTOR"],"clip":"B1.1-S07-P5"},{"cue":"B1.1-S07-P6","speaker":"Emilia","text":"Now listen to three replies to our planner's question 'Can we proceed?' 'We always do it this way' tells us about habit. 'The dose will be small' tells us something about an expected exposure, but nothing about why radiography is needed. 'Here is the standard that requires it, and here is the client's written justification of the location; let's check that they apply' gives us something we can examine. That is a much more useful conversation, and it is the one the rules expect.","screen_text":["'We always do it this way' · 'The dose will be small' · 'Here is the requirement and the location justification'"],"start_visual":"The three speech-line placeholders from S06 fill one at a time under the request page.","beats":[{"at":"We always do it this way","show":"Line 1"},{"at":"The dose will be small","show":"Line 2"},{"at":"Here is the standard that requires it","show":"Line 3 (highlighted as the useful one)"}],"clip":"B1.1-S07-P6"}],"sequence":{"cues_before_interaction":["B1.1-S07-P1","B1.1-S07-P2","B1.1-S07-P3","B1.1-S07-P4","B1.1-S07-P5","B1.1-S07-P6"],"interaction_after_cue":null,"interaction_id":null,"post_interaction_cues":[]}},{"id":"S08","title":"Optimisation — preparation makes a difference","paragraphs":[{"cue":"B1.1-S08-P1","speaker":"Emilia","text":"Suppose the justification is in order. I still ask how the job can be organised so that nobody is exposed unnecessarily. Most of that is decided before anyone leaves the depot. The client's written information about the job should be with us at least a day ahead. We agree who the client's contact person is, how many people are needed to supervise the protection perimeter, and where the exposures will be made—in a bunker whenever that is feasible.","screen_text":["Settled before the team leaves: contact person · perimeter supervision · place of exposure"],"start_visual":"One stable site drawing DOC-SITE-PLAN of Bram's hall (vessel, walkway, store, gate); Emilia beside it.","beats":[{"at":"decided before anyone leaves the depot","show":"Site drawing appears"},{"at":"who the client's contact person is","show":"Bram marker at the plan"},{"at":"supervise the protection perimeter","show":"Perimeter line and two supervision positions, one marked '?'"},{"at":"in a bunker whenever that is feasible","show":"Small note: 'this vessel: hall (location justified)'"}],"documents":["DOC-SITE-PLAN"],"characters":["Bram"],"clip":"B1.1-S08-P1"},{"cue":"B1.1-S08-P2","speaker":"Emilia","text":"Optimisation isn't a promise that every number will become zero. It means looking for reasonable ways to improve protection in the actual circumstances, and settling the avoidable questions while there is still time to settle them well. Those arrangements still have to be technically sound and follow our approved procedures; agreeing them is not the same as having them in place on the day.","screen_text":["Optimisation: reasonable improvements, settled in time"],"start_visual":"Drawing stays; Emilia to camera.","beats":[{"at":"isn't a promise that every number will become zero","show":"No numbers anywhere on the drawing (author rule)"}],"clip":"B1.1-S08-P2"},{"cue":"B1.1-S08-P3","speaker":"Emilia","text":"Let's compare two ways of preparing the same job on this drawing. Both would produce the inspection result Bram needs. In one, two questions are still open the day before: who supervises the perimeter at the far side, and which access route will be closed. In the other, the team has settled both with Bram: a named supervisor at the far side, and the walkway closed at the gate during exposures.","screen_text":["Open: far-side supervision · access route","Settled with Bram: supervisor named · walkway closed at the gate"],"start_visual":"Same drawing in two states: first with the two unresolved items highlighted ('?'), then the agreed change (supervisor marker, gate closed) with Bram's marker at the gate.","beats":[{"at":"two questions are still open","show":"State A: two '?' markers"},{"at":"settled both with Bram","show":"State B: supervisor marker and gate closed; Bram marker at the gate"}],"documents":["DOC-SITE-PLAN"],"characters":["Bram"],"clip":"B1.1-S08-P3"}],"sequence":{"cues_before_interaction":["B1.1-S08-P1","B1.1-S08-P2","B1.1-S08-P3"],"interaction_after_cue":null,"interaction_id":null,"post_interaction_cues":[]}},{"id":"S09","title":"Choose a planning response","paragraphs":[{"cue":"B1.1-S09-P1","speaker":"Emilia","text":"Notice the word 'proposed' on the drawing. We are judging preparation, not deciding to start the radiography. You don't need to estimate a dose or move a barrier yourself.","screen_text":["PROPOSED — not released for work"],"start_visual":"Drawing in state A (two open items) with a 'PROPOSED' tag.","beats":[{"at":"the word 'proposed'","show":"Tag highlighted"}],"documents":["DOC-SITE-PLAN"],"clip":"B1.1-S09-P1"}],"interaction":{"id":"B1.1-I03","type":"single_choice","prompt_spoken_once":"Two items are still open the day before the job. Which action reflects optimisation?","behaviour":"The prompt is spoken automatically exactly once when the activity opens; the narration lead-in never reads it. Manual 'Hear the question' replay. Each option has its own spoken and written feedback (evidence, then next step). Retry without replaying narration; keyboard equivalents (labelled radio controls, Check, Try again, Continue); no auto-advance; no colour-only cues; no timer. Feedback never invents a dose, cause, approval or successful contact.","situation_visible_text":"Open on the drawing: who supervises the far side of the perimeter; which access route is closed.","options":[{"id":"settle","text":"Settle both items with Bram before the team leaves.","correct":true,"feedback":{"spoken":"Yes. Who supervises the perimeter and which route is closed are exactly the arrangements the company and the client are expected to agree before the work, and settling them early is what keeps other people's exposure down. On the drawing that is a named supervisor at the far side and the walkway closed at the gate. The plan still goes through our normal review afterwards.","screen":"Settle supervision and the route with the contact person before leaving; review follows."},"clip":"B1.1-I03-settle"},{"id":"forecast","text":"Accept the open items, because the forecast dose stays below the limit.","correct":false,"feedback":{"spoken":"The forecast is real information, and it belongs to the third question—whether limits are respected. Optimisation is the second question: is a reasonable improvement available? Here two are, for the price of a phone call to Bram. An open access route is a planning gap on the drawing whatever the forecast says.","screen":"A forecast answers dose limitation, not optimisation; the two gaps remain."},"clip":"B1.1-I03-forecast"},{"id":"shorter","text":"Shorten the exposure time on site to make up for the open items.","correct":false,"feedback":{"spoken":"Shorter exposure is often a good protection measure in itself. But the exposure time follows from the image quality the inspection needs and from our procedure; cutting it may spoil the result, and it does nothing about who is standing where. The open items are about supervision and access on the drawing, and only agreeing them with Bram closes them.","screen":"Time is not a substitute for unresolved supervision and access."},"clip":"B1.1-I03-shorter"}],"placement":"Drawing state A stays visible; after a correct answer the drawing moves to state B.","clip":"B1.1-I03-prompt"},"sequence":{"cues_before_interaction":["B1.1-S09-P1"],"interaction_after_cue":"B1.1-S09-P1","interaction_id":"B1.1-I03","post_interaction_cues":[],"rule":"Play cues_before_interaction in order; open the interaction immediately after interaction_after_cue (it speaks its prompt once); post_interaction_cues play only when their condition is met; nothing in post_interaction_cues is spoken before the interaction."}},{"id":"S10","title":"A limit is not an exposure allowance","paragraphs":[{"cue":"B1.1-S10-P1","speaker":"Emilia","text":"Here's another comment worth slowing down for: 'We're below the limit, so there's no reason to change anything.' Respecting an applicable limit matters, but it doesn't complete our reasoning. We still need the justification and the optimisation we have just discussed.","screen_text":["Below the limit ≠ reasoning complete"],"start_visual":"Emilia to camera; the three question labels return dimmed, label 3 bright.","beats":[{"at":"We're below the limit","show":"Label 3 bright"},{"at":"justification and the optimisation","show":"Labels 1 and 2 brighten"}],"clip":"B1.1-S10-P1"},{"cue":"B1.1-S10-P2","speaker":"Emilia","text":"I do not treat the difference between a recorded dose and a limit as an allowance that the team should use up. And I can't compare any convenient number with any convenient limit. The quantity, the person or group, and the period have to match: the limits for workers, for example, are written for a specific quantity over a specific period. Later lessons will unpack those distinctions and the actual values carefully.","screen_text":["Quantity · person or group · period must match"],"start_visual":"A single regulation extract page DOC-REG-EXTRACT (dose limits article reference, no values) shown briefly.","beats":[{"at":"The quantity, the person or group, and the period","show":"Three words appear beside the extract"},{"at":"Later lessons will unpack","show":"Extract fades"}],"documents":["DOC-REG-EXTRACT"],"clip":"B1.1-S10-P2"},{"cue":"B1.1-S10-P3","speaker":"Emilia","text":"For now, keep three things apart. A legal dose limit is the boundary that may not be exceeded. A dose constraint is a lower level that the Agency can impose as part of optimisation—a planning tool, not a second limit. And an alarm setting on a dosimeter or rate meter is a working aid, set for a task under our approved arrangements. Hearing an alarm, or not hearing one, is not a complete evaluation of a work plan. Let's test that idea.","screen_text":["Legal dose limit — boundary","Dose constraint — planning tool (Agency)","Alarm setting — working aid on the instrument"],"start_visual":"Sequence: regulation extract (limit) → planning sheet line 'dose constraint: to be considered' → close-up of Daniel's electronic personal dosimeter on his left chest (EQ-EPD-LEFT-CHEST) with no reading shown.","beats":[{"at":"A legal dose limit is the boundary","show":"Regulation extract"},{"at":"A dose constraint is a lower level","show":"DOC-PLANNING line"},{"at":"an alarm setting on a dosimeter","show":"Close-up: Daniel's EPD, left chest; display not readable by design"},{"at":"Let's test that idea","show":"Back to Emilia"}],"documents":["DOC-REG-EXTRACT","DOC-PLANNING"],"equipment":["EQ-EPD-LEFT-CHEST"],"clip":"B1.1-S10-P3"}],"sequence":{"cues_before_interaction":["B1.1-S10-P1","B1.1-S10-P2","B1.1-S10-P3"],"interaction_after_cue":null,"interaction_id":null,"post_interaction_cues":[]}},{"id":"S11","title":"What does the forecast answer?","paragraphs":[{"cue":"B1.1-S11-P1","speaker":"Emilia","text":"A colleague's note is on the desk: one line, a dose forecast set against the applicable limit. It is one small piece of evidence, and the three questions from earlier are still on the board.","screen_text":["Colleague's note: forecast vs applicable limit"],"start_visual":"One small evidence item: a note card with 'Forecast for this job: well below the applicable limit' (no numbers).","beats":[{"at":"one line","show":"Note card readable"}],"clip":"B1.1-S11-P1"}],"interaction":{"id":"B1.1-I04","type":"single_choice","prompt_spoken_once":"A colleague reports that the dose forecast for this job is well below the applicable limit. Which of the three questions does that comparison answer?","behaviour":"The prompt is spoken automatically exactly once when the activity opens; the narration lead-in never reads it. Manual 'Hear the question' replay. Each option has its own spoken and written feedback (evidence, then next step). Retry without replaying narration; keyboard equivalents (labelled radio controls, Check, Try again, Continue); no auto-advance; no colour-only cues; no timer. Feedback never invents a dose, cause, approval or successful contact.","situation_visible_text":"Note: 'Forecast for this job: well below the applicable limit.'","options":[{"id":"limits","text":"Whether the dose limits are respected.","correct":true,"feedback":{"spoken":"Yes. A forecast set against the applicable limit speaks to dose limitation, and that is worth knowing. It tells us nothing yet about why radiography is the right technique or whether the arrangements are optimised—those questions keep their own evidence: Bram's written justifications and the settled drawing.","screen":"Correct: it answers dose limitation only."},"clip":"B1.1-I04-limits"},{"id":"technique","text":"Whether radiography is the right technique for this inspection.","correct":false,"feedback":{"spoken":"The note is honest evidence about expected dose, and that matters for the third question. It cannot make radiography the right method: the technique is justified by the client in writing—by a standard of a recognised standardisation organisation that requires it, or by his risk analysis of undetected defects—not by how small the dose would be.","screen":"Technique is justified in writing by the client, not by a low forecast."},"clip":"B1.1-I04-technique"},{"id":"optimised","text":"Whether the work arrangements are optimised.","correct":false,"feedback":{"spoken":"Being below the limit is the third question, not the second. Optimisation asks whether reasonable improvements to the arrangements are still available—on our drawing, supervision and the route. A forecast cannot answer that on its own; the settled drawing can.","screen":"Optimisation is about the arrangements; the forecast cannot show them."},"clip":"B1.1-I04-optimised"}],"placement":"Note card stays visible beside the options.","clip":"B1.1-I04-prompt"},"sequence":{"cues_before_interaction":["B1.1-S11-P1"],"interaction_after_cue":"B1.1-S11-P1","interaction_id":"B1.1-I04","post_interaction_cues":[],"rule":"Play cues_before_interaction in order; open the interaction immediately after interaction_after_cue (it speaks its prompt once); post_interaction_cues play only when their condition is met; nothing in post_interaction_cues is spoken before the interaction."}},{"id":"S12","title":"The regulation, our licence and our procedures","paragraphs":[{"cue":"B1.1-S12-P1","speaker":"Emilia","text":"A colleague might now ask me, 'If the regulation gives the principles, why do we also need a licence and our own procedures?' I would open these three folders. They relate to one another, but they answer different questions.","screen_text":["Regulation · Licence · Procedures and records"],"start_visual":"Three actual document thumbnails on the desk: a regulation extract page, the licence excerpt, a procedure page with a record line. Not folders.","beats":[{"at":"open these three","show":"Three thumbnails appear"}],"documents":["DOC-REG-EXTRACT","DOC-LICENCE","DOC-PROCEDURE-RECORD"],"clip":"B1.1-S12-P1"},{"cue":"B1.1-S12-P2","speaker":"Emilia","text":"The regulation sets the requirements. Our licence identifies what our company is permitted to do and under which conditions—and, as we saw, it is the proof that the practice is justified. Our procedures, approved by the recognised expert, describe how the work and the checks are carried out, and our records show what was actually checked. A familiar procedure does not let us extend the licence, and the licence is not evidence that today's checks have been completed.","screen_text":["Regulation → requirements","Licence → what we may do, under which conditions","Procedure → method · record → what was checked"],"start_visual":"Each thumbnail enlarges briefly at its sentence (one page at a time, full page then one field).","beats":[{"at":"The regulation sets the requirements","show":"Regulation page"},{"at":"Our licence identifies","show":"Licence page: authorised practice and conditions fields"},{"at":"Our procedures, approved by the recognised expert","show":"Procedure page: approval line, then record line"}],"clip":"B1.1-S12-P2"},{"cue":"B1.1-S12-P3","speaker":"Emilia","text":"Three documents, three different questions. This is a way of understanding the information, not a complete checklist for operating an installation.","screen_text":[],"start_visual":"Thumbnails ready for selection.","beats":[],"clip":"B1.1-S12-P3"}],"interaction":{"id":"B1.1-I05","type":"guided_exploration","prompt_spoken_once":"Open the three documents; read the field each one is for.","items":[{"id":"regulation","label":"The regulation","page":"DOC-REG-EXTRACT — one page, article reference with a short extract","field_in_focus":"Requirement sentence","screen":"Tells us the requirements that apply to us.","spoken":"This page gives me the requirements. What it cannot record is what our team has actually done this morning—that evidence lives in the record.","clip":"B1.1-I05-regulation"},{"id":"licence","label":"Our licence","page":"DOC-LICENCE — page 1, authorised practice and conditions","field_in_focus":"Authorised practice / conditions","screen":"Tells us what our company is permitted to do, under which conditions — and it is the proof the practice is justified.","spoken":"This tells me what we are permitted to do and under which conditions, and it is the proof that the practice is justified. For the job we are preparing now I still need the job's own evidence: Bram's justifications and the settled drawing.","clip":"B1.1-I05-licence"},{"id":"procedure","label":"Approved procedure and record","page":"DOC-PROCEDURE-RECORD — procedure page with approval line; record line below","field_in_focus":"Approval line; record line","screen":"The procedure explains how the work is controlled; the record shows what was actually checked.","spoken":"The procedure explains the way of working, approved by the recognised expert, and the record shows what was checked on a given day. Together they answer 'how' and 'what was done'; the licence still sets how far we may go.","clip":"B1.1-I05-procedure"}],"behaviour":"Reveal one page at a time on selection; full page, then the one field in focus, then back to the page; mark visited, not passed; all three required; keyboard list alternative; no fields below the fold; no timer.","replaces":"B1.1 I05 (kept as the one exploration; texts rewritten positively)","clip":"B1.1-I05-prompt"},"sequence":{"cues_before_interaction":["B1.1-S12-P1","B1.1-S12-P2","B1.1-S12-P3"],"interaction_after_cue":"B1.1-S12-P3","interaction_id":"B1.1-I05","post_interaction_cues":[],"rule":"Play cues_before_interaction in order; open the interaction immediately after interaction_after_cue (it speaks its prompt once); post_interaction_cues play only when their condition is met; nothing in post_interaction_cues is spoken before the interaction."}},{"id":"S13","title":"A changed access route","paragraphs":[{"cue":"B1.1-S13-P1","speaker":"Emilia","text":"Back to our request. We've now been told something concrete: the walkway route changed this morning, and the new route crosses the area we agreed to keep clear during exposures. The access-control plan we agreed with the client still shows the old route. Nobody has started the radiography. That gives us the chance to correct the preparation, instead of pretending that an old plan describes the current situation.","screen_text":["Walkway changed this morning","Agreed plan shows the old route"],"start_visual":"Same site drawing DOC-SITE-PLAN: the changed walkway now crosses the perimeter area; the agreed plan overlay still shows the old route; Daniel at the drawing with his phone (supplied pose) — he has not started.","beats":[{"at":"walkway route changed this morning","show":"New route drawn across the perimeter area"},{"at":"still shows the old route","show":"Old route overlay highlighted"},{"at":"Nobody has started the radiography","show":"HELD badge appears at the vessel: 'Radiography held — route not covered by the agreed plan'"}],"documents":["DOC-SITE-PLAN"],"characters":["Daniel"],"clip":"B1.1-S13-P1"},{"cue":"B1.1-S13-P2","speaker":"Emilia","text":"Remember who controls what here. Access by the site's own people and by third parties is the site employer's responsibility; Bram, the client's contact person, is our link to them; and our radiographers must not expose while safe work is not assured. Daniel holds the work and picks up the phone.","screen_text":["Site employer controls access · Bram is our link · radiographers do not expose while safe work is not assured"],"start_visual":"Daniel on the phone at the drawing; Bram marker at the gate; held badge stays.","beats":[{"at":"Daniel holds the work","show":"Daniel phone pose; held badge pulses once"}],"characters":["Daniel","Bram"],"clip":"B1.1-S13-P2"}],"interaction":{"id":"B1.1-I06","type":"single_choice","prompt_spoken_once":"The new walkway route is not covered by the agreed access-control plan. What should the team do now?","behaviour":"The prompt is spoken automatically exactly once when the activity opens; the narration lead-in never reads it. Manual 'Hear the question' replay. Each option has its own spoken and written feedback (evidence, then next step). Retry without replaying narration; keyboard equivalents (labelled radio controls, Check, Try again, Continue); no auto-advance; no colour-only cues; no timer. Feedback never invents a dose, cause, approval or successful contact.","situation_visible_text":"Drawing: new walkway crosses the perimeter area; agreed plan shows the old route; radiography held.","options":[{"id":"review","text":"Hold the radiography and have the access arrangement re-agreed with Bram and the site employer first.","correct":true,"feedback":{"spoken":"Yes. You've named the mismatch, held the radiography, and taken the access question to the people who control it—Bram as contact person and the site employer—while our own service checks the revised arrangement before anyone exposes. Preparation that is still safe can carry on meanwhile.","screen":"Hold; re-agree access with the contact person and site employer; service checks the revision."},"clip":"B1.1-I06-review"},{"id":"licence","text":"Go ahead as planned, because our licence already covers this kind of work.","correct":false,"feedback":{"spoken":"The licence does establish something: the practice is justified and this kind of work is within our scope and conditions. It says nothing about today's walkway. Readiness for this job rests on the arrangements agreed with Bram and the site employer, and one of them is no longer true—so the drawing, not the licence, is the document to fix.","screen":"The licence covers the practice; the agreed access plan is what no longer matches."},"clip":"B1.1-I06-licence"},{"id":"watch","text":"Ask the radiographers to watch the new route more closely during exposures.","correct":false,"feedback":{"spoken":"Watching is what the agreed supervisors already do at the positions on the drawing. Who supervises the protection perimeter, and with how many people, is agreed with the client before the work—it is not something the radiographer improvises while exposing. A route through the controlled area has to be closed or re-planned by the site employer first.","screen":"Supervision is agreed beforehand; a route through the area must be closed or re-planned."},"clip":"B1.1-I06-watch"}],"placement":"Drawing with the held badge stays visible.","clip":"B1.1-I06-prompt"},"sequence":{"cues_before_interaction":["B1.1-S13-P1","B1.1-S13-P2"],"interaction_after_cue":"B1.1-S13-P2","interaction_id":"B1.1-I06","post_interaction_cues":[],"rule":"Play cues_before_interaction in order; open the interaction immediately after interaction_after_cue (it speaks its prompt once); post_interaction_cues play only when their condition is met; nothing in post_interaction_cues is spoken before the interaction."},"status_badges":[{"kind":"held","label":"Radiography held","explanation":"The new walkway crosses the area agreed to be kept clear; the agreed plan no longer matches. Held until access is re-agreed with the contact person and the site employer and our service has checked the revision."}]},{"id":"S14","title":"Try the reasoning in a different setting","paragraphs":[{"cue":"B1.1-S14-P1","speaker":"Emilia","text":"Let's leave the client's site and try the same reasoning at home, in our own bunker. The licence covers the work and the approved procedure for checking the bunker's safety devices is on the shelf. But today's check record is missing: nobody can show me that the check was done this morning. What conclusion can you support from that? Remember, I am asking what we know, not what is probably true.","screen_text":["Our own bunker — today's check record missing"],"start_visual":"Different workplace image: the company bunker exterior (roofed; EQ-BUNKER-REFERENCE layout) with the control post; the control and test programme page DOC-CONTROL-TEST-PROGRAMME with today's line empty.","beats":[{"at":"in our own bunker","show":"Bunker exterior image"},{"at":"today's check record is missing","show":"Programme page: today's line empty, NOT ESTABLISHED badge"}],"documents":["DOC-CONTROL-TEST-PROGRAMME"],"equipment":["EQ-BUNKER-REFERENCE"],"clip":"B1.1-S14-P1"},{"cue":"B1.1-S14-P2","speaker":"Emilia","text":"I wouldn't turn a missing record into a claim that a safety device has failed; we haven't established that. Equally, I wouldn't treat the existence of the procedure as proof that the check happened. I'd describe the gap plainly and have it resolved by the people responsible—the check done and recorded, or the reason found—before relying on that protection.","screen_text":["Missing record ≠ failed device","Procedure on the shelf ≠ check done"],"start_visual":"Badge explanation visible; Emilia to camera.","beats":[{"at":"I wouldn't turn a missing record","show":"Label 1"},{"at":"existence of the procedure","show":"Label 2"},{"at":"resolved by the people responsible","show":"Text: 'resolved under the procedure — no retest result shown'"}],"clip":"B1.1-S14-P2"}],"sequence":{"cues_before_interaction":["B1.1-S14-P1","B1.1-S14-P2"],"interaction_after_cue":null,"interaction_id":null,"post_interaction_cues":[]},"status_badges":[{"kind":"not_established","label":"Today's check: not established","explanation":"No record of this morning's check can be shown. That is an evidence gap: it does not show a failed device, and the procedure's existence does not show the check happened. Resolved by the responsible people under the procedure."}]},{"id":"S15","title":"Close the lesson and look ahead","paragraphs":[{"cue":"B1.1-S15-P1","speaker":"Emilia","text":"We've covered a lot of new ground together. We began with the purpose of the course, then placed the people on our Belgian picture: the regulator, our company and its physical control service, the recognised organisation and its expert, and the radiographers—all trained as radiation protection agents, with one of them designated by the company on each worksite. Then we met the client, and the three questions you will keep meeting: justification, optimisation and dose limitation. Together, they give a far better basis for protection than a reassuring number on its own.","screen_text":["Regulator · company and service · recognised organisation · radiographers / agents","Justification · Optimisation · Dose limitation"],"start_visual":"Brief visual recap: the S03 scene (three frames, Daniel) then the three question labels.","beats":[{"at":"placed the people","show":"S03 scene"},{"at":"three questions","show":"Three labels"}],"clip":"B1.1-S15-P1"},{"cue":"B1.1-S15-P2","speaker":"Emilia","text":"One last practical habit before we finish, using the three documents from a moment ago. A colleague asks whether our company may use a particular X-ray set for a job. Keep the three documents in view.","screen_text":["Which document would you open?"],"start_visual":"The three document thumbnails from S12 return on the desk.","beats":[{"at":"three documents","show":"Thumbnails: regulation · licence · procedure/record"}],"documents":["DOC-REG-EXTRACT","DOC-LICENCE","DOC-PROCEDURE-RECORD"],"clip":"B1.1-S15-P2"},{"cue":"B1.1-S15-P3","speaker":"Emilia","text":"If the role names still feel unfamiliar, that's all right. Keep the picture available. The next lesson stays with these people, but makes their work more concrete: what the designated agent checks, what the recognised expert approves, and who needs to hear about an abnormal result. You'll have a chance to use the distinctions, rather than just remember their names.","screen_text":["Next: what the agent checks, what the expert approves, who hears about an abnormal result"],"start_visual":"Emilia to camera; bridge to the people lesson.","beats":[{"at":"The next lesson stays with these people","show":"Daniel and Emilia markers"}],"clip":"B1.1-S15-P3"}],"interaction":{"id":"B1.1-R01","type":"single_choice","prompt_spoken_once":"Which document would you open to check the company's permitted equipment?","behaviour":"The prompt is spoken automatically exactly once when the activity opens; the narration lead-in never reads it. Manual 'Hear the question' replay. Each option has its own spoken and written feedback (evidence, then next step). Retry without replaying narration; keyboard equivalents (labelled radio controls, Check, Try again, Continue); no auto-advance; no colour-only cues; no timer. Feedback never invents a dose, cause, approval or successful contact.","situation_visible_text":"Three documents on the desk: the regulation extract, our licence excerpt, the approved procedure with its record line.","options":[{"id":"licence","text":"Our licence — the equipment scope, inventory and conditions.","correct":true,"feedback":{"spoken":"Yes. The licence identifies what our company is permitted to do, with which installations and equipment, and under which conditions. Open it at the equipment scope and conditions fields. If the set is not in that scope, the answer is 'not licensed for the moment'—and the licence lesson shows what happens then.","screen":"Licence → equipment scope / inventory / conditions."},"clip":"B1.1-R01-licence"},{"id":"regulation","text":"The regulation — it lists the requirements for X-ray equipment.","correct":false,"feedback":{"spoken":"The regulation is the right place for requirements—what any operator must meet. It does not say which equipment our company in particular is permitted to use; that is a decision recorded in our licence. Read the regulation for the rule, and the licence for our scope.","screen":"Regulation = requirements for everyone; the licence = our scope."},"clip":"B1.1-R01-regulation"},{"id":"procedure","text":"The approved procedure and record — they show the set being checked.","correct":false,"feedback":{"spoken":"A procedure and its record are good evidence that a check was done, by whom and with what result. They cannot extend what the company is permitted to do; a familiar procedure for a set does not license the set. Permission is in the licence; the record shows today's check.","screen":"Procedure/record = how and what was checked; permission is in the licence."},"clip":"B1.1-R01-procedure"}],"replaces":"B1.1 S15 R01 (free-text reflection) — replaced one-for-one in the same slot","placement":"Between S15-P2 and S15-P3; the licence thumbnail opens at the equipment field on a correct answer.","clip":"B1.1-R01-prompt"},"sequence":{"cues_before_interaction":["B1.1-S15-P1","B1.1-S15-P2"],"interaction_after_cue":"B1.1-S15-P2","interaction_id":"B1.1-R01","post_interaction_cues":[{"cue":"B1.1-S15-P3","condition":"after the activity is completed (any outcome)"}],"rule":"Play cues_before_interaction in order; open the interaction immediately after interaction_after_cue (it speaks its prompt once); post_interaction_cues play only when their condition is met; nothing in post_interaction_cues is spoken before the interaction."}}]},{"id":"B1.2","title":"The people behind radiation protection","scenes":[{"id":"S01","title":"Welcome back: who does what","paragraphs":[{"cue":"B1.2-S01-P1","speaker":"Emilia","text":"Welcome back. Last time we drew a picture of Belgian radiation protection: the regulator outside the company, our company with its physical control service, the recognised organisation whose expert works with us, and the radiographers—all trained as radiation protection agents, one of them designated on each worksite. We also met the client, and the three questions that no reassuring number can answer on its own.","screen_text":["Regulator · company and service · recognised organisation · radiographers / agents"],"start_visual":"Company workspace at the first word (office with the hall behind); Emilia beside it; the S03 picture from B1.1 returns in miniature.","beats":[{"at":"Last time we drew a picture","show":"Miniature picture"},{"at":"We also met the client","show":"Bram's request page DOC-REQ thumbnail on the desk"}],"documents":["DOC-REQ"],"clip":"B1.2-S01-P1"},{"cue":"B1.2-S01-P2","speaker":"Emilia","text":"Today I want to make that picture work for a living. Names on a chart are easy to remember and easy to confuse. What matters on a Monday morning is different: who actually carries out a check, who approves the procedure behind it, who has to hear when a result is wrong, and what a new colleague still needs before we can rely on him. We will stay inside our own company for this lesson, and we will use three ordinary questions that arrived on my desk this week.","screen_text":["Who carries out a check · who approves the procedure · who must hear · what a new colleague still needs"],"start_visual":"Desk with three real documents face down (turned over in S02).","beats":[{"at":"three ordinary questions","show":"Three documents on the desk"}],"clip":"B1.2-S01-P2"},{"cue":"B1.2-S01-P3","speaker":"Emilia","text":"By the end you should be able to explain the difference between doing a check, coordinating it and approving the procedure behind it. You should be able to say what a training certificate proves and what it does not. And you should recognise one role name that is easy to mistake for ours: the delegate for radiological security. None of this needs a legal memory. It needs the habit of asking what a piece of evidence actually establishes.","screen_text":["Doing · coordinating · approving","What a certificate proves","Delegate for radiological security (a different role)"],"start_visual":"Emilia to camera; three short labels in turn.","beats":[{"at":"doing a check, coordinating it and approving","show":"Label 1"},{"at":"what a training certificate proves","show":"Label 2"},{"at":"delegate for radiological security","show":"Label 3"}],"clip":"B1.2-S01-P3"}],"sequence":{"cues_before_interaction":["B1.2-S01-P1","B1.2-S01-P2","B1.2-S01-P3"],"interaction_after_cue":null,"interaction_id":null,"post_interaction_cues":[]}},{"id":"S02","title":"Three questions on my desk","paragraphs":[{"cue":"B1.2-S02-P1","speaker":"Emilia","text":"Here is the first message, from our planning colleague: 'Who is the radiation protection agent on Thursday's worksite?' The second comes from the team: 'Can we start using the revised version of the pre-use check form for the survey meters and the exposure devices?' And the third is from Daniel, a radiographer who joined us a few months ago: 'I passed the agent course. Does that mean I can be the agent on my own now?'","screen_text":["1 · Planning sheet: who is Thursday's agent?","2 · Proposed check form","3 · Daniel's certificate"],"start_visual":"Each document is turned over at its sentence: DOC-PLANNING (designated-agent line empty), DOC-CHECK-SHEET with a PROPOSED revision beside it, DOC-CERT-AGENT.","beats":[{"at":"Who is the radiation protection agent on Thursday","show":"DOC-PLANNING: designated-agent line empty"},{"at":"revised version of the pre-use check form","show":"DOC-CHECK-SHEET current + PROPOSED copy"},{"at":"I passed the agent course","show":"DOC-CERT-AGENT"}],"documents":["DOC-PLANNING","DOC-CHECK-SHEET","DOC-CERT-AGENT"],"clip":"B1.2-S02-P1"},{"cue":"B1.2-S02-P2","speaker":"Emilia","text":"It would be convenient to answer all three with 'ask the safety people'. But that hides the decisions we have to make. A team needs to know who performs a task, who has approved the way it is done, and who is told when something does not fit. Those are three different responsibilities, and if we blur them, a missed check or an unapproved form can sit unnoticed for months.","screen_text":["Who performs · who approved the method · who is told"],"start_visual":"Documents stay; three verbs appear.","beats":[{"at":"who performs a task","show":"Verb 1"},{"at":"who has approved","show":"Verb 2"},{"at":"who is told","show":"Verb 3"}],"clip":"B1.2-S02-P2"},{"cue":"B1.2-S02-P3","speaker":"Emilia","text":"Notice also that the three messages concern different kinds of document. A completed check form records what was observed on a day. A procedure tells us how a check should be done. A certificate shows that a person passed a test. I keep them in the same folder because they belong to the same activity, but I never treat them as the same kind of proof. Hold that thought; we will come back to it with each message.","screen_text":["Record = what was observed on a day","Procedure = how a check is done","Certificate = a person passed a test"],"start_visual":"Close-ups: a completed line on the check sheet; the procedure title/approval line; the certificate's 'knowledge test passed' line.","beats":[{"at":"A completed check form records","show":"Check sheet line"},{"at":"A procedure tells us","show":"Procedure approval line"},{"at":"A certificate shows","show":"Certificate line"}],"clip":"B1.2-S02-P3"}],"sequence":{"cues_before_interaction":["B1.2-S02-P1","B1.2-S02-P2","B1.2-S02-P3"],"interaction_after_cue":null,"interaction_id":null,"post_interaction_cues":[]}},{"id":"S03","title":"The company, its service and the recognised organisation","paragraphs":[{"cue":"B1.2-S03-P1","speaker":"Emilia","text":"Let me begin with the organisation behind all three messages, because the regulation starts there too. Every operator of a classified establishment has to set up a service charged with organising and supervising physical control. In the regulation's words, that duty rests on the exploitant—the operator. For us, the operator is our company, the holder of the establishment and operating licence for industrial radiography. The company can appoint people and contract outside expertise, but it cannot contract away its own responsibility.","screen_text":["The operator organises physical control — responsibility stays with the company"],"start_visual":"Company scene; the company frame labelled 'operator'.","beats":[{"at":"Every operator","show":"Company frame highlighted"},{"at":"cannot contract away its own responsibility","show":"Text label"}],"clip":"B1.2-S03-P1"},{"cue":"B1.2-S03-P2","speaker":"Emilia","text":"Who heads that service depends on who is on the staff. If the operator has a recognised expert in physical control of class one or two among its own personnel, it entrusts the leadership of the service to that expert. If it does not, it entrusts the leadership to a member of staff who has followed the basic and continuing training set out in article 30.4. That is our situation. I am that staff member. For a radiography company the decree adds one more condition: the head of the physical control service has three years of relevant experience in radiation protection for industrial radiography. I am not a recognised expert, and I will not pretend to be one in this course.","screen_text":["Head of service: expert on staff, or trained staff member (30.4)","Radiography: three years' relevant experience"],"start_visual":"Emilia marker in the service area; a regulation extract page DOC-REG-EXTRACT (23.1.3.1) thumbnail.","beats":[{"at":"Who heads that service","show":"Extract thumbnail"},{"at":"three years of relevant experience","show":"Label 2"},{"at":"I am not a recognised expert","show":"Text: 'not a recognised expert'"}],"documents":["DOC-REG-EXTRACT"],"clip":"B1.2-S03-P2"},{"cue":"B1.2-S03-P3","speaker":"Emilia","text":"What does heading the service mean in practice? The regulation says the head coordinates and organises the proper execution of the tasks and assignments given to the service, and has direct access to the head of the establishment and to the operator. So I need to know whether every relevant task is covered, and whether the people concerned can actually perform it. And when a required task cannot be done with the arrangements we have, I have a route straight to the people who can change the arrangements. I do not quietly drop the task or call a missing result satisfactory so that the schedule survives.","screen_text":["Coordinates and organises · direct access to the operator"],"start_visual":"Line from the service to the management position; no ladder.","beats":[{"at":"direct access to the head of the establishment","show":"Access line drawn"},{"at":"I do not quietly drop the task","show":"Text label"}],"clip":"B1.2-S03-P3"},{"cue":"B1.2-S03-P4","speaker":"Emilia","text":"Now the expert. The tasks listed under 23.1.5 b)—examining and approving, measuring, evaluating—are carried out by a recognised expert of class one or two. Because we have no such expert on our staff, the regulation requires us to entrust those tasks to a physical control organisation recognised for the purpose, and a contract between the operator and that organisation is concluded for exactly this. That is why an expert from the recognised organisation appears in our dossiers, approves our procedures and visits our installations. She is not a distant name reserved for accidents. Her work helps establish and evaluate our protection arrangements.","screen_text":["Recognised expert — examines and approves, measures, evaluates — by contract"],"start_visual":"External organisation frame with contract line; the expert's approval line on a procedure page.","beats":[{"at":"Now the expert","show":"External frame"},{"at":"a contract between the operator and that organisation","show":"Contract line"},{"at":"approves our procedures","show":"DOC-PROCEDURE-RECORD approval line"}],"documents":["DOC-PROCEDURE-RECORD"],"clip":"B1.2-S03-P4"},{"cue":"B1.2-S03-P5","speaker":"Emilia","text":"And one more group stands outside our company altogether. In class two and three establishments, the Agency—the Federal Agency for Nuclear Control—is charged with supervising whether the physical control service carries out its mission properly. So the picture is not a single chain of command. It is a company responsible for its own protection, a service that coordinates, an external expert with specified approval duties, and a regulator looking in. A person may hold more than one function when the conditions for each are met. We should still be able to say which responsibility is being exercised in a given decision.","screen_text":["FANC supervises from outside","Not a single chain of command"],"start_visual":"Actual FANC logo outside the company frame; final wide view with the four parties.","beats":[{"at":"the Agency—the Federal Agency for Nuclear Control","show":"FANC logo appears outside"},{"at":"not a single chain of command","show":"All four parties shown without arrows of command"}],"equipment":["EQ-FANC-LOGO"],"clip":"B1.2-S03-P5"}],"sequence":{"cues_before_interaction":["B1.2-S03-P1","B1.2-S03-P2","B1.2-S03-P3","B1.2-S03-P4","B1.2-S03-P5"],"interaction_after_cue":null,"interaction_id":null,"post_interaction_cues":[]}},{"id":"S04","title":"What the agent does, and on whose procedures","paragraphs":[{"cue":"B1.2-S04-P1","speaker":"Emilia","text":"Let us answer the first message now: who is the agent on Thursday's worksite? The regulation says the operator designates, in each of its establishments and among its own staff, radiation protection agents who carry out the physical control tasks listed under 23.1.5 a). For their physical control tasks, these agents depend functionally on the service. And they have followed the training described in article 30.4. The industrial radiography decree makes this concrete for us: on every worksite the company designates an agent from the industrial radiographers present who belong to its staff and have followed that training.","screen_text":["Agents designated among own staff · functionally under the service · trained (30.4)","Every worksite: one agent from the trained radiographers present"],"start_visual":"DOC-PLANNING page: the designated-agent line is filled 'Daniel' at the last sentence.","beats":[{"at":"designates, in each of its establishments","show":"Planning page"},{"at":"on every worksite the company designates","show":"Line filled: 'Designated agent: Daniel'"}],"documents":["DOC-PLANNING"],"clip":"B1.2-S04-P1"},{"cue":"B1.2-S04-P2","speaker":"Emilia","text":"So the answer is not 'the safety department'. All our radiographers are trained as agents. For Thursday, the company names one of the radiographers who will actually be there. That designation is a company decision about a particular worksite, recorded in the planning, and it is my job to make sure it has been made and that the person is prepared for that installation and that task.","screen_text":["A company decision for a particular worksite — recorded"],"start_visual":"Daniel beside the planning sheet; Emilia marker.","beats":[{"at":"not 'the safety department'","show":"Text label"},{"at":"recorded in the planning","show":"Planning line pulses"}],"characters":["Daniel"],"clip":"B1.2-S04-P2"},{"cue":"B1.2-S04-P3","speaker":"Emilia","text":"What does the designated agent do? The regulation lists frequent and systematic radiation-protection tasks in the installations. Three of them matter most for today. Checking that the measures, rules and work procedures for radiation protection are being followed. Checking that the protective means and provisions, the measuring instruments and the dosimeters are available, in good working order and correctly used. And informing the head of the physical control service and the recognised expert of every abnormal situation. The list closes with one sentence I want you to remember: these tasks are carried out on the basis of instructions and procedures approved by a recognised expert in physical control.","screen_text":["Checks: rules and procedures followed · protective means, instruments and dosimeters available and working · abnormal situations reported","On the basis of procedures approved by a recognised expert"],"start_visual":"Daniel uses the CURRENT check sheet DOC-CHECK-SHEET; the PROPOSED copy beside it carries a visibly distinct 'PROPOSED — not approved' marker.","beats":[{"at":"Checking that the measures, rules","show":"Check sheet line 1"},{"at":"Checking that the protective means","show":"Daniel's handheld, EPD and TLD in view"},{"at":"informing the head of the physical control service","show":"Text: 'report abnormal situations'"},{"at":"approved by a recognised expert","show":"Approval line enlarged on the procedure page"}],"documents":["DOC-CHECK-SHEET","DOC-PROCEDURE-RECORD"],"equipment":["EQ-HANDHELD-SURVEY","EQ-EPD-LEFT-CHEST","EQ-TLD-RIGHT-UPPER-CHEST"],"clip":"B1.2-S04-P3"},{"cue":"B1.2-S04-P4","speaker":"Emilia","text":"That last sentence connects the agent and the expert without confusing them. The agent does the checking; the expert has approved how the checking is done. When Daniel checks a survey meter against our pre-use procedure and records the result, that record is his observation on that day. It is not a new expert judgement, and it does not need to be. Equally, the expert's approval of the procedure tells us how a check is to be done, and the record tells us whether a particular check was actually done. Each piece of evidence answers its own question.","screen_text":["Record = his observation that day","Approval = how the check is done; record = that it was done"],"start_visual":"Close-up: one completed line on the current sheet; then the approval line; only the specific sentence enlarged.","beats":[{"at":"that record is his observation","show":"Record line"},{"at":"tells us how a check is to be done","show":"Approval line"}],"clip":"B1.2-S04-P4"}],"sequence":{"cues_before_interaction":["B1.2-S04-P1","B1.2-S04-P2","B1.2-S04-P3","B1.2-S04-P4"],"interaction_after_cue":null,"interaction_id":null,"post_interaction_cues":[]}},{"id":"S05","title":"The revised check form: who approves it?","paragraphs":[{"cue":"B1.2-S05-P1","speaker":"Emilia","text":"Now the second message: can the team start using the revised pre-use check form? Here is how the revision came about. Daniel noticed that one sentence on the current form can be read two ways—whether the meter's response is checked before or after the device is positioned. He wrote a clearer sentence and suggested we use it. That is exactly the kind of contribution I want from a radiographer, and I told him so.","screen_text":["Daniel's proposal: one clearer sentence"],"start_visual":"Daniel offers the PROPOSED sheet to Emilia (supplied poses: Daniel holding the sheet, Emilia receiving); close-up on the ambiguous sentence and the proposed replacement.","beats":[{"at":"Daniel noticed that one sentence","show":"Close-up: ambiguous sentence"},{"at":"He wrote a clearer sentence","show":"Proposed sentence beside it, marked PROPOSED"}],"documents":["DOC-CHECK-SHEET"],"characters":["Daniel","Emilia"],"clip":"B1.2-S05-P1"},{"cue":"B1.2-S05-P2","speaker":"Emilia","text":"But a good suggestion is still a proposal. The form belongs to a radiation-protection procedure, and the agents carry out their checks on the basis of procedures approved by the recognised expert. So I ask Daniel to describe the ambiguity with an example, I bring the proposal to the expert of our recognised organisation, and the team keeps using the current version until the revised one has been examined and approved. Nobody on a worksite should have to guess which form applies.","screen_text":["Proposal → expert examines and approves → then in use","Until then: the current version applies"],"start_visual":"Two sheets: CURRENT (in use) and PROPOSED (not approved) with their status markers.","beats":[{"at":"a good suggestion is still a proposal","show":"PROPOSED marker pulses"},{"at":"keeps using the current version","show":"CURRENT marker pulses"}],"clip":"B1.2-S05-P2"},{"cue":"B1.2-S05-P3","speaker":"Emilia","text":"You can see three responsibilities working together without merging. The radiographer raises a practical problem. I coordinate the follow-up and keep the versions apart. The expert examines and approves the revised procedure.","screen_text":["Radiographer raises · head of service coordinates · expert approves"],"start_visual":"Three markers: Daniel, Emilia, external expert frame.","beats":[{"at":"The radiographer raises","show":"Daniel"},{"at":"I coordinate","show":"Emilia"},{"at":"The expert examines and approves","show":"External frame"}],"clip":"B1.2-S05-P3"}],"interaction":{"id":"B1.2-I01","type":"single_choice","prompt_spoken_once":"Before the team may use the revised radiation-protection check form, who approves it?","behaviour":"The prompt is spoken automatically exactly once when the activity opens; the narration lead-in never reads it. Manual 'Hear the question' replay. Each option has its own spoken and written feedback (evidence, then next step). Retry without replaying narration; keyboard equivalents (labelled radio controls, Check, Try again, Continue); no auto-advance; no colour-only cues; no timer. Feedback never invents a dose, cause, approval or successful contact.","situation_visible_text":"Daniel's proposed revision of the pre-use check form is on the desk, marked PROPOSED.","options":[{"id":"expert","text":"The recognised expert of the organisation we contract.","correct":true,"feedback":{"spoken":"Yes. The agents' checks are carried out on the basis of instructions and procedures approved by a recognised expert in physical control, and because we have no such expert on our staff, those approval tasks are entrusted by contract to the recognised organisation. Daniel's idea improves the form; the expert's examination and approval make it the procedure we use—and until then the current sheet stays in use.","screen":"Approval: the recognised expert (contracted organisation). Current form until then."},"clip":"B1.2-I01-expert"},{"id":"daniel","text":"Daniel, because he uses the form most and wrote the revision.","correct":false,"feedback":{"spoken":"Daniel's knowledge of the form is exactly why the revision is good, and his proposal is the right first step. But familiarity does not transfer the expert's approval function to the agent. His revision stays a proposal, marked as such, until a recognised expert has examined and approved it.","screen":"Daniel proposes; he does not approve."},"clip":"B1.2-I01-daniel"},{"id":"emilia","text":"Emilia, as head of the physical control service.","correct":false,"feedback":{"spoken":"I do something real with it: I coordinate the follow-up, keep the versions apart and bring the proposal to the expert of our organisation. Coordinating is not approving. The examination and approval of radiation-protection procedures are tasks of the recognised expert, which is why they sit with the organisation we contract.","screen":"Head of service coordinates; the expert approves."},"clip":"B1.2-I01-emilia"}],"placement":"Both sheets stay visible with their CURRENT / PROPOSED markers.","clip":"B1.2-I01-prompt"},"sequence":{"cues_before_interaction":["B1.2-S05-P1","B1.2-S05-P2","B1.2-S05-P3"],"interaction_after_cue":"B1.2-S05-P3","interaction_id":"B1.2-I01","post_interaction_cues":[],"rule":"Play cues_before_interaction in order; open the interaction immediately after interaction_after_cue (it speaks its prompt once); post_interaction_cues play only when their condition is met; nothing in post_interaction_cues is spoken before the interaction."}},{"id":"S06","title":"Training has several different jobs to do","paragraphs":[{"cue":"B1.2-S06-P1","speaker":"Emilia","text":"That brings us to Daniel's own message: he passed the agent course, so can he be the agent on his own now? To answer that honestly, I need to separate several things that people lump together as 'training'. They have different purposes, different evidence, and none of them stands in for the others.","screen_text":["Several kinds of 'training' — different purposes, different evidence"],"start_visual":"A chronological preparation path appears beside Emilia (empty stations).","beats":[{"at":"separate several things","show":"Path with four empty stations"}],"clip":"B1.2-S06-P1"},{"cue":"B1.2-S06-P2","speaker":"Emilia","text":"The first thing Daniel received, before he was employed in radiography at all, was our own four-hour initial instruction: how we work, which safety equipment we use and how—dosimeters, survey meters, dose-rate meters, the bunker equipment here and at our clients'. The decree wants that given by a radiographer with at least three years' professional experience who knows our installations. Then comes the general information every exposed worker gets before starting at the workstation—the health risks, the rules of good practice, what the signs mean, what to do in an emergency, and so on. It is written down, and we refresh it at least once a year. The full list is in the reference reader; you do not need to recite it, you need to recognise it when it is missing.","screen_text":["Station 1: company initial instruction (4 h) — safety equipment, bunker equipment","Station 2: general information before the workstation — refreshed yearly"],"start_visual":"Station 1 fills with a document occasion (initial instruction record); station 2 with the general-information sheet; Daniel's handheld, EPD and TLD shown at 'dosimeters, survey meters'.","beats":[{"at":"four-hour initial instruction","show":"Station 1"},{"at":"dosimeters, survey meters, dose-rate meters","show":"Equipment close-up: handheld, EPD, TLD"},{"at":"general information every exposed worker gets","show":"Station 2"},{"at":"reference reader","show":"Reference reader control indicated (optional overlay)"}],"equipment":["EQ-HANDHELD-SURVEY","EQ-EPD-LEFT-CHEST","EQ-TLD-RIGHT-UPPER-CHEST"],"clip":"B1.2-S06-P2"},{"cue":"B1.2-S06-P3","speaker":"Emilia","text":"Next, training for the actual job. In addition to that information, the operator organises training aimed specifically at the person's workstation or function and at the devices and substances he uses. It happens on recruitment, when someone changes function, when a work tool is changed or introduced, and when a new technology arrives—and it is repeated as needs require and documented. So when Daniel moves from our X-ray sets to a gamma projector he has not used before, experience with one device does not settle the question for the other.","screen_text":["Station 3: workstation / function training — on recruitment, change of function, new tool or technology; documented"],"start_visual":"Station 3 fills; the X-ray generator and gamma projector images side by side at 'gamma projector he has not used before'.","beats":[{"at":"training aimed specifically at the person's workstation","show":"Station 3"},{"at":"gamma projector he has not used before","show":"EQ-XRAY-GENERATOR and EQ-GAMMA-PROJECTOR side by side, labelled"}],"equipment":["EQ-XRAY-GENERATOR","EQ-GAMMA-PROJECTOR"],"clip":"B1.2-S06-P3"},{"cue":"B1.2-S06-P4","speaker":"Emilia","text":"Then the agent course, which is what Daniel's message is about. The general regulation sets the floor: a certificate based on a passed knowledge test, proving a theoretical basic training of at least eight hours supplemented by at least eight hours for class two establishments, together with relevant practical experience in physical control for the type of installation, and continuing training afterwards. The Agency's training regulation fills that in for our kind of company. Because we work with both X-ray devices and sealed sources, our radiographers follow the combined route: twelve hours of basic training and twelve hours of supplementary training covering devices and sources together, rather than the eight-plus-eight of a devices-only or sources-only route. The theory is supplemented by practical training or experience in the installation type, the programme is approved by a recognised expert, and class two agents follow at least four hours of continuing training a year. For radiographers the decree places the agent training within three months of entering service, and without it nobody manipulates gamma or X-ray equipment.","screen_text":["Station 4: agent course — certificate from a passed knowledge test; practical training/experience; continuing training","Within three months of entering service; no equipment manipulation without it"],"start_visual":"Station 4 fills with DOC-CERT-AGENT; the training regulation extract thumbnail for the combined route.","beats":[{"at":"Then the agent course","show":"Station 4 with certificate"},{"at":"combined route","show":"Extract thumbnail: 12 + 12 h (training regulation)"},{"at":"within three months","show":"Text label (expert decision D01 noted in author notes)"}],"documents":["DOC-CERT-AGENT","DOC-REG-EXTRACT"],"clip":"B1.2-S06-P4"},{"cue":"B1.2-S06-P5","speaker":"Emilia","text":"And finally designation. Training makes someone eligible; the certificate is one prerequisite among several, not a licence to act. The company's decision to name him as the agent for a worksite is a separate act, recorded in the planning. All of this happens during working time and at the operator's cost. For external workers coming from another company, the allocation between their employer and us needs its own attention; that is a later lesson, so I will not hide it inside Daniel's case.","screen_text":["Designation: a separate company decision — recorded in the planning"],"start_visual":"A separate station, set apart from the path: DOC-PLANNING designated-agent line.","beats":[{"at":"And finally designation","show":"Separate station: planning line"},{"at":"external workers","show":"Text: 'external workers → later lesson'"}],"documents":["DOC-PLANNING"],"clip":"B1.2-S06-P5"}],"sequence":{"cues_before_interaction":["B1.2-S06-P1","B1.2-S06-P2","B1.2-S06-P3","B1.2-S06-P4","B1.2-S06-P5"],"interaction_after_cue":null,"interaction_id":null,"post_interaction_cues":[]}},{"id":"S07","title":"What does Daniel's certificate establish?","paragraphs":[{"cue":"B1.2-S07-P1","speaker":"Emilia","text":"Daniel's folder currently holds one document: the certificate from his agent course, based on a passed knowledge test. It is a real achievement and I do not want him to feel otherwise. But look at the separate requirements we just walked through. The certificate answers one of them—the theory. It says nothing about practical training or experience with our projectors, nothing about the workplace instruction for our installations, and nothing about a company decision to designate him. An empty card is not evidence of failure either; it just means I have to find out.","screen_text":["Certificate: theory — knowledge test passed","Still to establish: practical experience · workstation instruction · designation"],"start_visual":"DOC-CERT-AGENT full page; close-up on the one highlighted purpose line 'theoretical training — knowledge test passed'; the path from S06 beside it with stations 3 and the designation station marked 'to establish'.","beats":[{"at":"one document","show":"Certificate full page"},{"at":"The certificate answers one of them","show":"Close-up: highlighted purpose line"},{"at":"An empty card is not evidence of failure","show":"Path stations marked 'to establish', not red"}],"documents":["DOC-CERT-AGENT"],"clip":"B1.2-S07-P1"},{"cue":"B1.2-S07-P2","speaker":"Emilia","text":"So my reply to Daniel is not yes and not no. It is: well done, here is what we still need to establish, and here is who decides.","screen_text":["Well done — here is what we still need to establish, and who decides"],"start_visual":"Emilia to camera.","beats":[{"at":"not yes and not no","show":"Label"}],"clip":"B1.2-S07-P2"}],"interaction":{"id":"B1.2-I02","type":"single_choice","prompt_spoken_once":"Daniel's folder holds only his agent-course certificate. On its own, what does that certificate establish?","behaviour":"The prompt is spoken automatically exactly once when the activity opens; the narration lead-in never reads it. Manual 'Hear the question' replay. Each option has its own spoken and written feedback (evidence, then next step). Retry without replaying narration; keyboard equivalents (labelled radio controls, Check, Try again, Continue); no auto-advance; no colour-only cues; no timer. Feedback never invents a dose, cause, approval or successful contact.","situation_visible_text":"Certificate: theoretical training — knowledge test passed.","options":[{"id":"test","text":"That he passed the theoretical knowledge test.","correct":true,"feedback":{"spoken":"Exactly. A certificate based on a passed knowledge test is how the regulation wants the theoretical training proved, and that is what it proves. It is one prerequisite. Practical training or experience in our installation type, the workplace instruction for our equipment and the company's designation are separate pieces of evidence that we now establish—each with its own document on the path.","screen":"Correct: the theory test. The other stations need their own evidence."},"clip":"B1.2-I02-test"},{"id":"designated","text":"That he is now our designated agent.","correct":false,"feedback":{"spoken":"The certificate does establish something: the theory requirement is met, and that is one of the conditions for being designated. It does not establish his practical training, his instruction for our installations, or a decision by the company. Designation is that company decision, made for a particular worksite among the trained radiographers present and recorded in the planning. Nobody becomes the designated agent by filing a certificate.","screen":"Theory met; designation is a separate recorded company decision."},"clip":"B1.2-I02-designated"},{"id":"complete","text":"That his training for our equipment is complete.","correct":false,"feedback":{"spoken":"The agent course is theoretical training in radiation protection, and the certificate is good evidence of it. Training for his actual workstation—our projectors, our X-ray sets, our procedures—is a separate duty with its own occasions, documented separately on the path. The certificate does not tell me whether that has happened.","screen":"Theory ≠ workstation training; that is documented separately."},"clip":"B1.2-I02-complete"}],"placement":"Certificate and path stay visible.","clip":"B1.2-I02-prompt"},"sequence":{"cues_before_interaction":["B1.2-S07-P1","B1.2-S07-P2"],"interaction_after_cue":"B1.2-S07-P2","interaction_id":"B1.2-I02","post_interaction_cues":[],"rule":"Play cues_before_interaction in order; open the interaction immediately after interaction_after_cue (it speaks its prompt once); post_interaction_cues play only when their condition is met; nothing in post_interaction_cues is spoken before the interaction."}},{"id":"S08","title":"One person, more than one function","paragraphs":[{"cue":"B1.2-S08-P1","speaker":"Emilia","text":"Suppose a few weeks have passed. Daniel's practical experience and workplace instruction are documented, and the company has designated him as the agent on a worksite. He is now both a radiographer doing the radiography and the agent for that site. When he positions the device and makes the exposure, the operational duties of a radiographer apply. When he checks that the controlled area is set up as the procedure requires, he is exercising the agent function under the approved procedure. Same person, two functions, and we can say which one is at work in each decision.","screen_text":["Daniel — radiographer (operational duties)","Daniel — designated agent (checks under the procedure)"],"start_visual":"Daniel at a worksite with the X-ray generator: small role caption appears only when each function matters.","beats":[{"at":"positions the device and makes the exposure","show":"Caption 'radiographer'"},{"at":"checks that the controlled area is set up","show":"Caption 'designated agent'; handheld in hand"}],"equipment":["EQ-XRAY-GENERATOR","EQ-HANDHELD-SURVEY"],"characters":["Daniel"],"clip":"B1.2-S08-P1"},{"cue":"B1.2-S08-P2","speaker":"Emilia","text":"The same is true higher up the chart. I am also the company's quality and safety manager, and I have been formally appointed to head the physical control service. The letters on my business card do not create either function; the appointments do. In a small company one name appears in several places. That is legitimate when the conditions for each function are met. What we avoid is the shortcut of assuming that a senior title brings every power on the chart with it—including, as you will see shortly, powers that belong to a completely different appointment.","screen_text":["Emilia — quality and safety manager","Emilia — head of the physical control service (appointed)"],"start_visual":"Emilia with two captions in turn; no business-card graphic.","beats":[{"at":"I am also the company's quality and safety manager","show":"Caption 1"},{"at":"formally appointed to head","show":"Caption 2"},{"at":"a completely different appointment","show":"Both captions fade"}],"clip":"B1.2-S08-P2"}],"sequence":{"cues_before_interaction":["B1.2-S08-P1","B1.2-S08-P2"],"interaction_after_cue":null,"interaction_id":null,"post_interaction_cues":[]}},{"id":"S09","title":"When a check does not pass","paragraphs":[{"cue":"B1.2-S09-P1","speaker":"Emilia","text":"Now a situation rather than a document. Daniel is the designated agent on a worksite. Before the first exposure, he performs the pre-use check on the survey meter, and the meter fails its function check. The device has not been positioned and no exposure has been made. We know the observation. We do not know the cause, and we have no reason to suspect anyone has been exposed. That is enough to require action, and not enough to invent a diagnosis.","screen_text":["Observed: meter failed its function check","Exposure: not started","Cause: unknown"],"start_visual":"Worksite before the first exposure: close-up of the correct Tracerco-form handheld EQ-HANDHELD-SURVEY on the case; Daniel's EPD (left chest) and TLD (right upper chest) remain visible; device not positioned. HELD badge: 'Exposure held — meter failed its function check'.","beats":[{"at":"the meter fails its function check","show":"Handheld close-up; no reading shown"},{"at":"no exposure has been made","show":"HELD badge appears"},{"at":"We do not know the cause","show":"NOT ESTABLISHED badge: cause"}],"equipment":["EQ-HANDHELD-SURVEY","EQ-EPD-LEFT-CHEST","EQ-TLD-RIGHT-UPPER-CHEST"],"characters":["Daniel"],"clip":"B1.2-S09-P1"},{"cue":"B1.2-S09-P2","speaker":"Emilia","text":"Three provisions come together here. Every worker and external worker must follow the instructions and this regulation; he is forbidden to expose himself unnecessarily or to damage or remove protective means; and he reports immediately, at least to the physical control service, every irregularity or defect in the protective means. You do not need an agent title for that duty—it belongs to everyone. The agent's list adds a specific task: informing the head of the physical control service and the recognised expert of every abnormal situation. And the industrial radiography decree tells radiographers to stop the radiography when safe working is not possible and to report that immediately, with the reason, to their hierarchical superior, to the head of the physical control service and to the client's contact person.","screen_text":["Everyone: report defects immediately, at least to the service","Agent: inform head of service and expert","Radiographers: stop when unsafe; tell superior, head of service, client contact"],"start_visual":"Three short labels in turn, parallel (no arrows).","beats":[{"at":"Every worker and external worker","show":"Label 1"},{"at":"The agent's list adds","show":"Label 2"},{"at":"the industrial radiography decree tells radiographers","show":"Label 3"}],"clip":"B1.2-S09-P2"},{"cue":"B1.2-S09-P3","speaker":"Emilia","text":"So I teach neither 'leave it for the expert's next visit' nor 'fix it yourself because you are the agent'. Both miss the organisation. Take the protective action your approved instruction assigns to you—here, the exposure does not start. Communicate without delay to everyone the rules name—your supervisor, me as head of service, the client's contact person—and make sure the expert hears through our service. Keep the boundary around technical work you are not authorised or competent to do. And describe what you saw, not what you suppose. Our procedure for this case is explicit, and I am telling you its condition so you do not have to guess: do not start the exposure, call the service on the worksite line, and the service makes sure the expert is informed.","screen_text":["Our procedure: do not start · call the service on the worksite line · service informs the expert"],"start_visual":"Daniel with his phone (supplied pose) beside the case; procedure line close-up.","beats":[{"at":"Our procedure for this case is explicit","show":"Procedure line close-up"}],"characters":["Daniel"],"clip":"B1.2-S09-P3"}],"sequence":{"cues_before_interaction":["B1.2-S09-P1","B1.2-S09-P2","B1.2-S09-P3"],"interaction_after_cue":null,"interaction_id":null,"post_interaction_cues":[]},"status_badges":[{"kind":"held","label":"Exposure held","explanation":"The survey meter failed its pre-use function check; under the procedure the exposure does not start and the service is called."},{"kind":"not_established","label":"Cause not established","explanation":"Whether it is the meter, the battery or something else is not known; nobody has been exposed; no reading or cause is shown."}]},{"id":"S10","title":"Choose Daniel's response","paragraphs":[{"cue":"B1.2-S10-P1","speaker":"Emilia","text":"Keep the facts in mind: Daniel is the designated, prepared agent; the survey meter failed its function check; no exposure has been made; the cause is unknown; our procedure says do not start and call the service.","screen_text":["Agent · meter failed check · no exposure · cause unknown · procedure: do not start, call the service"],"start_visual":"Short options beside Daniel's phone and check sheet; the HELD badge large.","beats":[{"at":"Keep the facts in mind","show":"Fact list visible"}],"clip":"B1.2-S10-P1"}],"interaction":{"id":"B1.2-I03","type":"single_choice","prompt_spoken_once":"The survey meter fails its pre-use function check before the first exposure. What does Daniel do?","behaviour":"The prompt is spoken automatically exactly once when the activity opens; the narration lead-in never reads it. Manual 'Hear the question' replay. Each option has its own spoken and written feedback (evidence, then next step). Retry without replaying narration; keyboard equivalents (labelled radio controls, Check, Try again, Continue); no auto-advance; no colour-only cues; no timer. Feedback never invents a dose, cause, approval or successful contact.","options":[{"id":"stop_report","text":"Keep the exposure from starting and report the failed check to the service at once.","correct":true,"feedback":{"spoken":"Yes. The protective action his instruction assigns is to hold the exposure. The duty to report an irregularity in the protective means immediately, at least to the physical control service, follows directly; as the radiographer who stopped the work he also tells his supervisor Luc and the client's contact person, and as agent he informs me, and I contact the recognised expert and confirm back when that contact has succeeded. He describes the failed check and the status, not a cause or a dose he has not established.","screen":"Hold the exposure; report at once to the service, supervisor and client contact; the service reaches the expert."},"clip":"B1.2-I03-stop_report"},{"id":"alarm","text":"Start the exposure and rely on his personal dosimeter alarm instead of the meter.","correct":false,"feedback":{"spoken":"The dosimeter on his chest is doing a real job: it follows his own dose. The survey check does a different one—it confirms the radiation situation around the device and at the boundary, for everyone. Starting without a working meter is exactly the exposure the decree tells him to stop, and it would leave the defect unreported.","screen":"Dosimeter ≠ survey meter; the exposure stays held and the defect is reported."},"clip":"B1.2-I03-alarm"},{"id":"log","text":"Note the failure in the daily log for the expert's next scheduled visit.","correct":false,"feedback":{"spoken":"Writing it down is right—the log entry will matter. What it cannot do is meet the duty to report immediately. The expert's scheduled visit is not the route for an abnormal situation; the head of service and the expert need to hear now, through the agreed route, so the next decision can be taken by the right people.","screen":"Record it, and report now; a later visit is not the route."},"clip":"B1.2-I03-log"}],"placement":"HELD badge and the facts list stay visible; Daniel with phone.","clip":"B1.2-I03-prompt"},"sequence":{"cues_before_interaction":["B1.2-S10-P1"],"interaction_after_cue":"B1.2-S10-P1","interaction_id":"B1.2-I03","post_interaction_cues":[],"rule":"Play cues_before_interaction in order; open the interaction immediately after interaction_after_cue (it speaks its prompt once); post_interaction_cues play only when their condition is met; nothing in post_interaction_cues is spoken before the interaction."}},{"id":"S11","title":"A handover the next person can act on","paragraphs":[{"cue":"B1.2-S11-P1","speaker":"Emilia","text":"Here is how I would want Daniel's call to sound, and we'll watch the record line update as he speaks. 'Emilia, it's Daniel at the pipe-rack site. During the pre-use check the survey meter failed its function check. We have not positioned the device and no exposure has been made. I've held the exposure as the procedure says. I've told Luc and the client's contact person; I'm calling you now. I haven't touched the device.' And my side of the call ends with: 'Understood—I'm contacting the expert now, and I'll call you back about the meter.' Twenty minutes later I ring Daniel back: 'I've spoken to the expert; she has the facts and she'll look at the meter question this afternoon.' Only at that second call can we say that everyone the rules name has actually been reached; until then the expert's information was pending, and the record says so.","screen_text":["Observed · Done · Contacted · Unknown"],"start_visual":"Daniel reports (phone pose); Emilia listens (phone pose — asset dependency flagged if no phone pose exists); the event record DOC-EVENT-RECORD lines fill as the facts are spoken: observation, status, contacted (expert: pending → reached).","beats":[{"at":"the survey meter failed its function check","show":"Record line: observation"},{"at":"I've held the exposure","show":"Record line: status HELD"},{"at":"I've told Luc","show":"Record line: contacted — Luc, client contact"},{"at":"I'm contacting the expert now","show":"Record line: expert — pending"},{"at":"I've spoken to the expert","show":"Record line: expert — reached (time)"}],"documents":["DOC-EVENT-RECORD"],"characters":["Daniel","Emilia"],"clip":"B1.2-S11-P1"},{"cue":"B1.2-S11-P2","speaker":"Emilia","text":"That call is complete without pretending to know the answer. The receiver can tell what was seen, what has been done, who has been contacted, who is still being contacted, and what is still unknown. Nobody has claimed a cause or a dose. Those four parts—observed, done, contacted, unknown—will come back in the lesson about abnormal events and statutory reporting, where the time limits and the Agency's criteria get their own treatment. Today the point is organisational: a clear handover lets the person with the next responsibility act.","screen_text":["A handover the next person can act on"],"start_visual":"Record page complete; Emilia to camera.","beats":[{"at":"Those four parts","show":"Four headings pulse"}],"clip":"B1.2-S11-P2"},{"cue":"B1.2-S11-P3","speaker":"Emilia","text":"Now look at a different ending to the same call. Daniel's draft handover is on the record, and its last sentence reads: 'The battery must be faulty.' Everything above that line is accurate.","screen_text":["Draft last sentence: 'The battery must be faulty.'"],"start_visual":"DOC-EVENT-RECORD draft with the last line highlighted; HELD badge still visible.","beats":[{"at":"its last sentence reads","show":"Last line highlighted"}],"documents":["DOC-EVENT-RECORD"],"clip":"B1.2-S11-P3"}],"interaction":{"id":"B1.2-R01","type":"single_choice","prompt_spoken_once":"Which ending keeps this handover accurate?","behaviour":"The prompt is spoken automatically exactly once when the activity opens; the narration lead-in never reads it. Manual 'Hear the question' replay. Each option has its own spoken and written feedback (evidence, then next step). Retry without replaying narration; keyboard equivalents (labelled radio controls, Check, Try again, Continue); no auto-advance; no colour-only cues; no timer. Feedback never invents a dose, cause, approval or successful contact.","situation_visible_text":"Draft handover: meter failed its function check; exposure held; Luc and client contact told; service called. Last line: 'The battery must be faulty.'","options":[{"id":"not_established","text":"'The meter failed its function check; the cause is not yet established.'","correct":true,"feedback":{"spoken":"Yes. That ending reports what Daniel observed and marks the cause as open, which is exactly what the expert needs to decide what to look at this afternoon. The handover stays true if the cause turns out to be the battery, the meter or something else, and the held status stays visible until the service resolves it.","screen":"Observation stated; cause open; status held."},"clip":"B1.2-R01-not_established"},{"id":"battery","text":"'The battery must be faulty, so I'll swap it and carry on.'","correct":false,"feedback":{"spoken":"A suspicion can be useful if it is labelled as one—'I suspect the battery' with a reason. Stated as a fact it invents a cause nobody has established, and 'carry on' quietly lifts a hold that only the service, under the procedure, can lift. The accurate ending keeps the cause open and the exposure held.","screen":"Suspicion ≠ cause; the hold is not Daniel's to lift."},"clip":"B1.2-R01-battery"},{"id":"probably_fine","text":"'The meter is probably fine, so we can start if you agree.'","correct":false,"feedback":{"spoken":"This ending removes the one fact the call exists for: the meter failed its function check. 'Probably fine' is a guess that contradicts the observation, and asking for agreement to start skips the procedure's route through the service and the expert. Keep the observation and leave the cause open.","screen":"Keep the observation; no start on a guess."},"clip":"B1.2-R01-probably_fine"}],"replaces":"B1.2 S11 R01 (free-text rehearsal) — replaced one-for-one; Daniel reports, Emilia listens, the record line updates","placement":"After S11-P3; on a correct answer the record's last line updates to the accurate sentence.","clip":"B1.2-R01-prompt"},"sequence":{"cues_before_interaction":["B1.2-S11-P1","B1.2-S11-P2","B1.2-S11-P3"],"interaction_after_cue":"B1.2-S11-P3","interaction_id":"B1.2-R01","post_interaction_cues":[],"rule":"Play cues_before_interaction in order; open the interaction immediately after interaction_after_cue (it speaks its prompt once); post_interaction_cues play only when their condition is met; nothing in post_interaction_cues is spoken before the interaction."}},{"id":"S12","title":"Safety and security: a different role with a similar name","paragraphs":[{"cue":"B1.2-S12-P1","speaker":"Emilia","text":"Before we finish, one role name that is easy to confuse with ours. Belgium has a separate royal decree of 17 March 2024 on the security of radioactive substances and certain nuclear materials—colleagues call it RAMAS. Radiation protection is about controlling exposure. Security is about preventing unauthorised removal, malicious acts and misuse of radioactive substances. The two are connected, and in our work they meet, but their responsibilities are not interchangeable.","screen_text":["Radiation protection: controlling exposure","Security: preventing removal, malicious acts, misuse"],"start_visual":"Two connected workplace examples with equal weight: left, Daniel checking the perimeter at a worksite (protection); right, the company's source store door with its inventory sheet (security). Both real scenes, no cards.","beats":[{"at":"Radiation protection is about controlling exposure","show":"Left scene: Daniel with handheld at the perimeter"},{"at":"Security is about preventing","show":"Right scene: source store door, inventory sheet (no confidential arrangement shown)"}],"equipment":["EQ-HANDHELD-SURVEY","EQ-GAMMA-PROJECTOR"],"characters":["Daniel"],"clip":"B1.2-S12-P1"},{"cue":"B1.2-S12-P2","speaker":"Emilia","text":"Where does the security decree apply? To radioactive substances, whether or not placed in a device, above the exemption levels, in establishments classified in class one, two or three—and also to radioactive substances used in a mobile installation or in temporary work licensed under article 5.7 of the general regulation. That second sentence is us: our gamma projectors contain sealed sources, and we take them to worksites. An X-ray set contains no radioactive substance, so an X-ray-only activity is not brought under this decree merely because it produces ionising radiation. What applies to a given source depends on its category under the decree, which is determined from the licensed activity, not from a meter reading or from the words 'class two'. For the lowest categories, four and five, only a few of the decree's articles apply.","screen_text":["Applies to radioactive substances — incl. mobile/temporary use","X-ray set: no radioactive substance"],"start_visual":"Right scene: gamma projector image in the store; left: X-ray generator image with 'no radioactive substance' label.","beats":[{"at":"our gamma projectors contain sealed sources","show":"Projector image highlighted"},{"at":"An X-ray set contains no radioactive substance","show":"X-ray image with label"}],"equipment":["EQ-GAMMA-PROJECTOR","EQ-XRAY-GENERATOR"],"clip":"B1.2-S12-P2"},{"cue":"B1.2-S12-P3","speaker":"Emilia","text":"Now the role. Under the decree, the operator appoints within its establishment or organisation at least one delegate for radiological security—the ARB—who works for the operator in a durable way, whether or not as an employee. That appointment is subject to the Agency's approval; the Agency may approve it with or without conditions or refuse it, taking into account the person's qualifications, experience, security training, and his status, position and means within the establishment. The ARB sets up and maintains the radiological security system on behalf of and under the responsibility of the operator, and he carries out this task, where relevant, in consultation with the head of the physical control service. So the ARB and I talk to each other. We are not the same appointment.","screen_text":["ARB — appointed by the operator, approved by the Agency","Consults the head of the physical control service"],"start_visual":"Right scene gains an 'ARB' role caption (no new face); a consultation line to Emilia's marker; FANC logo at 'Agency's approval'.","beats":[{"at":"delegate for radiological security","show":"ARB caption"},{"at":"subject to the Agency's approval","show":"FANC logo appears outside the company frame"},{"at":"in consultation with the head of the physical control service","show":"Consultation line to Emilia"}],"equipment":["EQ-FANC-LOGO"],"clip":"B1.2-S12-P3"},{"cue":"B1.2-S12-P4","speaker":"Emilia","text":"One more thing you should know even at this introductory stage. The decree says that anyone who observes a malicious act must immediately inform the operator or the ARB. That duty belongs to every person, whatever their title. The later lesson on abnormal events will show how security incidents are reported onward. For today, notice when a request is for a separate role rather than one more routine task.","screen_text":["Anyone who observes a malicious act informs the operator or the ARB immediately"],"start_visual":"Text label only.","beats":[{"at":"anyone who observes a malicious act","show":"Label"}],"clip":"B1.2-S12-P4"}],"sequence":{"cues_before_interaction":["B1.2-S12-P1","B1.2-S12-P2","B1.2-S12-P3","B1.2-S12-P4"],"interaction_after_cue":null,"interaction_id":null,"post_interaction_cues":[]}},{"id":"S13","title":"Does the agent designation make Daniel the ARB?","paragraphs":[{"cue":"B1.2-S13-P1","speaker":"Emilia","text":"Two appointment documents sit side by side on my desk: the planning line that records Daniel's designation as radiation protection agent, and the outline of an ARB appointment with its field for the Agency's approval. Same company, two different decrees behind the two pieces of paper.","screen_text":["Planning line: designated agent (radiation protection)","ARB appointment: operator's decision, Agency approval (security decree)"],"start_visual":"Two document purposes side by side: DOC-PLANNING designated-agent line; an ARB appointment letter outline (role only, Agency approval field).","beats":[{"at":"the planning line","show":"Planning line"},{"at":"the outline of an ARB appointment","show":"Appointment outline with 'Agency approval' field"}],"documents":["DOC-PLANNING"],"clip":"B1.2-S13-P1"}],"interaction":{"id":"B1.2-I04","type":"single_choice","prompt_spoken_once":"Daniel is now a designated radiation protection agent. Does that make him our delegate for radiological security?","behaviour":"The prompt is spoken automatically exactly once when the activity opens; the narration lead-in never reads it. Manual 'Hear the question' replay. Each option has its own spoken and written feedback (evidence, then next step). Retry without replaying narration; keyboard equivalents (labelled radio controls, Check, Try again, Continue); no auto-advance; no colour-only cues; no timer. Feedback never invents a dose, cause, approval or successful contact.","options":[{"id":"separate","text":"No — the ARB is a separate appointment by the operator that the Agency must approve.","correct":true,"feedback":{"spoken":"Right. Agent training and designation concern radiation protection, recorded on the planning sheet. The security decree requires the operator to appoint at least one ARB, and that appointment is subject to the Agency's approval on the person's qualifications, experience, security training and position—a different document with a different approver. The same person can hold both functions only if the conditions for each are met.","screen":"Two documents, two approvers: planning line (company) vs ARB appointment (Agency approval)."},"clip":"B1.2-I04-separate"},{"id":"covers","text":"Yes — the agent course covers security, so the designation includes the ARB role.","correct":false,"feedback":{"spoken":"The agent course is real and it matters: it is theoretical training in radiation protection under article 30.4. It is not the security qualification the Agency weighs when approving an ARB appointment, and a company designation for radiation protection does not create a security appointment that needs the Agency's approval.","screen":"Agent course = radiation protection; ARB needs its own appointment and approval."},"clip":"B1.2-I04-covers"},{"id":"head","text":"Only if he also becomes head of the physical control service.","correct":false,"feedback":{"spoken":"There is a real link here: the ARB consults the head of the physical control service where relevant, so the two roles talk to each other. But neither creates the other. Heading the service is an appointment under the general regulation; the ARB is a separate appointment under the security decree, each with its own conditions.","screen":"Linked by consultation; neither appointment creates the other."},"clip":"B1.2-I04-head"}],"placement":"Both document purposes stay visible.","clip":"B1.2-I04-prompt"},"sequence":{"cues_before_interaction":["B1.2-S13-P1"],"interaction_after_cue":"B1.2-S13-P1","interaction_id":"B1.2-I04","post_interaction_cues":[],"rule":"Play cues_before_interaction in order; open the interaction immediately after interaction_after_cue (it speaks its prompt once); post_interaction_cues play only when their condition is met; nothing in post_interaction_cues is spoken before the interaction."}},{"id":"S14","title":"Bring the responsibilities together","paragraphs":[{"cue":"B1.2-S14-P1","speaker":"Emilia","text":"Let us return to the three messages. Who is the agent on Thursday? All our radiographers are trained as agents, and the company designates one of those present for that worksite—a decision I make sure has been taken and recorded. Can the team use the revised check form? When the recognised expert has examined and approved it; until then the current version applies. Can Daniel be the agent on his own? His certificate proves the theoretical test; practical experience, workplace instruction and the company's designation have to be established, and then yes.","screen_text":["Thursday's agent: designated and recorded","Revised form: after expert approval","Daniel: theory proved; experience, instruction, designation to establish"],"start_visual":"Brief visual recap: the three documents from S02 each shown with its resolution line.","beats":[{"at":"Who is the agent on Thursday","show":"Planning line filled"},{"at":"Can the team use the revised check form","show":"PROPOSED sheet with 'expert approval pending'"},{"at":"Can Daniel be the agent on his own","show":"Certificate + path stations"}],"clip":"B1.2-S14-P1"},{"cue":"B1.2-S14-P2","speaker":"Emilia","text":"Underneath all three is the same habit: ask what a piece of evidence establishes and who holds the next responsibility. The operator remains responsible for the organisation. I coordinate. The expert approves and evaluates. The agent checks, acts within his instruction and reports. The Agency supervises from outside. And one appointment with a similar-sounding name—the delegate for radiological security—belongs to a different decree with its own approval.","screen_text":["Operator responsible · head of service coordinates · expert approves · agent checks and reports · Agency supervises"],"start_visual":"Wide company scene with the four parties; FANC logo outside.","beats":[{"at":"The operator remains responsible","show":"Company frame"},{"at":"The Agency supervises from outside","show":"FANC logo"}],"equipment":["EQ-FANC-LOGO"],"clip":"B1.2-S14-P2"},{"cue":"B1.2-S14-P3","speaker":"Emilia","text":"In the next lesson we leave the people for the paperwork that lets a company like ours exist at all: the licence, the bunker and its conformity, commissioning, and what happens when something about the installation changes. You will find the same people there, doing the things we have just separated. I'll see you then.","screen_text":["Next: the licence, the bunker, commissioning, changes"],"start_visual":"Bunker exterior image appears as the bridge.","beats":[{"at":"the licence, the bunker","show":"Bunker exterior"}],"equipment":["EQ-BUNKER-REFERENCE"],"clip":"B1.2-S14-P3"}],"sequence":{"cues_before_interaction":["B1.2-S14-P1","B1.2-S14-P2","B1.2-S14-P3"],"interaction_after_cue":null,"interaction_id":null,"post_interaction_cues":[]}}]},{"id":"B1.3","title":"Licence, bunker and commissioning","scenes":[{"id":"S01","title":"Welcome back: from the people to the paperwork","paragraphs":[{"cue":"B1.3-S01-P1","speaker":"Emilia","text":"Welcome back. Last time we separated the people: the company as operator, my coordination, the recognised expert's approvals, the agent's checks, and the Agency looking in from outside. Today we look at the paperwork and the walls that let a company like ours work with radiation at all—and at what each document actually proves.","screen_text":["The installation file — at the control post"],"start_visual":"Emilia at the bunker control post (supplied X-ray control unit image EQ-XRAY-CONTROL-UNIT on the desk) opening the installation file: licence, acceptance report, bunker certificate tabs.","beats":[{"at":"the paperwork and the walls","show":"Installation file opened; bunker gate visible through the control-post window"}],"documents":["DOC-LICENCE","DOC-CERT-BUNKER"],"equipment":["EQ-XRAY-CONTROL-UNIT","EQ-BUNKER-REFERENCE"],"clip":"B1.3-S01-P1"},{"cue":"B1.3-S01-P2","speaker":"Emilia","text":"You will hear the phrase 'everything is approved' on many worksites. By the end of this lesson I want you to be able to replace it with something more precise: what our licence permits, what had to be favourable before an installation could be put into service, what makes a room a bunker in the sense of the law, what effective protection means in the regulation's own terms, and what happens when somebody wants to change something. You will not learn how to test or operate the equipment here. You will learn to say what the evidence supports.","screen_text":["What the licence permits · what was favourable before service · what makes a bunker · effective protection · changes"],"start_visual":"Five tabs of the file named one at a time.","beats":[{"at":"what our licence permits","show":"Tab 1"},{"at":"favourable before an installation","show":"Tab 2"},{"at":"what makes a room a bunker","show":"Tab 3"},{"at":"effective protection","show":"Tab 4"},{"at":"change something","show":"Tab 5"}],"clip":"B1.3-S01-P2"},{"cue":"B1.3-S01-P3","speaker":"Emilia","text":"I will use two installations: our own radiography bunker at the company's premises, and an X-ray cabinet at one of our clients, who inspects small castings in-house. The two sit in different classes, and that difference is a useful way into the licensing rules.","screen_text":["Our bunker (class II) · a client's X-ray cabinet (class III)"],"start_visual":"Bunker exterior image; then a small enclosed X-ray cabinet image (supplied if available, else original render labelled illustration).","beats":[{"at":"our own radiography bunker","show":"Bunker exterior"},{"at":"X-ray cabinet at one of our clients","show":"Cabinet image"}],"equipment":["EQ-BUNKER-REFERENCE"],"clip":"B1.3-S01-P3"}],"sequence":{"cues_before_interaction":["B1.3-S01-P1","B1.3-S01-P2","B1.3-S01-P3"],"interaction_after_cue":null,"interaction_id":null,"post_interaction_cues":[]}},{"id":"S02","title":"Our licence: what it is and what it says","paragraphs":[{"cue":"B1.3-S02-P1","speaker":"Emilia","text":"Start with our own company. The general regulation sorts establishments into classes. Class two includes, among others, installations with X-ray devices whose nominal peak voltage exceeds 200 kilovolts, and establishments that hold or use radioactive sources for industrial radiography without being exempt. Both apply to us, so we are a class two establishment, and class two establishments must hold an establishment and operating licence granted by the Agency.","screen_text":["Class II: X-ray > 200 kV · sources for industrial radiography","Establishment and operating licence from the Agency"],"start_visual":"DOC-LICENCE full page (two-page facsimile, page 1): header 'Establishment and operating licence — teaching excerpt'; FANC logo as issuer shown outside the company, credited.","beats":[{"at":"Class two includes","show":"Classification extract thumbnail beside the page"},{"at":"must hold an establishment and operating licence","show":"Licence page 1 overview"}],"documents":["DOC-LICENCE","DOC-REG-EXTRACT"],"equipment":["EQ-FANC-LOGO"],"clip":"B1.3-S02-P1"},{"cue":"B1.3-S02-P2","speaker":"Emilia","text":"How did the company get it? The application went to the Agency after it had been examined and approved by a recognised expert in physical control of class one or two—either an employee of the future operator or an expert from a recognised organisation. For us that was the organisation we still contract. The regulation lists what the application contains; the point for you is that the dossier describes the establishment, its installations, its sources and its practices in enough detail for the Agency to decide.","screen_text":["Application examined and approved by a recognised expert before submission"],"start_visual":"Close-up: 'examined and approved by: recognised expert (organisation)' field, then back to the page.","beats":[{"at":"examined and approved by a recognised expert","show":"Field close-up"},{"at":"in enough detail for the Agency to decide","show":"Back to page"}],"clip":"B1.3-S02-P2"},{"cue":"B1.3-S02-P3","speaker":"Emilia","text":"When I read our licence, I read it for four things. Which installations and equipment it covers. Which sources, with their characteristics, it allows us to hold. Which practices it permits—industrial radiography in our bunker, radiography on clients' sites. And which conditions are attached. You met the first use of this document in the opening lesson: for a type of practice, the licence granted counts as proof of justification. But the licence is not a general permission to do anything with radiation under the company's name. Anything outside its scope is, for the moment, not licensed—and we will come back to that under 'changes'.","screen_text":["Installations · sources · practices · conditions","Proof of justification of the practice — not blanket permission"],"start_visual":"Four field close-ups in turn (installations; sources placeholders; authorised practices; conditions), then full page.","beats":[{"at":"Which installations and equipment","show":"Field: installations/equipment scope"},{"at":"Which sources","show":"Field: sources (placeholders)"},{"at":"Which practices","show":"Field: authorised practices"},{"at":"which conditions","show":"Field: conditions"},{"at":"not a general permission","show":"Full page with 'scope and conditions' label"}],"clip":"B1.3-S02-P3"}],"sequence":{"cues_before_interaction":["B1.3-S02-P1","B1.3-S02-P2","B1.3-S02-P3"],"interaction_after_cue":null,"interaction_id":null,"post_interaction_cues":[]}},{"id":"S03","title":"A client's cabinet: the class III route","paragraphs":[{"cue":"B1.3-S03-P1","speaker":"Emilia","text":"Now the client. They want to inspect small castings themselves, so they have bought an enclosed X-ray cabinet. Its device does not exceed 200 kilovolts, it is not one of the installations listed for class two, and it is not exempt from declaration and licensing. Installations with devices that can produce ionising radiation and fall outside the class two list, without being exempt, place the establishment in class three. I am telling you that classification as a fact of this example; in real life it is the expert's dossier, not the look of the cabinet, that settles it.","screen_text":["Class III: devices outside the class II list, not exempt"],"start_visual":"Cabinet image; classification extract thumbnail.","beats":[{"at":"Installations with devices","show":"Extract thumbnail"},{"at":"the expert's dossier, not the look of the cabinet","show":"Text label"}],"documents":["DOC-REG-EXTRACT"],"clip":"B1.3-S03-P1"},{"cue":"B1.3-S03-P2","speaker":"Emilia","text":"For class three the route is different. The Agency grants the establishment and operating licence if the operator submits a declaration that meets the conditions set out in the regulation. That declaration, too, is addressed to the Agency in writing or in printable electronic form after it has been examined and approved by a recognised expert of class one or two—an employee of the future operator or an expert of a recognised organisation. The Agency then rules on the declaration within a set period—thirty calendar days after receiving the waste agency's reasoned opinion where that applies, or sixty calendar days after receiving the dossier, or a longer period that it has to justify.","screen_text":["Declaration (expert-approved) → Agency decision within 30 / 60 days or longer with reasons → licence"],"start_visual":"A chronological strip: 'declaration sent' (receipt) → 'Agency decision' (letter with FANC logo) → 'licence'. Only the first step is filled.","beats":[{"at":"the operator submits a declaration","show":"Receipt at step 1"},{"at":"The Agency then rules","show":"Step 2 outlined, empty"}],"equipment":["EQ-FANC-LOGO"],"clip":"B1.3-S03-P2"},{"cue":"B1.3-S03-P3","speaker":"Emilia","text":"So 'we sent the declaration' and 'we hold the licence' are two different statements separated by a decision of the Agency. The client's office manager emails me: 'We sent the declaration for the cabinet last week, so we are licensed now and can start as soon as the installer leaves.'","screen_text":["Sent ≠ licensed"],"start_visual":"The client's email line beside the strip: 'We sent the declaration last week, so we are licensed now.'","beats":[{"at":"The client's office manager emails me","show":"Email line visible"}],"clip":"B1.3-S03-P3"}],"interaction":{"id":"B1.3-I01","type":"single_choice","prompt_spoken_once":"The client writes that the declaration for the X-ray cabinet was sent last week, so they are licensed now. What has the client established?","behaviour":"The prompt is spoken automatically exactly once when the activity opens; the narration lead-in never reads it. Manual 'Hear the question' replay. Each option has its own spoken and written feedback (evidence, then next step). Retry without replaying narration; keyboard equivalents (labelled radio controls, Check, Try again, Continue); no auto-advance; no colour-only cues; no timer. Feedback never invents a dose, cause, approval or successful contact.","situation_visible_text":"Chronology: declaration sent (receipt) → Agency decision (pending) → licence.","options":[{"id":"submitted","text":"That the declaration was submitted; the licence is the Agency's decision.","correct":true,"feedback":{"spoken":"Yes. The receipt is real evidence of the first step: for class three the Agency grants the licence if the declaration meets the regulation's conditions, and it rules within a set period. Until the Agency's decision arrives, the client has no licence to read for scope and conditions—so the next step is to wait for that letter, not to start.","screen":"Submission proved; the licence is the Agency's decision, still pending."},"clip":"B1.3-I01-submitted"},{"id":"granted","text":"That the licence has been granted, because the declaration met the conditions.","correct":false,"feedback":{"spoken":"A declaration that meets the conditions is what the Agency needs in order to grant the licence, and an expert-approved declaration is a solid first step. It is not the licence. The Agency has thirty or sixty calendar days, or longer with justification, to rule. The client is reading the decision into the submission; the chronology shows the gap.","screen":"Conditions met → Agency may grant; the decision is a separate step."},"clip":"B1.3-I01-granted"},{"id":"use_on_arrival","text":"That the cabinet may be used as soon as the licence arrives.","correct":false,"feedback":{"spoken":"Even when the licence arrives, something true has happened—the client may build and fit out under it. But the regulation separates that from putting the installation into service. Commissioning needs a fully favourable acceptance that expressly permits it—the next part of the lesson—and the installer cannot supply it.","screen":"Licence → build and fit out; use needs the acceptance."},"clip":"B1.3-I01-use_on_arrival"}],"placement":"Chronological strip stays visible.","clip":"B1.3-I01-prompt"},"sequence":{"cues_before_interaction":["B1.3-S03-P1","B1.3-S03-P2","B1.3-S03-P3"],"interaction_after_cue":"B1.3-S03-P3","interaction_id":"B1.3-I01","post_interaction_cues":[],"rule":"Play cues_before_interaction in order; open the interaction immediately after interaction_after_cue (it speaks its prompt once); post_interaction_cues play only when their condition is met; nothing in post_interaction_cues is spoken before the interaction."}},{"id":"S04","title":"From licence to use: commissioning","paragraphs":[{"cue":"B1.3-S04-P1","speaker":"Emilia","text":"Here is the distinction the client missed, and it applies to our bunker as much as to their cabinet. Following the licence granted for a class two establishment—other than class IIA—or a class three establishment, the operator has the right, under its own responsibility, to build and fit out the installations in accordance with the licence. That is construction. Putting the installation into service is a separate step.","screen_text":["Licence granted → build and fit out (operator's responsibility) → commissioning: a separate step"],"start_visual":"Automatic sequence (plays with the narration, no exercise): licence → construction → commissioning; current point marked.","beats":[{"at":"build and fit out the installations","show":"Construction step current"},{"at":"Putting the installation into service is a separate step","show":"Commissioning step outlined"}],"clip":"B1.3-S04-P1"},{"cue":"B1.3-S04-P2","speaker":"Emilia","text":"The regulation says commissioning may take place only if two things hold. First, where the security decree applies, the acceptance of the radiological security system by the delegate for radiological security is favourable. Second, the acceptance under article 23.1.5 b) point 4—the recognised expert's acceptance—is fully favourable and expressly permits commissioning. And before commissioning, the operator of a class two establishment sends the Agency a document declaring that these conditions have been met.","screen_text":["Where the security decree applies: ARB's security acceptance favourable","Recognised expert's acceptance fully favourable and expressly permitting commissioning","Class II: declaration to the Agency beforehand"],"start_visual":"Conditional branch drawn only where applicable: security acceptance (sealed sources) joins the expert's acceptance; each document arrives at its point.","beats":[{"at":"where the security decree applies","show":"Conditional branch: security acceptance document"},{"at":"the recognised expert's acceptance","show":"Acceptance report document arrives"},{"at":"sends the Agency a document","show":"Declaration document; FANC logo"}],"equipment":["EQ-FANC-LOGO"],"clip":"B1.3-S04-P2"},{"cue":"B1.3-S04-P3","speaker":"Emilia","text":"What is an acceptance—an oplevering? The regulation defines it as the check that the installations or practices conform to the radiation regulations, to the establishment and operating licence, and, where there is one, to the safety report. Notice the three reference points. The expert is not asking 'does the equipment work?' in general. She is asking whether what was built matches what was licensed and what the regulation requires. A supplier's delivery note, an installer's sign-off and a manager's enthusiasm answer none of those questions.","screen_text":["Acceptance = conformity check against: the regulation · the licence · the safety report (where there is one)"],"start_visual":"Acceptance report page: three reference points as fields.","beats":[{"at":"The regulation defines it","show":"Acceptance page"},{"at":"Notice the three reference points","show":"Three fields highlighted in turn"}],"clip":"B1.3-S04-P3"},{"cue":"B1.3-S04-P4","speaker":"Emilia","text":"So for the client's cabinet the order is: licence from the Agency, construction and installation, the recognised expert's fully favourable acceptance expressly permitting commissioning, then use. For our bunker it was the same, with the security acceptance added because our projectors hold sealed sources. I keep the acceptance report with the licence, because together they are the answer to 'may this installation be used at all?'","screen_text":["Cabinet: licence → installation → expert's acceptance → use","Our bunker: + security acceptance (sealed sources)"],"start_visual":"Sequence shown twice: cabinet (no branch); bunker (with branch); installation file tabs 'licence' and 'acceptance' together.","beats":[{"at":"for the client's cabinet the order is","show":"Cabinet sequence"},{"at":"For our bunker it was the same","show":"Bunker sequence with security branch"},{"at":"together they are the answer","show":"File tabs together"}],"clip":"B1.3-S04-P4"}],"sequence":{"cues_before_interaction":["B1.3-S04-P1","B1.3-S04-P2","B1.3-S04-P3","B1.3-S04-P4"],"interaction_after_cue":null,"interaction_id":null,"post_interaction_cues":[]}},{"id":"S05","title":"What makes a room a bunker","paragraphs":[{"cue":"B1.3-S05-P1","speaker":"Emilia","text":"Now the walls. In the industrial radiography decree a bunker is not any thick-walled room. It is a whole consisting of four parts: an enclosure—with or without a roof—whose walls shield the ionising radiation; various safety devices; lockable doors or gates; and a control post outside the enclosure holding the remote control of each radiography device. And one more sentence: a bunker has a valid conformity certificate drawn up by a recognised expert in physical control. Our company must make sure that the bunkers in which it carries out radiography have such a valid certificate—our own and any client's.","screen_text":["Enclosure with shielding walls (with or without roof)","Safety devices","Lockable doors or gates","Control post outside","Valid conformity certificate — recognised expert"],"start_visual":"Roofed bunker exterior from the owner's architectural reference (EQ-BUNKER-REFERENCE: block enclosure, mono-pitch roof, sliding gate with pedestrian door) → brief deliberate cutaway (roof lifts/fades 2 s) → control post → back to exterior. Labels at their phrases.","beats":[{"at":"whole consisting of four parts","show":"Exterior view, roof clearly visible"},{"at":"with or without a roof","show":"Cutaway: roof lifts; interior visible, nobody inside, no emission"},{"at":"various safety devices","show":"Roof returns; entrance hardware in frame"},{"at":"lockable doors or gates","show":"Gate and pedestrian door"},{"at":"control post outside","show":"Control post with EQ-XRAY-CONTROL-UNIT"},{"at":"valid conformity certificate","show":"DOC-CERT-BUNKER thumbnail at the control post"}],"documents":["DOC-CERT-BUNKER"],"equipment":["EQ-BUNKER-REFERENCE","EQ-XRAY-CONTROL-UNIT"],"clip":"B1.3-S05-P1"},{"cue":"B1.3-S05-P2","speaker":"Emilia","text":"'Various safety devices' is where the bells and buttons live. The Agency's technical regulation on safety means in industrial radiography sets the minimum a bunker has to have, and the safety logic of each bunker follows from its own risk analysis. Let me show you the hardware and the state each item is for. While a door or gate is closing, a signal sounds at the control post and inside the bunker—it begins with the closing, not after it, so that anyone inside or near the door is warned while there is still time. A visual signal comes on when, and only when, ionising radiation is present in the exposure room, visible from every point inside and at every entrance. While the set is emitting, access to the room is locked. A locked door must never trap a person, so at least one door or gate is a clearly marked evacuation exit that can always be opened by hand from the inside. At the entrance hangs a description of what the audible and visual alarms mean, and there is emergency lighting. And because this bunker is used with an X-ray set, two more things: a device enforces a safety walk-round before an exposure—nobody left behind—ending with the doors locked, within a time the recognised expert set; and there are emergency stops inside the room, placed so that one can be reached from any position without crossing the direct beam, and one at the control post.","screen_text":["Sounder: while a door or gate is closing","Lamp: when—and only when—radiation is present","Access locked while emitting","Evacuation exit opens by hand from inside","Alarm meaning described at the entrance · emergency lighting","X-ray: enforced walk-round · emergency stops inside (off the beam) and at the control post"],"start_visual":"Hardware close-ups in idle state, each with a separate labelled STATE ILLUSTRATION inset (no person inside, never a live emission with people): gate + sounders; entrance and inside lamps; gate lock; evacuation exit handle; alarm-meaning sign; emergency luminaire; walk-round acknowledgement point; emergency stops (inside, off the beam axis; control post).","beats":[{"at":"While a door or gate is closing","show":"Inset: gate in motion → sounders lit at control post and inside"},{"at":"A visual signal comes on when","show":"Inset: radiation present → lamps on; room empty"},{"at":"access to the room is locked","show":"Inset: bolt engaged"},{"at":"opened by hand from the inside","show":"Close-up: marked evacuation exit and inside handle"},{"at":"description of what the audible and visual alarms mean","show":"Close-up: sign at the entrance (sample rows)"},{"at":"emergency lighting","show":"Close-up: emergency luminaire"},{"at":"a device enforces a safety walk-round","show":"Inset: walk-round not completed in time → exposure cannot start"},{"at":"emergency stops inside the room","show":"Close-ups: inside stop off the beam axis; control-post stop"}],"equipment":["EQ-BUNKER-REFERENCE","EQ-XRAY-CONTROL-UNIT"],"clip":"B1.3-S05-P2"},{"cue":"B1.3-S05-P3","speaker":"Emilia","text":"The certificate turns those parts into proof. The recognised expert checked that the safety requirements are met, and the certificate also says which isotopes and activities, which X-ray voltages and which working configurations are allowed in here. It is valid for ten years at most, it is adapted when the bunker changes, and a copy goes to the Agency.","screen_text":["Certificate: description · permitted equipment and configurations · safety-logic reference · valid max. 10 years"],"start_visual":"DOC-CERT-BUNKER full page → close-up on permitted equipment/configuration fields (placeholders) → validity line → back to page.","beats":[{"at":"The certificate turns those parts into proof","show":"Full page"},{"at":"which isotopes and activities","show":"Close-up: permitted equipment/configurations (placeholders)"},{"at":"valid for ten years at most","show":"Validity line"}],"documents":["DOC-CERT-BUNKER"],"clip":"B1.3-S05-P3"},{"cue":"B1.3-S05-P4","speaker":"Emilia","text":"The decree also says where radiography takes place, and this is one of the activity-specific rules you are expected to know. Radiography of movable workpieces that fit within one cubic metre and weigh less than 500 kilograms is always carried out in a bunker. Both conditions together—size and weight. Larger or heavier workpieces are preferably radiographed in a bunker; if that is not reasonably feasible, then after a risk analysis by the client and by our company it may be done on the client's site in an irradiation infrastructure—fixed shielding intended to protect against the radiation. And if neither a bunker nor an irradiation infrastructure is reasonably feasible, radiography may, again after a risk analysis by both, be carried out elsewhere. The Agency can prohibit radiography at a location whose justification it finds insufficient.","screen_text":["Movable, within 1 m³ and under 500 kg → always in a bunker","Larger/heavier: bunker preferred → irradiation infrastructure → another place, after risk analyses","The Agency may prohibit a location"],"start_visual":"Small casting on the exposure table (interior, no emission); then the three tiers as short lines; FANC logo at 'The Agency can prohibit'.","beats":[{"at":"fit within one cubic metre","show":"Casting on the table"},{"at":"Larger or heavier workpieces","show":"Tier lines"},{"at":"The Agency can prohibit","show":"FANC logo"}],"equipment":["EQ-FANC-LOGO"],"clip":"B1.3-S05-P4"},{"cue":"B1.3-S05-P5","speaker":"Emilia","text":"You met the client's written justification of the location in the opening lesson. Here is its companion: on the basis of its own risk analysis, the client gives us the information we need to do our risk analysis for radiography at that place. So when a client says 'use our bunker', I want to see the certificate, and when a client says 'do it in the hall', I want to see the written reasoning for why neither a bunker nor an irradiation infrastructure is reasonably feasible for that workpiece, and the information for the risk analysis.","screen_text":["Client's bunker → certificate","Client's hall → documented assessment of both options + risk-analysis information"],"start_visual":"Two document thumbnails: DOC-CERT-BUNKER and DOC-LOC-JUST (from B1.1 S07).","beats":[{"at":"I want to see the certificate","show":"Certificate thumbnail"},{"at":"I want to see the written reasoning","show":"Location justification thumbnail"}],"documents":["DOC-CERT-BUNKER","DOC-LOC-JUST"],"clip":"B1.3-S05-P5"}],"sequence":{"cues_before_interaction":["B1.3-S05-P1","B1.3-S05-P2","B1.3-S05-P3","B1.3-S05-P4","B1.3-S05-P5"],"interaction_after_cue":null,"interaction_id":null,"post_interaction_cues":[]}},{"id":"S06","title":"Is it a bunker?","paragraphs":[{"cue":"B1.3-S06-P1","speaker":"Emilia","text":"At a new client's site everyone calls a concrete room at the back of the hall 'the bunker'. It has a heavy door and a control desk outside. The site supervisor says: 'It was built for this; the walls are half a metre thick.'","screen_text":["Concrete room · heavy door · control desk outside · 'half a metre thick'"],"start_visual":"Client's concrete room (original render, labelled illustration): heavy door, control desk outside; no lamp, no alarm sign, no certificate visible.","beats":[{"at":"everyone calls a concrete room","show":"Room view"},{"at":"the walls are half a metre thick","show":"Supervisor's line as a speech line; no dimension drawn"}],"clip":"B1.3-S06-P1"}],"interaction":{"id":"B1.3-I02","type":"single_choice","prompt_spoken_once":"Before I plan small workpieces in that room, what has to be true for it to be a bunker in the sense of the decree?","behaviour":"The prompt is spoken automatically exactly once when the activity opens; the narration lead-in never reads it. Manual 'Hear the question' replay. Each option has its own spoken and written feedback (evidence, then next step). Retry without replaying narration; keyboard equivalents (labelled radio controls, Check, Try again, Continue); no auto-advance; no colour-only cues; no timer. Feedback never invents a dose, cause, approval or successful contact.","situation_visible_text":"Concrete room with a heavy door and a control desk outside; the supervisor says the walls are half a metre thick.","options":[{"id":"certificate","text":"It has the required parts and safety features, and a valid conformity certificate drawn up by a recognised expert.","correct":true,"feedback":{"spoken":"Right. The decree describes a bunker by its parts—shielding enclosure, safety devices, lockable doors or gates, a control post outside—and then adds the certificate, drawn up by a recognised expert, that says those parts and the safety requirements were checked. With the certificate in hand I can plan the work; without it, the first thing I ask the client for is exactly that.","screen":"Parts + safety features + valid certificate from a recognised expert."},"clip":"B1.3-I02-certificate"},{"id":"walls","text":"The walls are thick enough that a meter reads nothing outside the room.","correct":false,"feedback":{"spoken":"That reading is useful: it tells me something about the shielding on the day it was taken. What it cannot tell me is whether the door locks during an exposure, whether someone inside can get out, or whether the set can be stopped from both sides—and none of that is in a meter. The certificate covers the whole set of features, which is why it is the thing I ask for.","screen":"A reading is one observation; the certificate covers all the features."},"clip":"B1.3-I02-walls"},{"id":"licence","text":"The room is listed as a radiography room in the client's licence.","correct":false,"feedback":{"spoken":"The licence is real evidence of something else: it tells me what the client is permitted to do and where. It answers 'may radiography happen here at all?'. The bunker definition asks a narrower question—does this enclosure have the required features, confirmed by a recognised expert's certificate? I need both documents, for two different questions.","screen":"Licence = permitted practice; certificate = this enclosure's conformity."},"clip":"B1.3-I02-licence"}],"placement":"Room view stays visible.","clip":"B1.3-I02-prompt"},"sequence":{"cues_before_interaction":["B1.3-S06-P1"],"interaction_after_cue":"B1.3-S06-P1","interaction_id":"B1.3-I02","post_interaction_cues":[],"rule":"Play cues_before_interaction in order; open the interaction immediately after interaction_after_cue (it speaks its prompt once); post_interaction_cues play only when their condition is met; nothing in post_interaction_cues is spoken before the interaction."}},{"id":"S07","title":"Effective protection: the regulation's own five factors","paragraphs":[{"cue":"B1.3-S07-P1","speaker":"Emilia","text":"Here is where the paperwork meets the physics. Article 27 says that undertakings must put protective means in place that make it possible to ensure effective protection as defined in the regulation. Devices and installations that do not, or no longer, meet the regulation's provisions must be taken out of use until the identified deficiencies have been corrected. Keep that second sentence; it comes back shortly.","screen_text":["Protective means → effective protection","No longer compliant → out of use until corrected"],"start_visual":"ARBIS 27 extract thumbnail; control post view.","beats":[{"at":"Article 27 says","show":"Extract thumbnail"},{"at":"taken out of use","show":"Label 2"}],"documents":["DOC-REG-EXTRACT"],"clip":"B1.3-S07-P1"},{"cue":"B1.3-S07-P2","speaker":"Emilia","text":"The article then names five safety factors as fundamental, used alone or together. Protection by distance: the measures needed to prevent people from unintentionally approaching the sources. In our work that is the protection perimeter, the controlled area marked out around an exposure. Protection by shielding the sources: in our trade the projector's shielded container and the collimator are shielding at work, and the regulation adds a condition for the case where shielding is the only protective means relied on—you will find it in the reference reader. Protection of rooms by screens, with any openings in the screens themselves protected: the bunker's walls and door. Protection by preventing contamination, a list of principles for unsealed and sealed sources alike—sealed sources preferred, the smallest quantities, no spreading, no loss or theft, and an accurate inventory that lets every source be located at any moment. And protection by limiting exposure time: the speed of the source movement, the speed of the operation, or the limitation of working time and the rotation of staff.","screen_text":["Distance — perimeter","Shielding — projector container, collimator","Screens — bunker walls and door","Preventing contamination — sealed sources, inventory","Time — exposure planning"],"start_visual":"One concrete visual per factor with a short label: perimeter kit at a worksite; gamma projector image (container, collimator); bunker wall and door; the source inventory sheet at the store; an exposure planning line. No folder or sun icons.","beats":[{"at":"Protection by distance","show":"EQ-PERIMETER-KIT at a worksite"},{"at":"Protection by shielding the sources","show":"EQ-GAMMA-PROJECTOR close-up"},{"at":"Protection of rooms by screens","show":"Bunker wall and door"},{"at":"Protection by preventing contamination","show":"Inventory sheet (placeholders)"},{"at":"protection by limiting exposure time","show":"Exposure planning line, no values"}],"equipment":["EQ-PERIMETER-KIT","EQ-GAMMA-PROJECTOR","EQ-BUNKER-REFERENCE"],"clip":"B1.3-S07-P2"},{"cue":"B1.3-S07-P3","speaker":"Emilia","text":"One more sentence from the same article, and it should shape how you think about your personal dosimeter. In the study and design of protective means, and in their use in existing installations, priority goes to collective protective means that limit the radiation and contamination level, rather than to individual protective means. The bunker, the interlocks and the perimeter protect everyone present; the dosimeter records what one person received. The dosimeter matters, but it is not where protection starts.","screen_text":["Collective means first; the dosimeter records"],"start_visual":"Bunker, gate lock and perimeter in one view; then Daniel's EPD close-up.","beats":[{"at":"priority goes to collective protective means","show":"Collective means view"},{"at":"the dosimeter records","show":"EPD close-up, left chest"}],"equipment":["EQ-EPD-LEFT-CHEST"],"clip":"B1.3-S07-P3"},{"cue":"B1.3-S07-P4","speaker":"Emilia","text":"So when I ask 'is the protection effective?' about an installation, I am not asking for a feeling. I am asking which of these factors the design relies on, whether each still works as accepted, and whether the collective means come first. That is also how the recognised expert's risk analysis and acceptance are organised, and why the agent's checks look at protective means, instruments and dosimeters together.","screen_text":["Which factors · still working as accepted · collective first"],"start_visual":"Emilia to camera.","beats":[{"at":"is the protection effective","show":"Three short labels"}],"clip":"B1.3-S07-P4"}],"sequence":{"cues_before_interaction":["B1.3-S07-P1","B1.3-S07-P2","B1.3-S07-P3","B1.3-S07-P4"],"interaction_after_cue":null,"interaction_id":null,"post_interaction_cues":[]}},{"id":"S08","title":"A failed function and a missing record are different facts","paragraphs":[{"cue":"B1.3-S08-P1","speaker":"Emilia","text":"Now apply article 27's second sentence. Our bunker's door interlock is one of its safety devices. During the periodic test under the approved procedure, the interlock fails to stop the exposure sequence when the door is opened. That is a protective function that no longer meets the requirements, so the installation goes out of use until the deficiency is corrected. The licence does not make the result disappear, and neither does the week's schedule. The failed test is reported immediately—you know the duties from last lesson—and the correction is confirmed through the procedure and the expert's involvement, not by somebody saying 'it should be fine now'.","screen_text":["Case 1 — interlock FAILED its test → out of use until corrected → reported immediately"],"start_visual":"Case 1 state (red border + the words 'DEFECT ESTABLISHED'): control post; gate bolt shown not engaging in a labelled state illustration; Daniel at the control post, nobody inside; 'OUT OF USE' card.","beats":[{"at":"the interlock fails to stop the exposure sequence","show":"State illustration: bolt not engaging"},{"at":"goes out of use until the deficiency is corrected","show":"'OUT OF USE until corrected' card"},{"at":"reported immediately","show":"Daniel with phone"}],"characters":["Daniel"],"clip":"B1.3-S08-P1"},{"cue":"B1.3-S08-P2","speaker":"Emilia","text":"Here is a different fact that deserves the same care in language. This month's interlock test record cannot be found. We know that evidence is missing. We do not know whether the test was done and filed elsewhere, whether it was forgotten, or whether a fault was found and not written up. I will not fill in a pass because last month looked fine, and I will not report a defective interlock because a folder is incomplete. Both replace an open question with an invented answer.","screen_text":["Case 2 — this month's record NOT FOUND → result not established"],"start_visual":"Case 2 state (different border and words): DOC-CONTROL-TEST-PROGRAMME page, this month's line empty, last month's complete; NOT ESTABLISHED badge.","beats":[{"at":"This month's interlock test record cannot be found","show":"Programme page: empty line"},{"at":"I will not fill in a pass","show":"Last month's line visible, not copied"},{"at":"I will not report a defective interlock","show":"No defect card; NOT ESTABLISHED badge"}],"documents":["DOC-CONTROL-TEST-PROGRAMME"],"clip":"B1.3-S08-P2"},{"cue":"B1.3-S08-P3","speaker":"Emilia","text":"In our procedure, the relevant satisfactory test has to be established before the bunker is used again. Until it is, use is held—not because a defect has been proven, but because the required evidence is not there. Notice how much more useful the handover becomes when we name the actual gap: 'the result is not established; use is held under the procedure; please help locate or redo the test'. That gives the service something specific to do and leaves room for the facts to change when the record turns up.","screen_text":["Use HELD under the procedure — because the evidence is not there"],"start_visual":"Hold card DOC-HOLD-CARD placed at the control post (large held-work state); Emilia explains.","beats":[{"at":"use is held","show":"Hold card placed; HELD badge"},{"at":"please help locate or redo the test","show":"Hold card reason line"}],"documents":["DOC-HOLD-CARD"],"clip":"B1.3-S08-P3"},{"cue":"B1.3-S08-P4","speaker":"Emilia","text":"Here is how the second case went on that morning. Sofia, from the late shift, said she ran the test on Friday and that it passed, and simply never wrote it up. That is useful, and it is still not a record. My decision as head of service, under the procedure, was that the test is repeated, witnessed by Luc as supervisor, and the actual result is entered—result, date, both names. If it is satisfactory, I review the entry and only then does the hold come off. If it is not, we are in the first case, with a defect to correct. Nothing is released by memory or by a phone call; the record is.","screen_text":["Late-shift account ≠ record","Repeat the test under the procedure → record the actual result → head of service reviews → then the hold is lifted (or case 1)"],"start_visual":"Sofia gives her account at the control post (supplied pose); Luc and Daniel at the gate preparing the witnessed repeat; the programme page shows a new, still-empty line; the hold card stays. The outcome is deliberately not shown.","beats":[{"at":"Sofia, from the late shift","show":"Sofia at the control post"},{"at":"witnessed by Luc","show":"Luc at the gate"},{"at":"the actual result is entered","show":"Programme page: new empty line"},{"at":"the hold come off","show":"Hold card remains (no release shown)"}],"documents":["DOC-CONTROL-TEST-PROGRAMME","DOC-HOLD-CARD"],"characters":["Sofia","Luc","Daniel"],"clip":"B1.3-S08-P4"}],"sequence":{"cues_before_interaction":["B1.3-S08-P1","B1.3-S08-P2","B1.3-S08-P3","B1.3-S08-P4"],"interaction_after_cue":null,"interaction_id":null,"post_interaction_cues":[]},"status_badges":[{"kind":"fact","label":"Fact (case 1)","explanation":"The interlock did not stop the exposure sequence during its periodic test: a protective function that no longer meets the requirements."},{"kind":"held","label":"Held (case 2)","explanation":"Bunker use is held under the company procedure because this month's satisfactory test is not established — not because a defect has been proven."},{"kind":"not_established","label":"Not established (case 2)","explanation":"Whether the test was done, filed elsewhere, forgotten, or failed and not written up is unknown; a colleague's recollection is not a record."}]},{"id":"S09","title":"Say what is known","paragraphs":[{"cue":"B1.3-S09-P1","speaker":"Emilia","text":"You are handing over the missing-record case, not the failed-test case. The hold card and the empty line are in front of you; nothing is known about the function either way.","screen_text":["Missing-record case — use held"],"start_visual":"Case 2 state with the hold card large.","beats":[{"at":"the missing-record case","show":"Hold card and empty line"}],"clip":"B1.3-S09-P1"}],"interaction":{"id":"B1.3-I03","type":"single_choice","prompt_spoken_once":"This month's interlock test record for the bunker cannot be found. What do you report?","behaviour":"The prompt is spoken automatically exactly once when the activity opens; the narration lead-in never reads it. Manual 'Hear the question' replay. Each option has its own spoken and written feedback (evidence, then next step). Retry without replaying narration; keyboard equivalents (labelled radio controls, Check, Try again, Continue); no auto-advance; no colour-only cues; no timer. Feedback never invents a dose, cause, approval or successful contact.","situation_visible_text":"Hold card: bunker use on hold — this month's interlock test result not established. Last month's line: satisfactory.","options":[{"id":"not_established","text":"The test result is not established; use is held under the procedure.","correct":true,"feedback":{"spoken":"Exactly. That says what is known, what has been done and what still needs resolving, and it tells the service what to do: locate the record if the test was done, or repeat the test under the procedure if it was not. It leaves room for the facts to change—and until then the bunker stays held, because the required evidence is not there.","screen":"Known · done · open — the service locates or repeats the test; hold stays."},"clip":"B1.3-I03-not_established"},{"id":"defective","text":"The interlock is defective and must be repaired before use.","correct":false,"feedback":{"spoken":"A missing record is an evidence gap, and the useful report names it as one. If you report a defect nobody has observed, the service goes after the wrong problem, and when the record turns up the report has to be withdrawn. The accurate line is 'not established; use held under the procedure'—which still keeps the bunker out of use until it is resolved.","screen":"No observed defect; report the gap, keep the hold."},"clip":"B1.3-I03-defective"},{"id":"last_month","text":"Last month's test passed, so the bunker can still be used.","correct":false,"feedback":{"spoken":"Last month's record is a true statement about last month, and it is right that it is in the programme. What the procedure asks for before use is this month's satisfactory test, and a remembered pass does not supply it. Reporting the old result as today's evidence removes the open condition; the accurate report keeps it there.","screen":"Last month answers last month; this month's test is what the procedure requires."},"clip":"B1.3-I03-last_month"}],"placement":"Hold card and programme page stay visible.","clip":"B1.3-I03-prompt"},"sequence":{"cues_before_interaction":["B1.3-S09-P1"],"interaction_after_cue":"B1.3-S09-P1","interaction_id":"B1.3-I03","post_interaction_cues":[],"rule":"Play cues_before_interaction in order; open the interaction immediately after interaction_after_cue (it speaks its prompt once); post_interaction_cues play only when their condition is met; nothing in post_interaction_cues is spoken before the interaction."}},{"id":"S10","title":"When something changes","paragraphs":[{"cue":"B1.3-S10-P1","speaker":"Emilia","text":"Installations do not stay as they were licensed. A team wants a second projector of a different model, a client asks us to bring a higher-energy X-ray set, the recognised organisation we contract changes. The general regulation says that every change to the establishment which the Agency considers to have a potential impact on radiation protection or safety must be declared to the Agency—and, for class two and three, every change with a potential impact on the security of radioactive substances. The Agency then decides whether the change requires a licence application under the relevant procedure, and for class two and three it may waive some formalities when the change does not move the establishment into a higher class.","screen_text":["Changes with potential impact → declared to the Agency → Agency decides"],"start_visual":"Change register DOC-CHANGE-REGISTER page; three example change lines appear; FANC logo at 'declared to the Agency'.","beats":[{"at":"Installations do not stay as they were licensed","show":"Register page"},{"at":"must be declared to the Agency","show":"FANC logo outside"}],"documents":["DOC-CHANGE-REGISTER"],"equipment":["EQ-FANC-LOGO"],"clip":"B1.3-S10-P1"},{"cue":"B1.3-S10-P2","speaker":"Emilia","text":"The Agency has set the criteria in a technical regulation on the declaration of changes, in force since 3 March 2022. For class two and three establishments other than class IIA it does two things. First, our physical control service keeps a list of all changes with a potential impact on radiation protection or radiological safety—for each one a short description, the approvals already given and still needed, and the status of implementation. That list is mine to keep, and it is where every proposal goes first. Second, certain changes must be declared to the Agency beforehand. Among them: using a radiation source, or holding a radioactive substance, in an installation not licensed for it; carrying out a practice not licensed; other changes that fall outside the inventory in the licence; the definitive cessation of a practice with sources; the departure of an internal recognised expert; and a change of the recognised organisation that provides our experts.","screen_text":["Service keeps the change list: description · approvals given / needed · status","Some changes: prior declaration"],"start_visual":"Close-up on the register columns, then the 'prior declaration' marker on the relevant lines only (not every line).","beats":[{"at":"keeps a list of all changes","show":"Register columns"},{"at":"certain changes must be declared","show":"Marker on the lines that need prior declaration; other lines unmarked"}],"clip":"B1.3-S10-P2"},{"cue":"B1.3-S10-P3","speaker":"Emilia","text":"The declaration is approved and countersigned by a recognised expert in physical control—except for the purely organisational criteria such as the expert's departure, the change of organisation, an address change without moving, or a name change of the legal entity. It gives the establishment's unique number and a description of the change, together with the updated parts of the licence dossier that the change affects. And the Agency informs the operator and the head of the physical control service of its decision. So nobody in our company—not the team, not me, not the supplier—approves a change of this kind. We recognise it, record it, bring in the expert and declare it; the Agency decides.","screen_text":["Declaration approved and countersigned by the recognised expert (except organisational criteria)","Agency informs operator and head of service"],"start_visual":"Declaration outline: expert countersignature field (role), unique establishment number placeholder; Agency decision letter outline.","beats":[{"at":"approved and countersigned by a recognised expert","show":"Countersignature field"},{"at":"except for the purely organisational criteria","show":"Lines without that field"},{"at":"the Agency decides","show":"Decision letter outline with FANC logo"}],"equipment":["EQ-FANC-LOGO"],"clip":"B1.3-S10-P3"}],"sequence":{"cues_before_interaction":["B1.3-S10-P1","B1.3-S10-P2","B1.3-S10-P3"],"interaction_after_cue":null,"interaction_id":null,"post_interaction_cues":[]}},{"id":"S11","title":"A new X-ray set","paragraphs":[{"cue":"B1.3-S11-P1","speaker":"Emilia","text":"Our team proposes buying an additional X-ray set of a type that is not in our licence's equipment inventory, to use in the bunker for thicker sections. Everyone agrees it would be useful.","screen_text":["Proposed: additional X-ray set — not in the licence inventory"],"start_visual":"Supplied X-ray generator image EQ-XRAY-GENERATOR beside the licence's equipment-inventory field (placeholders) where this type is absent; register line 'proposal'.","beats":[{"at":"additional X-ray set","show":"Generator image"},{"at":"not in our licence's equipment inventory","show":"Inventory field close-up: type absent"}],"documents":["DOC-LICENCE","DOC-CHANGE-REGISTER"],"equipment":["EQ-XRAY-GENERATOR"],"clip":"B1.3-S11-P1"}],"interaction":{"id":"B1.3-I04","type":"single_choice","prompt_spoken_once":"The team wants to add an X-ray set that is not in our licence's equipment inventory. What happens before it can be used?","behaviour":"The prompt is spoken automatically exactly once when the activity opens; the narration lead-in never reads it. Manual 'Hear the question' replay. Each option has its own spoken and written feedback (evidence, then next step). Retry without replaying narration; keyboard equivalents (labelled radio controls, Check, Try again, Continue); no auto-advance; no colour-only cues; no timer. Feedback never invents a dose, cause, approval or successful contact.","situation_visible_text":"Licence inventory excerpt: this type absent. Change register: 'proposal'.","options":[{"id":"declare","text":"It is declared to the Agency beforehand, approved and countersigned by the recognised expert.","correct":true,"feedback":{"spoken":"Yes. Using a source that can emit ionising radiation in an installation not licensed for it is one of the changes that must be declared beforehand; the declaration is approved and countersigned by a recognised expert, and the Agency decides whether a licence application is needed. Until then the set is a proposal on our change list—that line stays as it is.","screen":"Prior declaration, expert countersignature, Agency decision; proposal until then."},"clip":"B1.3-I04-declare"},{"id":"list_only","text":"Emilia records it on the service's change list, and the set can then be used.","correct":false,"feedback":{"spoken":"Recording it on the list is required and it is the right first step—every change with a potential impact goes there. But the list is our administration, not the Agency's decision. For a device not in the licence inventory the technical regulation requires a prior declaration, countersigned by the recognised expert.","screen":"List entry required; declaration and decision still needed."},"clip":"B1.3-I04-list_only"},{"id":"covered","text":"Nothing further: our licence already covers X-ray radiography in general.","correct":false,"feedback":{"spoken":"The licence does cover X-ray radiography—with the equipment in its inventory, under its conditions. The inventory field in front of you is where this type is missing. A set outside that inventory is exactly the kind of change the regulation and the technical regulation single out for prior declaration. 'We do X-ray work' is not 'we are licensed for this set'.","screen":"Licensed for the inventory, not for every set."},"clip":"B1.3-I04-covered"}],"placement":"Generator image and inventory excerpt stay visible.","clip":"B1.3-I04-prompt"},"sequence":{"cues_before_interaction":["B1.3-S11-P1"],"interaction_after_cue":"B1.3-S11-P1","interaction_id":"B1.3-I04","post_interaction_cues":[],"rule":"Play cues_before_interaction in order; open the interaction immediately after interaction_after_cue (it speaks its prompt once); post_interaction_cues play only when their condition is met; nothing in post_interaction_cues is spoken before the interaction."}},{"id":"S12","title":"Useful knowledge from elsewhere, verified here","paragraphs":[{"cue":"B1.3-S12-P1","speaker":"Emilia","text":"One last kind of evidence. Several of you learned radiation physics abroad or from training material written for another country's rules. That knowledge does not become worthless in Belgium—how radiation attenuates in steel does not change at the border. But a check interval, an alarm setting or a 'you may start when' from another jurisdiction is not a Belgian requirement, and neither is a manufacturer's manual. What governs our installation is the Belgian regulation, our licence and its conditions, and the procedures approved by the recognised expert.","screen_text":["Physics travels; rules do not","Governs here: regulation · licence · expert-approved procedures"],"start_visual":"An equipment manual page (generic, no manufacturer) open beside the Belgian regulation extract and the company procedure page; the manual's 'check interval' line and the procedure's interval line pointed to as the type of discrepancy — no values shown.","beats":[{"at":"how radiation attenuates in steel","show":"Manual page: physics section"},{"at":"a check interval, an alarm setting","show":"Two interval lines side by side, values blanked"},{"at":"What governs our installation","show":"Regulation, licence, procedure thumbnails"}],"documents":["DOC-REG-EXTRACT","DOC-PROCEDURE-RECORD"],"clip":"B1.3-S12-P1"},{"cue":"B1.3-S12-P2","speaker":"Emilia","text":"So keep the physics, and treat the rule as a question: 'this is what I was taught elsewhere—what applies here?' If a manual and our procedure disagree, raise the discrepancy with the service and the expert rather than choosing the more convenient instruction. That habit is worth more than any single interval you could memorise.","screen_text":["Raise the discrepancy with the service and the expert"],"start_visual":"Emilia to camera.","beats":[{"at":"raise the discrepancy","show":"Label"}],"clip":"B1.3-S12-P2"}],"sequence":{"cues_before_interaction":["B1.3-S12-P1","B1.3-S12-P2"],"interaction_after_cue":null,"interaction_id":null,"post_interaction_cues":[]}},{"id":"S13","title":"Bring the evidence back to the work","paragraphs":[{"cue":"B1.3-S13-P1","speaker":"Emilia","text":"We started with 'everything is approved'. You can now say something better: what the licence permits and under which conditions; that the client's class three licence is the Agency's decision on a declaration, not the sending of it; that commissioning needed a fully favourable acceptance expressly permitting it—plus the security acceptance where sealed sources are involved; what the decree requires before a room counts as a bunker and when small workpieces must be radiographed in one; which five safety factors the regulation builds effective protection on, with collective means first; and that a change outside the licence is recorded, declared with the expert's countersignature and decided by the Agency.","screen_text":["Licence · Agency decision · acceptance (+ security) · bunker definition + certificate · five factors · change declared"],"start_visual":"Installation file at the control post; each tab opens briefly at its phrase (visual recap, not a bullet page).","beats":[{"at":"what the licence permits","show":"Tab: licence"},{"at":"the Agency's decision on a declaration","show":"Tab: decision"},{"at":"commissioning needed a fully favourable acceptance","show":"Tab: acceptance"},{"at":"before a room counts as a bunker","show":"Tab: certificate"},{"at":"five safety factors","show":"Tab: factors"},{"at":"a change outside the licence","show":"Tab: change register"}],"clip":"B1.3-S13-P1"},{"cue":"B1.3-S13-P2","speaker":"Emilia","text":"None of this needs you to be the licensing authority. It needs you to read the right document for the right question, to say plainly when a result is not established, and to route a proposal through the people who decide. In the next lesson we add a second company to the picture: what changes when the worker's employer and the operator of the workplace are not the same organisation—as happens every time one of our radiographers enters a client's controlled area, or a subcontractor enters ours.","screen_text":["Next: a second company in the picture"],"start_visual":"Clara's file-carrying preview as the bridge.","beats":[{"at":"a second company","show":"Clara preview"}],"characters":["Clara"],"clip":"B1.3-S13-P2"}],"sequence":{"cues_before_interaction":["B1.3-S13-P1","B1.3-S13-P2"],"interaction_after_cue":null,"interaction_id":null,"post_interaction_cues":[]}}]},{"id":"B1.4","title":"External workers: protection across company lines","scenes":[{"id":"S01","title":"Welcome back: protection across company lines","paragraphs":[{"cue":"B1.4-S01-P1","speaker":"Emilia","text":"Welcome back. So far we have looked at our own company from the inside: our service, our licence, our bunker, our agents—with clients appearing at the edge of the picture, asking for radiography and justifying where it happens. Today the company line itself becomes the subject. Almost every week one of our radiographers walks into another operator's controlled area, and from time to time a radiographer employed by another company works in our bunker. Who makes sure the important information travels with the person?","screen_text":["A second company changes the information flow"],"start_visual":"Reception area with the hall and bunker gate behind; Clara enters in her approved file-carrying pose at 'a radiographer employed by another company'; Emilia at the desk.","beats":[{"at":"walks into another operator's controlled area","show":"Daniel preview at the hall door with his case"},{"at":"a radiographer employed by another company works in our bunker","show":"Clara enters with her file"}],"characters":["Emilia","Clara","Daniel"],"clip":"B1.4-S01-P1"},{"cue":"B1.4-S01-P2","speaker":"Emilia","text":"Belgian law has a short section for exactly this situation: the operational protection of external workers exposed to a risk of ionising radiation while working in a controlled area. Today I want you to be able to say what the worker's own employer must do, what the operator of the workplace must do, what a signed agreement between the two can and cannot change, and what the worker brings to the arrangement personally. We will use both directions: one of our people going out, and a visiting radiographer coming in.","screen_text":["Employer's duties · workplace operator's duties · what an agreement can change · what the worker brings"],"start_visual":"Four short labels in turn beside Clara's file.","beats":[{"at":"what the worker's own employer must do","show":"Label 1"},{"at":"what the operator of the workplace must do","show":"Label 2"},{"at":"signed agreement","show":"Label 3"},{"at":"what the worker brings","show":"Label 4"}],"clip":"B1.4-S01-P2"}],"sequence":{"cues_before_interaction":["B1.4-S01-P1","B1.4-S01-P2"],"interaction_after_cue":null,"interaction_id":null,"post_interaction_cues":[]}},{"id":"S02","title":"Two directions, the same words","paragraphs":[{"cue":"B1.4-S02-P1","speaker":"Emilia","text":"First the words, because the law uses the same two terms whichever way the worker is travelling. The external undertaking is the company that employs the worker and sends him. The operator—or, where there is no operator, the head of the undertaking—is the party at whose premises the worker carries out an assignment involving an exposure risk. The external worker is the person in between.","screen_text":["External undertaking = employer who sends","Operator = where the assignment is carried out","External worker = the person in between"],"start_visual":"Two-lane view, both empty; the three terms appear as stable labels.","beats":[{"at":"The external undertaking","show":"Label 1"},{"at":"The operator","show":"Label 2"},{"at":"The external worker","show":"Label 3"}],"clip":"B1.4-S02-P1"},{"cue":"B1.4-S02-P2","speaker":"Emilia","text":"Direction one. Daniel is sent to a power station during an outage, to radiograph welds inside the plant's controlled area. There, Daniel is an external worker, our company is the external undertaking, and the power station is the operator. Notice that he does not stop being our designated agent for the radiography we perform: the decree asks for our agent on every worksite, and the Agency's guidance accepts that contractors bring their own agents for specific operations under the supervision of the operator's physical control service. Two roles run side by side—his, for our radiography; the plant's, for its controlled area—and this lesson is about how they are divided, not about one cancelling the other. Direction two. Clara, a radiographer employed by another inspection company, is subcontracted to work in our bunker for two weeks. In our bunker she is the external worker, her employer is the external undertaking, and we are the operator. Same words, roles reversed.","screen_text":["Direction 1 — Daniel out: we = external undertaking · plant = operator","Direction 2 — Clara in: her employer = external undertaking · we = operator"],"start_visual":"Lane 1 animates first: Daniel travels from our company to a power-station controlled area (labels stable); then lane 2: Clara arrives from her employer into our bunker. Labels 'employer' and 'workplace operator' stay fixed on each lane.","beats":[{"at":"Direction one","show":"Lane 1: Daniel travels out"},{"at":"our designated agent for the radiography we perform","show":"Small caption on Daniel: 'our agent for our radiography'"},{"at":"Direction two","show":"Lane 2: Clara arrives"},{"at":"roles reversed","show":"Both lanes with their fixed labels"}],"characters":["Daniel","Clara"],"clip":"B1.4-S02-P2"},{"cue":"B1.4-S02-P3","speaker":"Emilia","text":"A controlled area, in the regulation's definition, is an area subject to special rules for protection against ionising radiation and against the spread of contamination, and whose access is controlled; in licensed establishments, every area where three tenths of the annual dose limits for exposed workers could be exceeded must be a controlled area or part of one. The protection perimeter we mark out around an exposure is our controlled area on a worksite; the plant's marked zones are its controlled areas.","screen_text":["Controlled area: special rules, access controlled","Our perimeter on a worksite = our controlled area"],"start_visual":"Regulation extract thumbnail; perimeter kit image at the worksite lane.","beats":[{"at":"A controlled area","show":"Extract thumbnail"},{"at":"The protection perimeter we mark out","show":"EQ-PERIMETER-KIT in lane 1"}],"documents":["DOC-REG-EXTRACT"],"equipment":["EQ-PERIMETER-KIT"],"clip":"B1.4-S02-P3"},{"cue":"B1.4-S02-P4","speaker":"Emilia","text":"And the principle that governs the whole section is one sentence: the radiological control system for external workers provides protection equivalent to that enjoyed by the workers the operator employs permanently. Being there for two weeks, or for one shift, is not a reason for weaker arrangements. Keep that sentence in mind as we divide the duties.","screen_text":["Equivalent protection — however short the assignment"],"start_visual":"Both lanes; one sentence label.","beats":[{"at":"protection equivalent","show":"Label"}],"clip":"B1.4-S02-P4"}],"sequence":{"cues_before_interaction":["B1.4-S02-P1","B1.4-S02-P2","B1.4-S02-P3","B1.4-S02-P4"],"interaction_after_cue":null,"interaction_id":null,"post_interaction_cues":[]}},{"id":"S03","title":"What the worker's own employer must do","paragraphs":[{"cue":"B1.4-S03-P1","speaker":"Emilia","text":"Start with the employer, because its duties begin before anyone arrives. The external undertaking looks after the radiation protection and safety of its workers in accordance with chapter three of the regulation. In particular it ensures compliance with the general principles of radiation protection and the dose limits, and it organises the general information of article 25.1.1 for its workers—the information you met two lessons ago.","screen_text":["Employer: principles and limits · general information (25.1.1)"],"start_visual":"DOC-EXT-WORKER-FILE page 1 overview (page-shaped, two pages indicated).","beats":[{"at":"The external undertaking looks after","show":"Page 1 overview"}],"documents":["DOC-EXT-WORKER-FILE"],"clip":"B1.4-S03-P1"},{"cue":"B1.4-S03-P2","speaker":"Emilia","text":"Then, before an assignment with an exposure risk, it informs the operator—or the head of the undertaking, or the foreign undertaking—about three things, and the purpose of each is easy to see. Who the sending company is, so the operator knows whom it is dealing with: the name, the establishment unit and the enterprise number. Who the worker is, unambiguously: his identity data down to the national register number, so that dose records cannot be confused between two people with the same name. And what dose he has already received: the doses over the last five calendar years, shown per year, and the doses over the last twelve rolling months, shown with the monitoring period—so the operator can judge, before the task, whether a dose constraint is needed. Where exposure was not uniform or there was internal contamination, the file carries the corresponding equivalent and committed doses as well. The exact fields are in the reference reader.","screen_text":["Who sends — name, establishment unit, enterprise number","Who — identity data incl. national register number","Doses — five calendar years per year; twelve rolling months with period"],"start_visual":"Page 1 close-ups: sending-employer block (placeholders) → worker block (Clara; placeholders) → page 2 close-up: five-year section ('provided' ×5) → twelve-month section → back to page 2 overview.","beats":[{"at":"Who the sending company is","show":"Close-up: employer block"},{"at":"Who the worker is","show":"Close-up: worker block"},{"at":"what dose he has already received","show":"Page 2: five-year section"},{"at":"twelve rolling months","show":"Page 2: twelve-month section (content revealed in S04)"},{"at":"reference reader","show":"Reference reader control indicated"}],"documents":["DOC-EXT-WORKER-FILE"],"clip":"B1.4-S03-P2"},{"cue":"B1.4-S03-P3","speaker":"Emilia","text":"Two reporting periods, then: five calendar years, and twelve rolling months. They answer different questions, and an unlabelled number does not tell you which one you have. If the assignment is abroad, the employer also states the legal dose limits that apply there, and the information is transmitted in the way the Agency prescribes, using the radiation passport. So when Daniel is sent to the power station, it is my service that sends the plant his file before he arrives—and when Clara is sent to us, it is her employer's service I expect to hear from first.","screen_text":["Two periods, two questions","Abroad: legal limits there · radiation passport"],"start_visual":"Page 2 overview with both sections labelled; 'assignment abroad: not applicable' line.","beats":[{"at":"Two reporting periods","show":"Both sections pulse"},{"at":"If the assignment is abroad","show":"Abroad line"},{"at":"when Clara is sent to us","show":"Clara at the desk with the file"}],"characters":["Clara"],"clip":"B1.4-S03-P3"}],"sequence":{"cues_before_interaction":["B1.4-S03-P1","B1.4-S03-P2","B1.4-S03-P3"],"interaction_after_cue":null,"interaction_id":null,"post_interaction_cues":[]}},{"id":"S04","title":"Clara's file arrives incomplete","paragraphs":[{"cue":"B1.4-S04-P1","speaker":"Emilia","text":"Clara's employer sent her file last week, and this morning Clara hands me the printed copy herself, with her agent-course certificate on top. Company details, her details, and her doses for the last five calendar years are there. The twelve-rolling-month section is blank. Our service has a dosimeter ready for her.","screen_text":["Five calendar years: provided","Twelve rolling months: NOT PROVIDED"],"start_visual":"Clara visibly hands the folder to Emilia (supplied poses: Clara offering, Emilia receiving with both hands); Emilia opens it; page 2 close-up: five-year section 'provided', twelve-month section 'NOT PROVIDED' — the blank section is the evidence, framed, with a NOT ESTABLISHED badge; certificate thumbnail on top; dosimeter on the desk.","beats":[{"at":"Clara hands me the printed copy","show":"Hand-over: the folder moves from Clara's hand to Emilia's"},{"at":"five calendar years are there","show":"Close-up: five-year section"},{"at":"twelve-rolling-month section is blank","show":"Close-up: NOT PROVIDED section framed; badge"},{"at":"a dosimeter ready for her","show":"EPD on the desk"}],"documents":["DOC-EXT-WORKER-FILE","DOC-CERT-AGENT"],"equipment":["EQ-EPD-LEFT-CHEST"],"characters":["Clara","Emilia"],"clip":"B1.4-S04-P1"}],"interaction":{"id":"B1.4-I01","type":"single_choice","prompt_spoken_once":"Clara's file has her doses for the last five calendar years but not for the last twelve rolling months. What do we do?","behaviour":"The prompt is spoken automatically exactly once when the activity opens; the narration lead-in never reads it. Manual 'Hear the question' replay. Each option has its own spoken and written feedback (evidence, then next step). Retry without replaying narration; keyboard equivalents (labelled radio controls, Check, Try again, Continue); no auto-advance; no colour-only cues; no timer. Feedback never invents a dose, cause, approval or successful contact.","situation_visible_text":"Page 2: five calendar years — provided; twelve rolling months — NOT PROVIDED. Certificate and our dosimeter on the desk.","options":[{"id":"ask","text":"Ask her employer for the twelve-month results and take note of them before she starts.","correct":true,"feedback":{"spoken":"Yes. The employer must send both periods before the assignment, and we as the operator must take note of her monitoring results before she starts. So I name the exact gap—twelve rolling months with the monitoring period—and ask her employer's service for it this morning. Clara does not have to repeat anything, and nobody guesses what the missing months would show. Her instruction on our bunker can begin meanwhile; it does not depend on that number.","screen":"Name the gap; ask the employer; take note before she starts."},"clip":"B1.4-I01-ask"},{"id":"zero","text":"Treat the missing twelve months as zero and issue our dosimeter.","correct":false,"feedback":{"spoken":"Our dosimeter will do its job: it records what Clara receives with us, from today. What it cannot do is tell me what she received elsewhere in the last twelve months, and that is the figure I need before deciding whether a dose constraint applies to her task. Writing zero turns an unknown into a claim nobody can support. The useful step is to ask her employer for the twelve-month section.","screen":"Unknown ≠ zero; the dosimeter records from today only."},"clip":"B1.4-I01-zero"},{"id":"certificate","text":"Accept her agent-course certificate as sufficient evidence of her dose history.","correct":false,"feedback":{"spoken":"Her certificate is real evidence of something—she passed the knowledge test for the agent training, which I am glad to see on the file. It simply contains no dosimetry, because it was never meant to. Dose history comes from her employer's monitoring, in the file. So I keep the certificate for what it shows, and I ask her employer for the twelve-month results.","screen":"Certificate = passed test; dose history comes from the employer's monitoring."},"clip":"B1.4-I01-certificate"}],"placement":"Page 2 with the framed NOT PROVIDED section stays visible.","clip":"B1.4-I01-prompt"},"sequence":{"cues_before_interaction":["B1.4-S04-P1"],"interaction_after_cue":"B1.4-S04-P1","interaction_id":"B1.4-I01","post_interaction_cues":[],"rule":"Play cues_before_interaction in order; open the interaction immediately after interaction_after_cue (it speaks its prompt once); post_interaction_cues play only when their condition is met; nothing in post_interaction_cues is spoken before the interaction."},"status_badges":[{"kind":"not_established","label":"Twelve rolling months: not provided","explanation":"The employer's file lacks the twelve-month monitoring results with their period. This is an evidence gap to be closed by the employer; it is not a dose of zero."}]},{"id":"S05","title":"What the operator of the workplace must do","paragraphs":[{"cue":"B1.4-S05-P1","speaker":"Emilia","text":"Now the other side. The operator—or, failing one, the head of the undertaking—at whose premises external workers carry out an assignment with an exposure risk is responsible for the operational aspects of their radiation protection in the controlled area and for the task to be performed. The regulation lists six things in particular.","screen_text":["Operator: operational aspects in the controlled area and for the task"],"start_visual":"Emilia and Clara walk from reception toward the bunker control post (supplied poses or a cut between two positions if no walking pose exists).","beats":[{"at":"responsible for the operational aspects","show":"Label"}],"characters":["Emilia","Clara"],"clip":"B1.4-S05-P1"},{"cue":"B1.4-S05-P2","speaker":"Emilia","text":"Ensuring that the general principles and the dose limits are respected. Organising the individual dosimetric monitoring of the external workers, as provided in article 30.6. Organising the specific training for the external workers—the workstation training of article 25.1.2, aimed at this area and this task. Making the necessary personal protective equipment available. Taking note, before the assignment, of the results of their individual dosimetric monitoring. And, where necessary, determining and enforcing dose constraints, taking into account the doses already received, the nature of the controlled area and the task.","screen_text":["Principles and limits · monitoring (30.6) · specific training (25.1.2) · PPE · take note of dose results · dose constraints where needed"],"start_visual":"One action at a time, not a six-card lecture: Emilia hands Clara our EPD (clip to chest); the instruction record DOC-INSTRUCTION-RECORD is opened at the control post; PPE shelf; the file's dose page; the planning line 'dose constraint: to be considered'.","beats":[{"at":"Organising the individual dosimetric monitoring","show":"EPD handed over and clipped"},{"at":"Organising the specific training","show":"Instruction record opened: bunker · bunker X-ray set"},{"at":"personal protective equipment","show":"PPE shelf"},{"at":"Taking note, before the assignment","show":"File page 2"},{"at":"dose constraints","show":"Planning line"}],"documents":["DOC-INSTRUCTION-RECORD","DOC-EXT-WORKER-FILE","DOC-PLANNING"],"equipment":["EQ-EPD-LEFT-CHEST"],"characters":["Emilia","Clara"],"clip":"B1.4-S05-P2"},{"cue":"B1.4-S05-P3","speaker":"Emilia","text":"Apply it in both directions. When Daniel enters the power station, the plant organises his site-specific training, reads his dose history, and decides whether a dose constraint applies for the outage work—unless an agreement says otherwise, which is the next scene. When Clara enters our bunker, that list is mine: I organise her monitoring with us, her instruction on our bunker and our procedures, her protective equipment, and I read her file before she starts. Notice what the list does not contain. It does not say 'check that she has a certificate and let her get on with it'. The specific training is about this place and this task, and no certificate from a classroom supplies it.","screen_text":["Daniel at the plant: the plant's list (unless an agreement says otherwise)","Clara with us: my list"],"start_visual":"Both lanes from S02 briefly; then Daniel's instruction record at the plant (outline) and Clara's with us.","beats":[{"at":"When Daniel enters the power station","show":"Lane 1"},{"at":"When Clara enters our bunker","show":"Lane 2"},{"at":"no certificate from a classroom supplies it","show":"Certificate thumbnail set aside from the instruction record"}],"characters":["Daniel","Clara"],"clip":"B1.4-S05-P3"}],"sequence":{"cues_before_interaction":["B1.4-S05-P1","B1.4-S05-P2","B1.4-S05-P3"],"interaction_after_cue":null,"interaction_id":null,"post_interaction_cues":[]}},{"id":"S06","title":"What a signed agreement can change","paragraphs":[{"cue":"B1.4-S06-P1","speaker":"Emilia","text":"You may be thinking: our own service organises Daniel's dosimetry; surely the power station does not issue him a second dosimeter? The regulation foresees this. An external undertaking that intervenes continuously or repeatedly under a contract with an operator, or that has its own physical control service, or that is an external emergency service, may organise some or all of certain aspects of its workers' protection during assignments for that operator. Our company qualifies twice over: we work for the plant under a repeated contract, and we have our own physical control service.","screen_text":["Qualifying external undertaking: repeated contract · own physical control service · emergency service"],"start_visual":"DOC-AGREEMENT whole page (parties as roles; illustrative signature area, no names).","beats":[{"at":"The regulation foresees this","show":"Agreement page overview"},{"at":"Our company qualifies twice over","show":"Parties block"}],"documents":["DOC-AGREEMENT"],"clip":"B1.4-S06-P1"},{"cue":"B1.4-S06-P2","speaker":"Emilia","text":"Which aspects? The regulation names them: the specific training on the controlled area and the task; the individual dosimetric monitoring and the transfer of its results to the exposure register; and the provision of the necessary personal protective equipment. And it adds the condition that matters most in practice: these arrangements are laid down in an agreement signed by both parties.","screen_text":["Can be allocated: specific training · dosimetry + transfer to the register · PPE","Only in an agreement signed by both parties"],"start_visual":"Close-up on the three relevant clauses in turn, then the signature area (illustrative).","beats":[{"at":"the specific training on the controlled area","show":"Clause C"},{"at":"the individual dosimetric monitoring","show":"Clause A"},{"at":"protective equipment","show":"Clause B"},{"at":"signed by both parties","show":"Signature area (placeholders)"}],"clip":"B1.4-S06-P2"},{"cue":"B1.4-S06-P3","speaker":"Emilia","text":"So I read our agreement with the power station for what it actually allocates. Ours says: our company provides Daniel's individual dosimetry and transfers the results to the register, and provides his protective equipment; the plant provides the training specific to its controlled areas and the task. That is a sensible split—we know our dosimetry, they know their plant. What the agreement does not do is move every duty to us because we signed something. Each aspect is allocated by name, and each still has to be carried out by somebody.","screen_text":["Ours: dosimetry + register → us · PPE → us · site-specific training → the plant"],"start_visual":"Clauses A and B marked 'external undertaking'; clause C marked 'operator'; back to full page.","beats":[{"at":"Ours says","show":"Clauses A/B marked"},{"at":"the plant provides the training","show":"Clause C marked 'operator'"},{"at":"Each aspect is allocated by name","show":"Full page"}],"clip":"B1.4-S06-P3"}],"sequence":{"cues_before_interaction":["B1.4-S06-P1","B1.4-S06-P2","B1.4-S06-P3"],"interaction_after_cue":null,"interaction_id":null,"post_interaction_cues":[]}},{"id":"S07","title":"Read the allocation","paragraphs":[{"cue":"B1.4-S07-P1","speaker":"Emilia","text":"A colleague at the plant sees our signed agreement and says: 'You people handle Daniel's protection, then—we're off the hook.'","screen_text":["'You people handle Daniel's protection, then—we're off the hook.'"],"start_visual":"Agreement page with clauses A/B/C visible; the colleague's line as a speech line.","beats":[{"at":"A colleague at the plant","show":"Speech line"}],"documents":["DOC-AGREEMENT"],"clip":"B1.4-S07-P1"}],"interaction":{"id":"B1.4-I02","type":"single_choice","prompt_spoken_once":"Our signed agreement allocates Daniel's dosimetry and protective equipment to our company. Who provides the training specific to the plant's controlled area?","behaviour":"The prompt is spoken automatically exactly once when the activity opens; the narration lead-in never reads it. Manual 'Hear the question' replay. Each option has its own spoken and written feedback (evidence, then next step). Retry without replaying narration; keyboard equivalents (labelled radio controls, Check, Try again, Continue); no auto-advance; no colour-only cues; no timer. Feedback never invents a dose, cause, approval or successful contact.","situation_visible_text":"Agreement: clause A dosimetry → external undertaking; clause B PPE → external undertaking; clause C specific training → operator.","options":[{"id":"plant","text":"The power station, because the agreement did not allocate that training to us.","correct":true,"feedback":{"spoken":"Right. The agreement can allocate specific training, dosimetry and protective equipment to the external undertaking, but only as far as it says. Read clause C on the page: it stays with the operator. The specific training stays where the regulation places it by default: with the operator at whose premises the work is done.","screen":"Clause C: operator. Only named aspects move."},"clip":"B1.4-I02-plant"},{"id":"us","text":"Our company, because signing the agreement moved all protection duties to the external undertaking.","correct":false,"feedback":{"spoken":"The signature did move two real things: Daniel's dosimetry and his protective equipment are ours under clauses A and B. A signed agreement allocates the aspects it names, and the regulation lists which aspects can be allocated at all. Clause C does not allocate site-specific training to us, so that duty did not move. Reading every duty into one signature is exactly the colleague's mistake.","screen":"A and B moved to us; C did not."},"clip":"B1.4-I02-us"},{"id":"none","text":"Nobody needs to: Daniel's agent course already covers controlled areas.","correct":false,"feedback":{"spoken":"The agent course is real theoretical training in radiation protection, and it is one reason Daniel can be our agent. The specific training the regulation requires is about this controlled area and this task—the plant's zones, its rules, its emergency instructions. A classroom certificate cannot supply it, which is why the regulation assigns it to the party who knows the place—here, the plant under clause C.","screen":"Theory ≠ site-specific training; the plant provides it."},"clip":"B1.4-I02-none"}],"placement":"Agreement page stays visible with the three clauses.","clip":"B1.4-I02-prompt"},"sequence":{"cues_before_interaction":["B1.4-S07-P1"],"interaction_after_cue":"B1.4-S07-P1","interaction_id":"B1.4-I02","post_interaction_cues":[],"rule":"Play cues_before_interaction in order; open the interaction immediately after interaction_after_cue (it speaks its prompt once); post_interaction_cues play only when their condition is met; nothing in post_interaction_cues is spoken before the interaction."}},{"id":"S08","title":"When the task changes","paragraphs":[{"cue":"B1.4-S08-P1","speaker":"Emilia","text":"Clara has been with us a week. She was instructed on the bunker and on the X-ray work she was brought in for—that is what her instruction record says. Then an assignment slip arrives: can she help with gamma exposures in hall two this afternoon? Clara says, sensibly: 'I've had the briefing, but it was for the bunker job.' That is exactly the right thing to say. Workstation training is given for a workstation and a function, and the regulation repeats it when the function, the work tool or the technology changes. Familiarity with our site does not stretch an instruction to a different task.","screen_text":["Instruction record: bunker · bunker X-ray set · casting radiography","Assignment slip: gamma exposures · hall two · this afternoon"],"start_visual":"DOC-ASSIGNMENT-SLIP beside DOC-INSTRUCTION-RECORD; Clara at the desk; the gamma projector image at 'gamma exposures'.","beats":[{"at":"that is what her instruction record says","show":"Instruction record close-up: area, equipment, task"},{"at":"an assignment slip arrives","show":"Slip close-up"},{"at":"gamma exposures in hall two","show":"EQ-GAMMA-PROJECTOR image"},{"at":"Clara says, sensibly","show":"Clara speech line"}],"documents":["DOC-ASSIGNMENT-SLIP","DOC-INSTRUCTION-RECORD"],"equipment":["EQ-GAMMA-PROJECTOR"],"characters":["Clara"],"clip":"B1.4-S08-P1"},{"cue":"B1.4-S08-P2","speaker":"Emilia","text":"So we do not let Clara decide alone that the earlier briefing is close enough, and we do not make her repeat the whole induction either. We name what has changed—different area, different equipment, different procedure—and we arrange the instruction and the review of her protection and monitoring that the change needs before she starts. The decision sits on the slip in front of you.","screen_text":["Changed: area · equipment · procedure"],"start_visual":"Slip and record side by side; the three differences highlighted between them.","beats":[{"at":"We name what has changed","show":"Three differences highlighted"}],"clip":"B1.4-S08-P2"}],"interaction":{"id":"B1.4-R01","type":"single_choice","prompt_spoken_once":"Before Clara carries out the changed task, what must be checked?","behaviour":"The prompt is spoken automatically exactly once when the activity opens; the narration lead-in never reads it. Manual 'Hear the question' replay. Each option has its own spoken and written feedback (evidence, then next step). Retry without replaying narration; keyboard equivalents (labelled radio controls, Check, Try again, Continue); no auto-advance; no colour-only cues; no timer. Feedback never invents a dose, cause, approval or successful contact.","situation_visible_text":"Instruction record: bunker, bunker X-ray set, casting radiography. Slip: gamma exposures, hall two, this afternoon.","options":[{"id":"coverage","text":"Whether her instruction covers this area, equipment and task — and, as it does not, arrange the specific instruction and protection review before she starts.","correct":true,"feedback":{"spoken":"Yes. The record covers the bunker and its X-ray set; the slip asks for gamma work in hall two—different area, different equipment, different procedure. So the specific instruction for that task and the review of her protection and monitoring are arranged first, with her employer under our agreement where it applies, and the existing role allocation stays as it is. Clara's own remark was the right start.","screen":"Record ≠ slip → arrange specific instruction and protection review first."},"clip":"B1.4-R01-coverage"},{"id":"covered","text":"Nothing: her bunker instruction and her agent certificate cover gamma work too.","correct":false,"feedback":{"spoken":"Both documents are genuine: the record proves instruction for the bunker X-ray work, and the certificate proves the theory test. Neither covers hall two or the gamma projector, and the regulation repeats workstation training when the tool or the technology changes. The slip describes a different task, so the instruction for it has to be arranged before she starts.","screen":"Record and certificate are real, but neither covers this task."},"clip":"B1.4-R01-covered"},{"id":"dosimeter","text":"Only her dosimeter: a new task needs a new dosimeter reading first.","correct":false,"feedback":{"spoken":"Her dosimeter keeps doing its job in hall two, and reviewing her monitoring is part of what the change needs. But a reading does not instruct anyone on a different area, equipment and procedure. The check that decides whether she may do the task is the coverage of her instruction—and that, the record shows, does not reach hall two.","screen":"Monitoring review is part of it; instruction coverage is the decisive check."},"clip":"B1.4-R01-dosimeter"}],"replaces":"B1.4 S08 R01 (free-text handover rehearsal) — replaced one-for-one as a decision on the assignment slip","placement":"Slip and record stay side by side.","clip":"B1.4-R01-prompt"},"sequence":{"cues_before_interaction":["B1.4-S08-P1","B1.4-S08-P2"],"interaction_after_cue":"B1.4-S08-P2","interaction_id":"B1.4-R01","post_interaction_cues":[],"rule":"Play cues_before_interaction in order; open the interaction immediately after interaction_after_cue (it speaks its prompt once); post_interaction_cues play only when their condition is met; nothing in post_interaction_cues is spoken before the interaction."}},{"id":"S09","title":"Who is responsible where","paragraphs":[{"cue":"B1.4-S09-P1","speaker":"Emilia","text":"Back to Daniel at the power station. He is our employee and our designated agent for this radiography job.","screen_text":["Daniel at the plant — our employee, our designated agent for this radiography job"],"start_visual":"Both lanes from S02 again, Daniel's lane active; the same fixed labels 'employer' / 'workplace operator'; Clara's lane shown for comparison.","beats":[{"at":"Back to Daniel at the power station","show":"Lane 1 active"}],"characters":["Daniel","Clara"],"clip":"B1.4-S09-P1"}],"interaction":{"id":"B1.4-I03","type":"single_choice","prompt_spoken_once":"Daniel radiographs welds inside a power station's controlled area. In the regulation's terms, who is responsible for the operational aspects of his protection there?","behaviour":"The prompt is spoken automatically exactly once when the activity opens; the narration lead-in never reads it. Manual 'Hear the question' replay. Each option has its own spoken and written feedback (evidence, then next step). Retry without replaying narration; keyboard equivalents (labelled radio controls, Check, Try again, Continue); no auto-advance; no colour-only cues; no timer. Feedback never invents a dose, cause, approval or successful contact.","situation_visible_text":"Lane 1: Daniel — employer: our company; workplace operator: the power station. Lane 2 (for comparison): Clara — employer: her company; workplace operator: us.","options":[{"id":"plant","text":"The power station, as the operator at whose premises he carries out the assignment.","correct":true,"feedback":{"spoken":"Yes. The operator at whose premises external workers carry out an assignment with an exposure risk is responsible for the operational aspects in the controlled area and for the task. That sits alongside, not instead of, the other roles: our company keeps its duties as his employer, our signed agreement allocates named aspects to us, and Daniel remains our designated agent for the radiography itself, working under the plant's arrangements. The question asked about one responsibility, and the regulation places that one on the plant.","screen":"Workplace operator = the plant; employer and agent duties continue beside it."},"clip":"B1.4-I03-plant"},{"id":"us","text":"Our company, because Daniel is our employee and we sent him there.","correct":false,"feedback":{"spoken":"As his employer we have real duties: compliance with principles and limits, general information, and the pre-assignment file with his dose history—the same file you read for Clara. But the operational aspects inside another operator's controlled area are placed on that operator, unless a signed agreement allocates a named aspect to us. Employment alone does not make us responsible for a plant we do not run.","screen":"Employer duties are real; operational aspects in the plant's area are the plant's."},"clip":"B1.4-I03-us"},{"id":"daniel","text":"Daniel himself, because he is our designated radiation protection agent for the job.","correct":false,"feedback":{"spoken":"Daniel's designation is real and it travels with him: the decree asks for our agent on every worksite, and his checks on our equipment and our procedure continue inside the plant. But an agent's duties are not the operator's responsibility for the operational aspects of protection in its controlled area—monitoring, site-specific training, dose constraints. Those the regulation places on the plant, with our agreement dividing named aspects. Two roles side by side, not one replacing the other.","screen":"Agent duties continue; the operator's responsibility is the plant's."},"clip":"B1.4-I03-daniel"}],"placement":"Lanes stay visible.","clip":"B1.4-I03-prompt"},"sequence":{"cues_before_interaction":["B1.4-S09-P1"],"interaction_after_cue":"B1.4-S09-P1","interaction_id":"B1.4-I03","post_interaction_cues":[],"rule":"Play cues_before_interaction in order; open the interaction immediately after interaction_after_cue (it speaks its prompt once); post_interaction_cues play only when their condition is met; nothing in post_interaction_cues is spoken before the interaction."}},{"id":"S10","title":"What the worker brings, and when the work is abroad","paragraphs":[{"cue":"B1.4-S10-P1","speaker":"Emilia","text":"The information travels partly because the worker carries it. Every worker and external worker must follow the instructions and the regulation, must not expose himself unnecessarily or damage or remove protective means, and reports immediately, at least to the physical control service, any irregularity or defect in the protective means. The article goes on: he contributes as far as possible to his own protection, and in particular he agrees to give the employer, the operator or the head of the undertaking information about his previous and current work that is relevant to ensuring effective and coherent protection for himself and for others. Clara telling us that her briefing covered a different job is that duty in action. The article also stresses the need and the duty to declare a pregnancy as early as possible.","screen_text":["Worker: follow instructions · report defects at once · share relevant information about own work · declare pregnancy early"],"start_visual":"Clara at the desk; ARBIS 26 extract thumbnail; her remark from S08 as a speech line at 'Clara telling us'.","beats":[{"at":"Every worker and external worker","show":"Extract thumbnail"},{"at":"Clara telling us that her briefing covered a different job","show":"Clara speech line"}],"documents":["DOC-REG-EXTRACT"],"characters":["Clara"],"clip":"B1.4-S10-P1"},{"cue":"B1.4-S10-P2","speaker":"Emilia","text":"One more direction: abroad. When we send a radiographer to an undertaking in another country, our company makes sure, through an agreement with the foreign undertaking, that the general principles, the dose limits and any agreed dose constraints are respected; that our worker is subject to individual dosimetric monitoring; that he receives the specific training before the assignment starts; and that he has the necessary protective equipment. And we transmit the results of his monitoring to the exposure register ourselves. The pre-assignment information goes with the radiation passport, in the way the Agency prescribes. I am not giving you a cross-border checklist today; I am showing you that the same questions travel: who has the information, who needs it, and who has agreed to do what.","screen_text":["Domestic assignment: file as read today","Abroad: agreement with the foreign undertaking · radiation passport"],"start_visual":"Two sequential document examples with clear scope labels: 'Assignment in Belgium' (DOC-EXT-WORKER-FILE) then 'Assignment abroad' (passport outline, placeholders). The passport is shown only under the 'abroad' label.","beats":[{"at":"One more direction: abroad","show":"Scope label switches to 'Assignment abroad'"},{"at":"radiation passport","show":"Passport outline (placeholders)"},{"at":"the same questions travel","show":"Back to the domestic file"}],"documents":["DOC-EXT-WORKER-FILE"],"clip":"B1.4-S10-P2"}],"sequence":{"cues_before_interaction":["B1.4-S10-P1","B1.4-S10-P2"],"interaction_after_cue":null,"interaction_id":null,"post_interaction_cues":[]}},{"id":"S11","title":"One worker, connected responsibilities","paragraphs":[{"cue":"B1.4-S11-P1","speaker":"Emilia","text":"Daniel going out and Clara coming in show the same structure from both sides. The employer brings the general information, the identity data and the dose history for two reporting periods, and keeps responsibility for principles and limits. The operator of the workplace organises the operational protection in its controlled area: monitoring, specific training, protective equipment, reading the dose history, dose constraints where needed. A signed agreement between a qualifying external undertaking and the operator can move named aspects—and only those—between them. And the worker follows the instructions, reports defects at once and shares what is relevant about his own work.","screen_text":["Employer · workplace operator · agreement (named aspects) · worker"],"start_visual":"Both lanes with the four parties' labels pulsing in turn; Clara at the control post with Daniel; her file's missing section marked 'requested from employer — pending'.","beats":[{"at":"The employer brings","show":"Lane labels: employer"},{"at":"The operator of the workplace organises","show":"Lane labels: operator"},{"at":"A signed agreement","show":"Agreement thumbnail"},{"at":"the worker follows the instructions","show":"Clara"}],"characters":["Clara","Daniel"],"clip":"B1.4-S11-P1"},{"cue":"B1.4-S11-P2","speaker":"Emilia","text":"A missing result, an instruction that covered a different task, or a colleague reading a whole transfer into one signature should each lead to a precise handover, not a guess. Next time we look at what happens when something is actually wrong: the protective action, the internal information, and the statutory reporting to the Agency with its criteria and time limits—so that a message being passed on is never mistaken for every necessary action being done.","screen_text":["Next: protective action · internal information · statutory reporting"],"start_visual":"Bridge to B1.5: bunker control post with the warning lamp (off).","beats":[{"at":"Next time we look at what happens","show":"Control post view"}],"clip":"B1.4-S11-P2"}],"sequence":{"cues_before_interaction":["B1.4-S11-P1","B1.4-S11-P2"],"interaction_after_cue":null,"interaction_id":null,"post_interaction_cues":[]}}]},{"id":"B1.5","title":"When something is wrong: action, information and reporting","scenes":[{"id":"S01","title":"Welcome back: when an observation becomes a responsibility","paragraphs":[{"cue":"B1.5-S01-P1","speaker":"Emilia","text":"Welcome back. Last time we followed information across company lines, so that it would reach the right people before and after an assignment. Today we look at the moment when that connection becomes urgent: somebody notices that something is wrong. A defect, an unexpected event, a situation that could have hurt someone even though it did not.","screen_text":["A routine check → an unexpected observation"],"start_visual":"Bunker control post at the first word (control unit image, camera monitor showing the empty bunker interior, warning lamp off); Daniel at the post with his check sheet.","beats":[{"at":"somebody notices that something is wrong","show":"Camera monitor framed"}],"equipment":["EQ-XRAY-CONTROL-UNIT"],"characters":["Daniel"],"clip":"B1.5-S01-P1"},{"cue":"B1.5-S01-P2","speaker":"Emilia","text":"Those moments tempt us in two directions. One is to wait until we understand everything before saying anything. The other is to treat a message passed on as the job done. Both are mistakes, and Belgian law is quite specific about why. By the end of this lesson I want you to hold three lanes apart in your head and run them at the same time: the protective action, the information inside our protection organisation, and the statutory notification to the Agency with its criteria and time limits. And I want you to be able to give a first account that is useful precisely because it says what is not yet known.","screen_text":["Lane 1 protective action · Lane 2 internal information · Lane 3 statutory notification"],"start_visual":"Three parallel lanes appear, empty.","beats":[{"at":"the protective action","show":"Lane 1"},{"at":"the information inside our protection organisation","show":"Lane 2"},{"at":"statutory notification to the Agency","show":"Lane 3 with the FANC logo at its end"}],"equipment":["EQ-FANC-LOGO"],"clip":"B1.5-S01-P2"}],"sequence":{"cues_before_interaction":["B1.5-S01-P1","B1.5-S01-P2"],"interaction_after_cue":null,"interaction_id":null,"post_interaction_cues":[]}},{"id":"S02","title":"Tuesday, 10:12, in the bunker","paragraphs":[{"cue":"B1.5-S02-P1","speaker":"Emilia","text":"Here is the case we will follow. Tuesday morning, Daniel is radiographing a batch of castings in our bunker with the X-ray set. He is at the control post outside; the exposure is running and the warning light is on. At twelve minutes past ten a colleague from the workshop, Tom—a fitter, not one of our exposed workers, so he wears no dosimeter—opens the bunker door to fetch a tool he had left inside. The door interlock should have cut the exposure the instant the door opened. It did not. Daniel sees the door move on the camera, stops the exposure from the control post and calls Tom back out. Tom was in the doorway for a few seconds.","screen_text":["Tuesday 10:12 · bunker · X-ray set in exposure","Door opened — interlock did not cut the exposure","Exposure stopped manually"],"start_visual":"Bunker layout with roof (plan + control post); state before: 'EXPOSURE RUNNING' lamp on in the plan, room empty. Tom is NOT depicted as a person: the door movement appears only on the control-post camera monitor as a door-open indication, and in text. Daniel at the control post presses stop (supplied pose or cut). State after: lamp off, 'OUT OF USE / HELD'.","beats":[{"at":"the exposure is running and the warning light is on","show":"Plan: lamp on; room empty"},{"at":"opens the bunker door","show":"Camera monitor: door-open indication only"},{"at":"It did not","show":"FACT badge: 'interlock did not cut the exposure'"},{"at":"stops the exposure from the control post","show":"Lamp off; HELD/OUT OF USE state"}],"equipment":["EQ-XRAY-CONTROL-UNIT","EQ-BUNKER-REFERENCE"],"characters":["Daniel"],"clip":"B1.5-S02-P1"},{"cue":"B1.5-S02-P2","speaker":"Emilia","text":"Stop there and notice what we know and what we do not. We know the time, the place, the equipment, what Tom did, what the interlock did not do, and what Daniel did. We do not know why the interlock failed, and we do not know what dose Tom received. Seconds in the doorway of a bunker with an X-ray set running is not something to wave away, and it is not something to dramatise either; it is something to have assessed by the people and methods that can do it. Guessing either way helps nobody. We also cannot say that the interlock worked properly yesterday just because nobody opened the door yesterday.","screen_text":["Known: time, place, equipment, what Tom did, what the interlock did not do, what Daniel did","Unknown: why it failed · Tom's dose"],"start_visual":"Two short columns beside the plan: Known / Unknown; NOT ESTABLISHED badges on cause and dose.","beats":[{"at":"notice what we know and what we do not","show":"Known column fills"},{"at":"We do not know why the interlock failed","show":"NOT ESTABLISHED: cause"},{"at":"what dose Tom received","show":"NOT ESTABLISHED: dose"}],"clip":"B1.5-S02-P2"},{"cue":"B1.5-S02-P3","speaker":"Emilia","text":"Daniel's first words to me on the phone were good ones: 'The interlock didn't cut the exposure when Tom opened the door. I've stopped the exposure and the bunker is out of use. Tom is out of the bunker and says he feels nothing unusual, but I don't know his dose. I don't know why it failed.' Observed, done, unknown. That is a first account someone can act on. Notice what he has not said: he has not blamed Tom, he has not reassured anyone about a dose he cannot know—feeling nothing says nothing about dose—and he has not diagnosed the interlock.","screen_text":["Observed · Done · Unknown"],"start_visual":"Daniel on the phone (supplied pose); the event record DOC-EVENT-RECORD first lines fill as he speaks.","beats":[{"at":"Daniel's first words to me","show":"Record: observation line"},{"at":"I've stopped the exposure","show":"Record: status line"},{"at":"I don't know his dose","show":"Record: unknowns"}],"documents":["DOC-EVENT-RECORD"],"characters":["Daniel"],"clip":"B1.5-S02-P3"}],"sequence":{"cues_before_interaction":["B1.5-S02-P1","B1.5-S02-P2","B1.5-S02-P3"],"interaction_after_cue":null,"interaction_id":null,"post_interaction_cues":[]},"status_badges":[{"kind":"fact","label":"Interlock did not cut the exposure","explanation":"Observed by Daniel at 10:12: the door opened and the exposure continued until he stopped it manually from the control post."},{"kind":"held","label":"Bunker out of use","explanation":"A safety device no longer meets the requirements; the installation stays out of use until the deficiency is corrected and the checks required by the procedure and the expert are done."},{"kind":"not_established","label":"Cause and Tom's dose not established","explanation":"Why the interlock failed and what dose Tom received are for the expert's study and the proper dosimetry methods; 'feels nothing unusual' says nothing about dose."}]},{"id":"S03","title":"Lane one and lane two: protect, and inform the right people","paragraphs":[{"cue":"B1.5-S03-P1","speaker":"Emilia","text":"Lane one is the protective action, and most of it has already happened because it was in Daniel's instructions. The exposure is stopped. The installation stays out of use—you know from the lesson on effective protection that a device or installation that no longer meets the requirements is taken out of use until the deficiency is corrected. Tom stays available and the facts the expert will need to assess his dose are preserved under our response procedure—where he stood, for how long, the set's settings and the exposure log, nothing changed on the control panel. Nobody tests the interlock by opening the door again during an exposure. The agent's duties include taking the prescribed urgent measures in an incident and passing the information on immediately; none of that is an invitation to investigate the fault himself.","screen_text":["Lane 1 — protective action: exposure stopped · bunker out of use · Tom available · facts preserved · no re-test by opening the door"],"start_visual":"Lane 1 fills with Daniel's actions at the control post (nothing touched on the panel; exposure log preserved).","beats":[{"at":"The exposure is stopped","show":"Lane 1 step"},{"at":"stays out of use","show":"Lane 1 step"},{"at":"Nobody tests the interlock by opening the door again","show":"Lane 1: crossed text 'no re-test'"}],"characters":["Daniel"],"clip":"B1.5-S03-P1"},{"cue":"B1.5-S03-P2","speaker":"Emilia","text":"Lane two is information inside the protection organisation, and it runs at the same time as lane one, not after it. The agent informs the head of the physical control service and the recognised expert of every abnormal situation—so Daniel calls me and leaves the agreed message for the expert at the organisation we contract; as the radiographer who stopped the work he also tells Luc, his supervisor. I do not assume the message landed: I call the expert myself and I brief our head of establishment, because he is the one who will notify the Agency. Then my own duties start. Whenever an event occurs that could endanger the safety or health of people, the head of the physical control service immediately takes all useful measures against the danger discovered, where appropriate in consultation with the recognised expert. And he warns the recognised physician in charge of the workers' medical surveillance in three cases: whenever an exposed worker has to be subjected to an emergency exposure; whenever a person, exposed worker or not, has received an accidental exposure exceeding the dose limits; and whenever an accident occurs that involves a serious exposure hazard. We do not know Tom's dose yet, so I will be speaking to the physician about Tom today rather than waiting for a number to tell me whether I must.","screen_text":["Lane 2 — Daniel → Emilia, expert (message), Luc","Emilia → expert (direct), head of establishment, physician"],"start_visual":"Lane 2 fills in parallel with lane 1 (no arrow from lane 1 to lane 2): Daniel's calls (Emilia, expert message, Luc); Emilia's calls (expert direct, head of establishment, physician). Each person performs a distinct action: Daniel phone; Luc at the hall door; Emilia at her desk.","beats":[{"at":"Lane two is information","show":"Lane 2 appears beside lane 1"},{"at":"Daniel calls me","show":"Daniel → Emilia"},{"at":"tells Luc, his supervisor","show":"Daniel → Luc (Luc at the hall door)"},{"at":"I call the expert myself","show":"Emilia → expert: 'reached' only when confirmed"},{"at":"I brief our head of establishment","show":"Emilia → head of establishment"},{"at":"warns the recognised physician","show":"Emilia → physician (role, no person)"}],"characters":["Daniel","Luc","Emilia"],"clip":"B1.5-S03-P2"},{"cue":"B1.5-S03-P3","speaker":"Emilia","text":"The regulation then gives the recognised expert a job—a thorough study of the circumstances and of the doses received, using the proper methods of individual dosimetry, ending in a report to the operator recommending measures to correct the shortcoming and prevent a repeat. And it tells the operator, or failing one the head of the undertaking, to warn as soon as possible the Agency—communicating according to the modalities and criteria the Agency has set—the government's coordination and crisis centre and the 100 emergency call system, and, where an accident involves a serious exposure hazard, the mayor and the emergency services as well. Which of those calls our event requires is written in our emergency procedure, drawn up with the expert; the Agency's 'modalities and criteria' are the subject of the rest of this lesson. What matters now is that these duties run alongside each other. We do not wait for a written report before protecting Tom, and telling me does not complete anyone's notification to the Agency.","screen_text":["Expert: study of circumstances and doses → report to the operator","Operator: warn the Agency (per its criteria), crisis centre, 100 — mayor and emergency services where a serious hazard","Duties run alongside each other"],"start_visual":"Lane 3 outlined with the FANC logo; the emergency procedure thumbnail; no arrows between lanes.","beats":[{"at":"gives the recognised expert a job","show":"Expert step in lane 2"},{"at":"to warn as soon as possible the Agency","show":"Lane 3 with FANC logo"},{"at":"run alongside each other","show":"All three lanes shown parallel"}],"equipment":["EQ-FANC-LOGO"],"clip":"B1.5-S03-P3"}],"sequence":{"cues_before_interaction":["B1.5-S03-P1","B1.5-S03-P2","B1.5-S03-P3"],"interaction_after_cue":null,"interaction_id":null,"post_interaction_cues":[]}},{"id":"S04","title":"Daniel's next step","paragraphs":[{"cue":"B1.5-S04-P1","speaker":"Emilia","text":"Put yourself beside Daniel at the control post, a minute after he stopped the exposure. The cause is unknown; his instruction says the bunker stays out of use and the service is called.","screen_text":["Cause unknown · bunker out of use · service to be called"],"start_visual":"Control post with the HELD state and the NOT ESTABLISHED badge; Daniel beside the control unit.","beats":[{"at":"a minute after he stopped the exposure","show":"Control post state"}],"characters":["Daniel"],"clip":"B1.5-S04-P1"}],"interaction":{"id":"B1.5-I01","type":"single_choice","prompt_spoken_once":"The interlock failed to stop the exposure when the door opened, and Daniel has stopped the exposure. What does he do next?","behaviour":"The prompt is spoken automatically exactly once when the activity opens; the narration lead-in never reads it. Manual 'Hear the question' replay. Each option has its own spoken and written feedback (evidence, then next step). Retry without replaying narration; keyboard equivalents (labelled radio controls, Check, Try again, Continue); no auto-advance; no colour-only cues; no timer. Feedback never invents a dose, cause, approval or successful contact.","situation_visible_text":"Exposure stopped manually; bunker out of use; cause and dose not established.","options":[{"id":"keep","text":"Keep the bunker out of use, keep Tom and the exposure facts available, and call the service at once.","correct":true,"feedback":{"spoken":"Yes. That is lane one and lane two together: the protective action his instruction assigns, Tom and the facts needed for the dose assessment kept available, and the head of service and the expert informed immediately—Luc too, as his supervisor. He reports what he saw and leaves the cause and the dose to the people and methods that can establish them.","screen":"Out of use · facts preserved · service called now."},"clip":"B1.5-I01-keep"},{"id":"rerun","text":"Re-run the exposure with the door open to confirm the interlock fault before reporting it.","correct":false,"feedback":{"spoken":"The wish to be sure is understandable, and the fault will be investigated—by the people and procedures authorised for it, after the installation has been taken out of use. Reproducing it means repeating the exposure with the protection defeated: a new risk created on purpose. The report does not need a demonstrated cause to be worth making; it needs the observation.","screen":"No re-test with the door open; report the observation."},"clip":"B1.5-I01-rerun"},{"id":"finish","text":"Finish the batch carefully and note the interlock for the expert's next visit.","correct":false,"feedback":{"spoken":"Noting it for the expert is part of what happens—the expert does hear, through the service, today. But an installation whose safety device has just failed no longer meets the requirements and stays out of use until corrected; finishing the batch is exactly what the rule forbids, and an abnormal situation is reported immediately, not kept for a scheduled visit.","screen":"Out of use until corrected; report immediately."},"clip":"B1.5-I01-finish"}],"placement":"Control post state stays visible.","clip":"B1.5-I01-prompt"},"sequence":{"cues_before_interaction":["B1.5-S04-P1"],"interaction_after_cue":"B1.5-S04-P1","interaction_id":"B1.5-I01","post_interaction_cues":[],"rule":"Play cues_before_interaction in order; open the interaction immediately after interaction_after_cue (it speaks its prompt once); post_interaction_cues play only when their condition is met; nothing in post_interaction_cues is spoken before the interaction."}},{"id":"S05","title":"Give the facts their own place","paragraphs":[{"cue":"B1.5-S05-P1","speaker":"Emilia","text":"Before we reach the Agency, let us make Daniel's account useful to someone who was not there. 'Something went wrong this morning' helps nobody. 'At 10:12, bunker one, X-ray set in exposure, the door interlock did not cut the exposure when the door was opened; exposure stopped manually; bunker out of use' gives the next person facts to work with. Two times matter: when the event happened and when it was discovered. Here they coincide; with a slow leak or a mislabelled source they might be weeks apart, and the reporting clock runs from the event or from its discovery.","screen_text":["What · where · when (happened; discovered)"],"start_visual":"DOC-EVENT-RECORD page: observation field close-up with time/place/equipment/what; 'discovered at' field.","beats":[{"at":"At 10:12, bunker one","show":"Observation field"},{"at":"Two times matter","show":"Event time / discovery time fields"}],"documents":["DOC-EVENT-RECORD"],"clip":"B1.5-S05-P1"},{"cue":"B1.5-S05-P2","speaker":"Emilia","text":"If Daniel suspects a cause—he thinks the door switch has been sticking—he may say so, labelled as a suspicion with his reason. A suspicion is not a finding. The same discipline applies to dose. 'Not yet established' is an honest description of Tom's dose; it must not be turned into a zero because a form has a box. I might ask Daniel: what did you see yourself, what did Tom tell you, and what has already been done? Those three questions keep the record clean. Our teaching record is a handover aid; the statutory notification has its own prescribed contents, which we will come to.","screen_text":["Suspected cause — labelled as suspicion","Dose: not yet established"],"start_visual":"Close-ups: suspected-cause field ('suspected: door switch sticking — reason'); dose field 'not yet established'; status badges on the form support understanding without dominating it.","beats":[{"at":"labelled as a suspicion","show":"Suspected-cause field"},{"at":"'Not yet established' is an honest description","show":"Dose field; NOT ESTABLISHED badge"},{"at":"what did you see yourself","show":"Three question labels"}],"documents":["DOC-EVENT-RECORD"],"clip":"B1.5-S05-P2"}],"sequence":{"cues_before_interaction":["B1.5-S05-P1","B1.5-S05-P2"],"interaction_after_cue":null,"interaction_id":null,"post_interaction_cues":[]}},{"id":"S06","title":"Lane three: who notifies the Agency, and for which establishments","paragraphs":[{"cue":"B1.5-S06-P1","speaker":"Emilia","text":"Lane three is the statutory notification, and its rules are in a technical regulation of the Agency: the regulation of 17 June 2020 setting the criteria for notifying significant events, as amended. What is a significant event? Any event—including a human error, a near-miss, an accident, an unauthorised act—that has consequences, even potential consequences, for safety, security, radiation protection or the environment. Tom's few seconds in the doorway are a significant event whatever his dose turns out to be, because the consequences could have been serious.","screen_text":["Significant event: consequences, even potential, for safety, security, radiation protection or the environment"],"start_visual":"Lane 3 with the actual FANC logo; the technical-regulation extract thumbnail (17 June 2020, as amended).","beats":[{"at":"the regulation of 17 June 2020","show":"Extract thumbnail"},{"at":"What is a significant event","show":"Definition label"}],"documents":["DOC-REG-EXTRACT"],"equipment":["EQ-FANC-LOGO"],"clip":"B1.5-S06-P1"},{"cue":"B1.5-S06-P2","speaker":"Emilia","text":"Who is covered? All class two and three establishments, with one exception for establishments whose physical control is exercised by a shared service that also serves a class one establishment—they follow the class one route. Import, transit and export, and the transport of class seven dangerous goods, have their own criteria in the same regulation, and so do persons subject to the security decree. So a site event and a transport event are not the same route; today we stay with the establishment route.","screen_text":["Scope: class II and III establishments (exception: shared service with class I) · separate routes for transport and security"],"start_visual":"Scope label; transport/security routes shown as separate thin lanes, not followed.","beats":[{"at":"All class two and three establishments","show":"Scope label"},{"at":"not the same route","show":"Separate thin lanes"}],"clip":"B1.5-S06-P2"},{"cue":"B1.5-S06-P3","speaker":"Emilia","text":"Who notifies? The head of the establishment or the head of the undertaking. For the security rubrics, the delegate for radiological security may also notify on the operator's behalf. Notice who is not named: the head of the physical control service, and the agent. In our company the operator has designated our managing director as head of the establishment; I prepare the notification with him and make sure he has the facts, but my title does not silently make me the notifier, and Daniel's call to me does not make the notification happen. For the exercises that follow, the applicable scope is given and the responsible assessment has identified the criteria; your job is to use the rules correctly, not to classify every event yourself.","screen_text":["Notifier: head of the establishment or of the undertaking (ARB for security rubrics)","Not the head of service · not the agent"],"start_visual":"Role caption 'head of establishment — notifier' (role only, no new face) beside the FANC logo; Emilia caption 'prepares with him'.","beats":[{"at":"Who notifies","show":"Notifier caption"},{"at":"Notice who is not named","show":"Text: 'not the head of service, not the agent'"},{"at":"Daniel's call to me does not make the notification happen","show":"Lane 2 → lane 3: no arrow"}],"clip":"B1.5-S06-P3"}],"sequence":{"cues_before_interaction":["B1.5-S06-P1","B1.5-S06-P2","B1.5-S06-P3"],"interaction_after_cue":null,"interaction_id":null,"post_interaction_cues":[]}},{"id":"S07","title":"Use the criterion, not a remembered number","paragraphs":[{"cue":"B1.5-S07-P1","speaker":"Emilia","text":"The regulation's table lists the events to be notified, and for each one two things: whether successful direct contact with the Agency is required and by when, and whether an INES evaluation applies. Here is a small dated extract. Read the condition on the left as carefully as the deadline beside it; a remembered deadline without its condition is easy to apply to the wrong event.","screen_text":["Criterion → direct contact (by when?) · INES evaluation?"],"start_visual":"DOC-CRITERION-EXTRACT (one readable excerpt with its source and date), two columns explained.","beats":[{"at":"The regulation's table lists","show":"Extract page"},{"at":"Read the condition on the left","show":"Condition column highlighted"}],"documents":["DOC-CRITERION-EXTRACT"],"clip":"B1.5-S07-P1"},{"cue":"B1.5-S07-P2","speaker":"Emilia","text":"Criterion 1.5: loss or failure of equipment that fulfils a safety function. Direct contact no later than the next working day; INES evaluation yes. Criterion 1.4: non-compliance with the safety logic, or application of an unsuitable safety logic, that leads or may lead to unforeseen behaviour of the installation. Direct contact immediately; INES evaluation yes. Those are two different descriptions. An interlock that fails is equipment with a safety function; whether the way it was wired or bypassed also amounts to a safety-logic failure is a question for the responsible assessment with the expert, not for Daniel at the control post.","screen_text":["1.5 — equipment with a safety function fails: next working day · INES yes","1.4 — safety logic not complied with / unsuitable: immediately · INES yes"],"start_visual":"Two rows close-up in turn.","beats":[{"at":"Criterion 1.5","show":"Row 1.5"},{"at":"Criterion 1.4","show":"Row 1.4"},{"at":"a question for the responsible assessment","show":"Text label"}],"clip":"B1.5-S07-P2"},{"cue":"B1.5-S07-P3","speaker":"Emilia","text":"Alongside the direct-contact column stands a separate duty. For every event that meets one or more criteria, a written notification is sent by the notifier within 48 hours of the event or its discovery—or sooner if the Agency asks—to the Agency's event address. The written notification does not replace an immediate call or a next-working-day contact, and a call does not replace the written notification. In real work, our procedure holds the current complete table and the Agency's contact details; if the regulation changes, the training and the procedure are checked against the new text. This extract is for learning the mechanism.","screen_text":["Written notification within 48 h — every notifiable event — separate from the call"],"start_visual":"Separate line under the extract: '48 h written notification'.","beats":[{"at":"a written notification is sent","show":"48 h line"},{"at":"our procedure holds the current complete table","show":"Procedure thumbnail"}],"clip":"B1.5-S07-P3"}],"sequence":{"cues_before_interaction":["B1.5-S07-P1","B1.5-S07-P2","B1.5-S07-P3"],"interaction_after_cue":null,"interaction_id":null,"post_interaction_cues":[]}},{"id":"S08","title":"When two criteria apply","paragraphs":[{"cue":"B1.5-S08-P1","speaker":"Emilia","text":"Add one established fact to our case: the responsible assessment, with the expert, concludes that both criterion 1.5 and criterion 1.4 apply. Not guessed from the first phone call—established. The regulation says what happens when an event meets several criteria: the strictest requirements for direct contact apply.","screen_text":["Established by the responsible assessment with the expert: 1.5 AND 1.4 apply"],"start_visual":"One visible timeline (10:12 event → now) with both criteria placed on it; their contact requirements shown as two markers (next working day; immediately).","beats":[{"at":"both criterion 1.5 and criterion 1.4 apply","show":"Both markers on the timeline"},{"at":"the strictest requirements for direct contact apply","show":"'immediately' marker emphasised"}],"clip":"B1.5-S08-P1"}],"interaction":{"id":"B1.5-I02","type":"single_choice","prompt_spoken_once":"The responsible assessment establishes that both criterion 1.5, next working day, and criterion 1.4, immediately, apply. By when must successful direct contact be made?","behaviour":"The prompt is spoken automatically exactly once when the activity opens; the narration lead-in never reads it. Manual 'Hear the question' replay. Each option has its own spoken and written feedback (evidence, then next step). Retry without replaying narration; keyboard equivalents (labelled radio controls, Check, Try again, Continue); no auto-advance; no colour-only cues; no timer. Feedback never invents a dose, cause, approval or successful contact.","situation_visible_text":"Timeline: event 10:12; criteria 1.5 (next working day) and 1.4 (immediately) both established.","options":[{"id":"immediately","text":"Immediately — the stricter requirement governs when several criteria apply.","correct":true,"feedback":{"spoken":"Exactly. When an event meets more than one criterion, the strictest requirements for direct contact apply. Criterion 1.4 requires immediate contact, so that is the point on the timeline—and the written notification within 48 hours remains a separate duty that the call does not discharge.","screen":"Strictest governs: immediately. 48 h written notification stays separate."},"clip":"B1.5-I02-immediately"},{"id":"next_day","text":"By the next working day — the equipment criterion was identified first.","correct":false,"feedback":{"spoken":"Criterion 1.5 is genuinely met, and on its own it would give the next working day. But the order in which criteria were identified changes nothing. Once both apply, the regulation applies the strictest direct-contact requirement, and criterion 1.4 says immediately. Choosing the gentler deadline because it was noticed first is exactly the error the rule is written to prevent.","screen":"Order of identification is irrelevant; the strictest applies."},"clip":"B1.5-I02-next_day"},{"id":"48h","text":"Within 48 hours — the written notification covers both criteria.","correct":false,"feedback":{"spoken":"The 48-hour written notification is a real and separate obligation that applies to every notifiable event, so it is on the timeline too. It does not replace the direct-contact requirement in the table, which here is immediate. Sending a document on time is not the same as speaking to the Agency's duty officer now.","screen":"Written notification is separate; direct contact is immediate."},"clip":"B1.5-I02-48h"}],"placement":"Timeline stays visible.","clip":"B1.5-I02-prompt"},"sequence":{"cues_before_interaction":["B1.5-S08-P1"],"interaction_after_cue":"B1.5-S08-P1","interaction_id":"B1.5-I02","post_interaction_cues":[],"rule":"Play cues_before_interaction in order; open the interaction immediately after interaction_after_cue (it speaks its prompt once); post_interaction_cues play only when their condition is met; nothing in post_interaction_cues is spoken before the interaction."}},{"id":"S09","title":"A message left is not successful direct contact","paragraphs":[{"cue":"B1.5-S09-P1","speaker":"Emilia","text":"Our head of establishment calls the Agency's general duty roster and reaches voicemail. He leaves a message. Is the immediate direct contact made? The regulation defines successful direct contact as contact with the person on duty in the Agency's general duty roster, with a view to a direct, oral and understandable notification of the event. And it says in so many words what does not count: a message on the Agency's answering machine or a mobile, a text, an email, a fax—or speaking to a person who is not on duty in that roster at the time.","screen_text":["Successful direct contact = direct, oral, understandable, with the person on the duty roster","Not: voicemail, text, email, fax, someone off duty"],"start_visual":"Two clear phone/log states beside each other: 'Attempt 1 — voicemail' (unsuccessful) and 'Successful direct contact' (empty, not yet); no real numbers; no simulated call audio.","beats":[{"at":"reaches voicemail","show":"Log state: attempt — voicemail"},{"at":"The regulation defines successful direct contact","show":"Definition label"},{"at":"what does not count","show":"List of non-counting forms"}],"clip":"B1.5-S09-P1"},{"cue":"B1.5-S09-P2","speaker":"Emilia","text":"So 'I left a detailed message' and 'the required contact succeeded' are different statements, and the record must say which one is true. The regulation adds that the notifier makes as many attempts as needed to actually obtain successful direct contact. There is no rule that two attempts are enough, and no rule that a written message closes the duty. Meanwhile lane one and lane two keep running: the expert's dose assessment for Tom is under way, the bunker stays out of use, the physician has been called. Daniel does not have to take over the notification. But his handover must not say 'the Agency has been notified' if what has happened is a voicemail.","screen_text":["'Left a message' ≠ 'contact succeeded' · as many attempts as needed","Lanes 1 and 2 keep running"],"start_visual":"Log: attempt lines; lanes 1–2 markers active; Daniel's handover line 'Agency: attempts ongoing'.","beats":[{"at":"as many attempts as needed","show":"Attempt lines"},{"at":"Meanwhile lane one and lane two keep running","show":"Lane markers"},{"at":"if what has happened is a voicemail","show":"Record line: 'Agency: not yet reached'"}],"clip":"B1.5-S09-P2"}],"interaction":{"id":"B1.5-I03","type":"single_choice","prompt_spoken_once":"The head of establishment calls the Agency's duty roster and reaches only voicemail. What does the contact record say, and what happens next?","behaviour":"The prompt is spoken automatically exactly once when the activity opens; the narration lead-in never reads it. Manual 'Hear the question' replay. Each option has its own spoken and written feedback (evidence, then next step). Retry without replaying narration; keyboard equivalents (labelled radio controls, Check, Try again, Continue); no auto-advance; no colour-only cues; no timer. Feedback never invents a dose, cause, approval or successful contact.","situation_visible_text":"Log: attempt 1 — voicemail. Successful direct contact: not yet.","options":[{"id":"unsuccessful","text":"An unsuccessful attempt is recorded, and calls continue until someone on the duty roster answers.","correct":true,"feedback":{"spoken":"Yes. That records what actually happened and keeps the obligation open. The regulation defines successful direct contact as direct, oral and understandable contact with the person on duty, and requires as many attempts as needed. Protective action and internal information continue in parallel.","screen":"Record the attempt; keep calling; lanes 1–2 continue."},"clip":"B1.5-I03-unsuccessful"},{"id":"successful","text":"Successful contact is recorded, because the voicemail contained all the information.","correct":false,"feedback":{"spoken":"A complete voicemail is good practice and may help the duty officer later. But the content of the message does not change its status: the regulation says explicitly that a message on the answering machine is not successful direct contact. Recording it as such would make the file say something that did not happen.","screen":"Voicemail is not direct contact, however complete."},"clip":"B1.5-I03-successful"},{"id":"written","text":"The written notification is sent at once and the contact is treated as made.","correct":false,"feedback":{"spoken":"Sending the written notification early is fine—it is due within 48 hours anyway, and doing it now is not wrong. It is a separate duty. It does not satisfy the direct-contact requirement, which is about speaking to the duty officer. The calls must go on until one succeeds.","screen":"Written notification is separate; calls continue."},"clip":"B1.5-I03-written"}],"placement":"Log states stay visible.","clip":"B1.5-I03-prompt"},"sequence":{"cues_before_interaction":["B1.5-S09-P1","B1.5-S09-P2"],"interaction_after_cue":"B1.5-S09-P2","interaction_id":"B1.5-I03","post_interaction_cues":[],"rule":"Play cues_before_interaction in order; open the interaction immediately after interaction_after_cue (it speaks its prompt once); post_interaction_cues play only when their condition is met; nothing in post_interaction_cues is spoken before the interaction."}},{"id":"S10","title":"Write what is known, without waiting for the final explanation","paragraphs":[{"cue":"B1.5-S10-P1","speaker":"Emilia","text":"Move the case forward: direct contact has succeeded and is recorded. Now the written notification, within 48 hours of the event or its discovery. The regulation says what it must contain at minimum, and the list has a logic you already know from Daniel's first account: what happened, where and when, and when it was discovered; what equipment and sources were involved; what the actual consequences are, including doses where they are known; what the suspected causes are—suspected, the regulation's own word; what urgent measures were taken; who is managing the event; and, where it applies, the physician's follow-up proposal and the INES level the recognised expert proposes. It ends with the notifier's name and signature and with anything else the Agency asks for. The complete list is in the reference reader; what I want you to hear is that it is built from facts known at that moment.","screen_text":["Initial notification: facts known at that moment · suspected causes · measures taken"],"start_visual":"DOC-NOTIFICATION readable sample page: fields filled with the case; 'Dose: under assessment' and 'Suspected cause' explicitly marked; nothing below the fold.","beats":[{"at":"what happened, where and when","show":"Fields: what/where/when"},{"at":"what the suspected causes are","show":"Suspected-cause field"},{"at":"including doses where they are known","show":"Dose field: 'under assessment'"},{"at":"reference reader","show":"Reference reader control indicated"}],"documents":["DOC-NOTIFICATION"],"clip":"B1.5-S10-P1"},{"cue":"B1.5-S10-P2","speaker":"Emilia","text":"Two phrases in that requirement carry the whole idea: 'suspected causes' and 'on the basis of the facts known at that moment'. The initial notification is not the investigation report. If we waited for every answer, we would miss the 48 hours. Equally, it must not present a convenient assumption as a result. Someone says: 'Put zero for Tom's dose, otherwise the form looks unfinished.' We do not know that zero is true; the expert's dose assessment is under way.","screen_text":["'Put zero for Tom's dose, otherwise the form looks unfinished.'"],"start_visual":"Colleague's suggestion as a speech line beside the dose field.","beats":[{"at":"Someone says","show":"Speech line"}],"clip":"B1.5-S10-P2"}],"interaction":{"id":"B1.5-I04","type":"single_choice","prompt_spoken_once":"The written notification is due, but Tom's dose and the cause of the interlock failure are not yet established. What does the notifier do?","behaviour":"The prompt is spoken automatically exactly once when the activity opens; the narration lead-in never reads it. Manual 'Hear the question' replay. Each option has its own spoken and written feedback (evidence, then next step). Retry without replaying narration; keyboard equivalents (labelled radio controls, Check, Try again, Continue); no auto-advance; no colour-only cues; no timer. Feedback never invents a dose, cause, approval or successful contact.","situation_visible_text":"Notification sample: dose — under assessment; cause — suspected (door switch), not established; measures — listed.","options":[{"id":"send_known","text":"Send it on time with the known facts, the unknowns named and the measures taken.","correct":true,"feedback":{"spoken":"Right. The regulation asks for the facts known at that moment, suspected causes labelled as such, and the measures taken. 'Dose under assessment' is a true statement on the form in front of you; the dosimetry result and the cause follow in the investigation and the final report, which have their own requirements.","screen":"On time, true, unknowns named."},"clip":"B1.5-I04-send_known"},{"id":"hold","text":"Hold it until the expert has established the dose and the cause.","correct":false,"feedback":{"spoken":"The expert's study is real and it will produce those answers—in the final report, due within two calendar months. The written notification has its own deadline—48 hours from the event or its discovery—and is explicitly based on the facts known at that moment. Waiting confuses the initial notification with the final report.","screen":"48 h notification ≠ final report; send now with what is known."},"clip":"B1.5-I04-hold"},{"id":"zero","text":"Enter zero dose and no consequences so the form is complete, and correct it later.","correct":false,"feedback":{"spoken":"The wish for a complete-looking form is understandable, and the form is complete when every field is true. An unknown is not a zero: that entry would make a factual claim nobody can support, in a document sent to the regulator. The honest form says the dose is under assessment, and the later report carries the result.","screen":"Unknown ≠ zero; 'under assessment' is the complete entry."},"clip":"B1.5-I04-zero"}],"placement":"Notification sample stays visible with the dose field framed.","clip":"B1.5-I04-prompt"},"sequence":{"cues_before_interaction":["B1.5-S10-P1","B1.5-S10-P2"],"interaction_after_cue":"B1.5-S10-P2","interaction_id":"B1.5-I04","post_interaction_cues":[],"rule":"Play cues_before_interaction in order; open the interaction immediately after interaction_after_cue (it speaks its prompt once); post_interaction_cues play only when their condition is met; nothing in post_interaction_cues is spoken before the interaction."}},{"id":"S11","title":"No INES rating does not mean no notification","paragraphs":[{"cue":"B1.5-S11-P1","speaker":"Emilia","text":"Two more things on the extract. First, a trap. Look at criterion 1.22: repeated non-compliance with the deadlines for implementing actions proposed by the recognised expert. Keep all of that wording; it is not a label for any late action. For that criterion the table says direct contact not required and INES evaluation no. Yet the written notification within 48 hours still applies, because it applies to every event that meets a criterion. 'No' in one column is never 'no reporting' across the row.","screen_text":["1.22 — direct contact not required · INES no · written notification still within 48 h"],"start_visual":"Criterion extract: row 1.22 shown over the same incident file (concise, not a badge wall).","beats":[{"at":"Look at criterion 1.22","show":"Row 1.22"},{"at":"'No' in one column is never 'no reporting'","show":"48 h line pulses"}],"documents":["DOC-CRITERION-EXTRACT"],"clip":"B1.5-S11-P1"},{"cue":"B1.5-S11-P2","speaker":"Emilia","text":"Second, INES, the international scale of nuclear and radiological events. Where the table says yes, or where the Agency so judges, the recognised expert proposes an INES level in the written notification and the Agency approves it. For an event meeting several criteria the level follows the most penalising one. A confirmed level 1 or higher means the head of the establishment proposes a communication for publication on the Agency's website; level 2 or higher also means a press release. Daniel does not rate the event, and a low rating is not permission to use the bunker again.","screen_text":["INES: expert proposes, Agency approves · most penalising criterion · level 1+: web communication; level 2+: press release","A low rating is not permission to use the bunker again"],"start_visual":"Notification sample's 'proposed INES level' field; HELD state remains on the bunker plan.","beats":[{"at":"the recognised expert proposes an INES level","show":"INES field"},{"at":"not permission to use the bunker again","show":"HELD state pulses"}],"documents":["DOC-NOTIFICATION"],"clip":"B1.5-S11-P2"}],"sequence":{"cues_before_interaction":["B1.5-S11-P1","B1.5-S11-P2"],"interaction_after_cue":null,"interaction_id":null,"post_interaction_cues":[]}},{"id":"S12","title":"A security event follows its own route","paragraphs":[{"cue":"B1.5-S12-P1","speaker":"Emilia","text":"A failed interlock is a safety problem. A different kind of event needs a different route, and it must not get lost inside a technical-fault report. Suppose, in a separate example, that a gamma projector containing a sealed source is found to be missing from the locked storage at a client's site, or that someone has tried to take it. The source is a radioactive substance subject to the security decree, so three things happen that have nothing to do with interlocks.","screen_text":["Separate example: a sealed source missing from locked storage at a client's site"],"start_visual":"Separate source-security context: a locked storage cabinet at a client's site (no confidential arrangement), gamma projector image with 'sealed source'; clearly labelled 'different example'.","beats":[{"at":"Suppose, in a separate example","show":"Context switch label"},{"at":"The source is a radioactive substance","show":"EQ-GAMMA-PROJECTOR image"}],"equipment":["EQ-GAMMA-PROJECTOR"],"clip":"B1.5-S12-P1"},{"cue":"B1.5-S12-P2","speaker":"Emilia","text":"First, under the security decree, any person who observes a malicious act informs the operator or the delegate for radiological security immediately—that duty belongs to everyone on the site, whatever their title. Second, the operator, or the ARB on the operator's instruction, reports every malicious act and every unauthorised access or attempt at access to the competent police services, and any other security incident the operator judges should go to them. Third, every security incident the operator reports to the police is also reported to the Agency. And after the event, the operator draws up an evaluation report on causes, consequences and additional measures, available to the Agency at all times.","screen_text":["Anyone → operator or ARB immediately","Operator / ARB → police","Police-reported incidents → also the Agency","Evaluation report afterwards"],"start_visual":"Security route lane with roles only (ARB caption, police, Agency logo); no arrows to the safety lanes.","beats":[{"at":"any person who observes a malicious act","show":"Role: anyone → operator/ARB"},{"at":"competent police services","show":"Police step"},{"at":"also reported to the Agency","show":"FANC logo"}],"equipment":["EQ-FANC-LOGO"],"clip":"B1.5-S12-P2"},{"cue":"B1.5-S12-P3","speaker":"Emilia","text":"The Agency's table has rubrics for this. Criterion 1bis.2 has two branches: acts, threats or attempts of theft, unauthorised possession or malicious use of radioactive substances subject to the decree's security measures; and the loss of such substances if it has been reported to the police under the decree. Direct contact immediately; INES evaluation yes. Read the condition carefully: the police-report condition sits on the loss branch, not on the theft-or-threat branch. A credible threat is notified immediately; nobody waits for a police file before responding to it. For these security rubrics the ARB may make the notification on the operator's behalf, and the security incident may well also be a safety event—both routes then run.","screen_text":["1bis.2 — theft/threat/attempt: immediately · loss: if reported to the police — immediately · INES yes","ARB may notify for security rubrics; both routes may run"],"start_visual":"Criterion extract row 1bis.2 with its two branches.","beats":[{"at":"Criterion 1bis.2 has two branches","show":"Row with two branches"},{"at":"both routes then run","show":"Safety and security lanes shown in parallel"}],"documents":["DOC-CRITERION-EXTRACT"],"clip":"B1.5-S12-P3"}],"sequence":{"cues_before_interaction":["B1.5-S12-P1","B1.5-S12-P2","B1.5-S12-P3"],"interaction_after_cue":null,"interaction_id":null,"post_interaction_cues":[]}},{"id":"S13","title":"From the first account to the final report, and back to work","paragraphs":[{"cue":"B1.5-S13-P1","speaker":"Emilia","text":"Back in our bunker, a few weeks on. The expert has studied the circumstances and assessed Tom's dose, and the interlock fault has been found. The work is not finished when the notification has gone. The regulation requires a final report within two calendar months of the event or its discovery, or another period the Agency sets, to the same address. Where the first notification said 'suspected', this one says 'established': the causes, the doses, a detailed description. And it adds what the first could not contain—the preventive measures decided to correct every shortcoming and prevent a repeat, the lessons learned and the action plan, and, where it applies, the approval of the recognised expert and of the class seven safety adviser. The full list is in the reference reader.","screen_text":["Initial notification (48 h) → investigation → final report (two calendar months)"],"start_visual":"Timeline: initial notification → investigation → final report; DOC-FINAL-REPORT structure fields in turn.","beats":[{"at":"a final report within two calendar months","show":"Final report marker"},{"at":"'established'","show":"Fields: established causes, doses"},{"at":"the preventive measures","show":"Fields: measures, lessons, action plan"}],"documents":["DOC-FINAL-REPORT"],"clip":"B1.5-S13-P1"},{"cue":"B1.5-S13-P2","speaker":"Emilia","text":"That is not the initial form sent again with a later date. 'Tom will be more careful' is not a cause analysis of a failed interlock. And an acknowledgement from the Agency does not put the bunker back in service. Return to use follows the correction of the deficiency and the checks our procedure and the expert require—the same logic you met with the failed interlock test in the licensing lesson. One more route, specific to our trade: when radiographers stop a worksite because safe working is not possible and the situation cannot be resolved, our company contacts the Agency immediately under the industrial radiography decree. That is a different trigger from the event table, and it lives in the same procedure.","screen_text":["Return to use: a separate conditional decision after correction and the required checks","Stopped worksite that cannot be resolved → company contacts the Agency immediately"],"start_visual":"Resumption shown as a separate conditional gate beside the timeline (not a progress arrow); HELD state until the gate; the KB IR route as its own thin lane.","beats":[{"at":"does not put the bunker back in service","show":"Conditional gate, closed"},{"at":"Return to use follows","show":"Gate conditions listed: correction · checks under procedure and expert"},{"at":"One more route, specific to our trade","show":"Thin lane: company → Agency (KB IR)"}],"clip":"B1.5-S13-P2"}],"sequence":{"cues_before_interaction":["B1.5-S13-P1","B1.5-S13-P2"],"interaction_after_cue":null,"interaction_id":null,"post_interaction_cues":[]}},{"id":"S14","title":"Correct the draft before it is handed over","paragraphs":[{"cue":"B1.5-S14-P1","speaker":"Emilia","text":"Let us hand the case to a colleague who has just arrived. They need more than 'it's been dealt with'. Go back to Tuesday afternoon, before the expert's findings—that is the moment a handover is hardest and most useful. A draft handover record is on the desk. Most of its lines are genuine facts from the day: the interlock did not cut the exposure at 10:12; the exposure was stopped manually and the bunker is out of use; Tom is available and the exposure facts are preserved; the expert was briefed and confirmed she had the facts; direct contact with the Agency succeeded at 10:40 and the written notification went this afternoon. One line is not a fact.","screen_text":["Draft handover — Tuesday afternoon"],"start_visual":"DOC-EVENT-RECORD draft page with its lines readable; the dose line reads 'Dose: zero'.","beats":[{"at":"A draft handover record is on the desk","show":"Draft page"},{"at":"One line is not a fact","show":"Lines selectable"}],"documents":["DOC-EVENT-RECORD"],"clip":"B1.5-S14-P1"},{"cue":"B1.5-S14-P2","speaker":"Emilia","text":"Here it is, read once: 'Bunker one is out of use after the door interlock failed to cut an exposure at 10:12; exposure stopped manually. Tom, a workshop fitter with no dosimeter, was in the doorway for seconds; his dose is not yet established and is being assessed by the expert; the physician has been informed. Expert informed and briefed. Direct contact with the Agency succeeded at 10:40 and the written notification went this afternoon. Open: cause, Tom's dose, and the checks before return to use.'","screen_text":["Observation · protective and work status · actual reporting status · open items"],"start_visual":"Corrected record page; the four headings pulse as read. Plays after the activity.","beats":[{"at":"Open: cause","show":"Open-items line"}],"documents":["DOC-EVENT-RECORD"],"clip":"B1.5-S14-P2"}],"interaction":{"id":"B1.5-R01","type":"single_choice","prompt_spoken_once":"Which entry needs correcting before this handover is sent?","behaviour":"The prompt is spoken automatically exactly once when the activity opens; the narration lead-in never reads it. Manual 'Hear the question' replay. Each option has its own spoken and written feedback (evidence, then next step). Retry without replaying narration; keyboard equivalents (labelled radio controls, Check, Try again, Continue); no auto-advance; no colour-only cues; no timer. Feedback never invents a dose, cause, approval or successful contact.","situation_visible_text":"Draft lines: interlock did not cut the exposure at 10:12 · exposure stopped manually, bunker out of use · Tom available, facts preserved · expert briefed and confirmed · direct contact with the Agency succeeded at 10:40 · written notification sent · Dose: zero","options":[{"id":"dose_zero","text":"'Dose: zero' — replace with 'Dose: not yet established — under assessment by the expert'.","correct":true,"feedback":{"spoken":"Yes. Nobody has established Tom's dose; the expert's assessment is under way, and 'feels nothing unusual' says nothing about dose. The corrected line states the unknown as an unknown. Every other line records something that actually happened. Here is the handover read once in full.","screen":"Unknown stated as unknown; the rest are recorded facts."},"clip":"B1.5-R01-dose_zero"},{"id":"contact","text":"'Direct contact with the Agency succeeded at 10:40' — replace with 'Agency notified by voicemail'.","correct":false,"feedback":{"spoken":"In this case the direct contact did succeed, at 10:40, after the earlier voicemail attempt—so the line is a recorded fact and stays. The entry that claims something nobody has established is the dose line: 'zero' is a number the case does not have. Correct that one.","screen":"Contact succeeded on record; the dose line is the unsupported entry."},"clip":"B1.5-R01-contact"},{"id":"out_of_use","text":"'Bunker out of use' — replace with 'Bunker cleared for use after the stop'.","correct":false,"feedback":{"spoken":"The bunker is out of use and must stay so until the deficiency is corrected and the required checks are done; nothing on Tuesday afternoon cleared it. That line is accurate. The entry that invents a result is 'Dose: zero'—that is the one to correct.","screen":"Out of use is accurate; 'Dose: zero' is the invented entry."},"clip":"B1.5-R01-out_of_use"}],"replaces":"B1.5 S14 R01 (free-text handover rehearsal) — replaced one-for-one as a single correction task","placement":"Draft page stays visible; on the correct answer the dose line updates and Emilia reads the concise handover once (S14-P2).","clip":"B1.5-R01-prompt"},"sequence":{"cues_before_interaction":["B1.5-S14-P1"],"interaction_after_cue":"B1.5-S14-P1","interaction_id":"B1.5-R01","post_interaction_cues":[{"cue":"B1.5-S14-P2","condition":"only after the correct entry has been selected (the corrected dose line is shown first)"}],"rule":"Play cues_before_interaction in order; open the interaction immediately after interaction_after_cue (it speaks its prompt once); post_interaction_cues play only when their condition is met; nothing in post_interaction_cues is spoken before the interaction."}},{"id":"S15","title":"A clear response does not need to know everything","paragraphs":[{"cue":"B1.5-S15-P1","speaker":"Emilia","text":"When something is wrong, a clear response begins with an accurate observation. The protective action in your instructions comes first; the head of service and the expert hear immediately; the statutory notification follows its own criteria, with successful direct contact meaning a real conversation with the duty officer and the written notification due within 48 hours whatever the table says about contact or INES. The initial notification says what is known; the investigation and the final report, within two calendar months, develop the full account. Security events have their own route through the operator or the ARB, the police and the Agency.","screen_text":["Protect · inform · notify (direct contact + 48 h) · final report · security route"],"start_visual":"Back at the control post with the record visible; the three lanes recap briefly.","beats":[{"at":"The protective action in your instructions","show":"Lane 1"},{"at":"the statutory notification","show":"Lane 3"},{"at":"Security events have their own route","show":"Security lane"}],"clip":"B1.5-S15-P1"},{"cue":"B1.5-S15-P2","speaker":"Emilia","text":"Keep the three lanes with you, and keep the habit of saying 'not yet established' when that is the truth. In the final lesson of this module we bring the whole Belgian picture together around practical decisions: who is responsible, what evidence is needed, and what to do when the information in front of you is incomplete—with a visiting radiographer, a changed task and a client who would like you to hurry.","screen_text":["Next: one ordinary Thursday"],"start_visual":"Bridge: the job planner page DOC-PLANNER with Thursday marked.","beats":[{"at":"In the final lesson","show":"Planner thumbnail"}],"documents":["DOC-PLANNER"],"clip":"B1.5-S15-P2"}],"sequence":{"cues_before_interaction":["B1.5-S15-P1","B1.5-S15-P2"],"interaction_after_cue":null,"interaction_id":null,"post_interaction_cues":[]}}]},{"id":"B1.6","title":"One Thursday: the Belgian framework in practice","scenes":[{"id":"S01","title":"Welcome to the last lesson of this module","paragraphs":[{"cue":"B1.6-S01-P1","speaker":"Emilia","text":"Welcome back. Over five lessons we have looked at Belgian radiation protection from five directions: why a practice must be justified, optimised and kept within limits; who does what in and around our company; what the licence, the bunker and the acceptance prove; how protection follows a worker across company lines; and what happens when something is wrong. Today nothing new arrives from the regulation. Instead I want to spend one ordinary Thursday with you, and watch the five lessons turn into decisions.","screen_text":["Thursday — today"],"start_visual":"DOC-PLANNER week view with Thursday clearly marked as the current day; Daniel, Clara and the vessel image as familiar elements, no re-introduction.","beats":[{"at":"five lessons","show":"Planner week view"},{"at":"one ordinary Thursday","show":"Thursday marked current"}],"documents":["DOC-PLANNER"],"characters":["Daniel","Clara"],"clip":"B1.6-S01-P1"},{"cue":"B1.6-S01-P2","speaker":"Emilia","text":"This is practice, not an examination. The day has a job prepared earlier in the week, a client in a hurry to add to it, a visiting radiographer, a worksite that does not behave, and a planner who wants to make next time easier. In each case I will ask you a short question with a direct answer. A good answer explains the reason for a decision; it does not reach for the most reassuring document, and it does not ask for everything to be checked again.","screen_text":["08:10 · 08:40 · 10:30 · 11:40 · 12:00 · 15:00"],"start_visual":"Thursday's time marks appear on the planner.","beats":[{"at":"a job prepared earlier in the week","show":"Tuesday/Wednesday entries"},{"at":"a client in a hurry","show":"08:10 mark"}],"clip":"B1.6-S01-P2"}],"sequence":{"cues_before_interaction":["B1.6-S01-P1","B1.6-S01-P2"],"interaction_after_cue":null,"interaction_id":null,"post_interaction_cues":[]}},{"id":"S02","title":"08:10 — a prepared job, and a client in a hurry","paragraphs":[{"cue":"B1.6-S02-P1","speaker":"Emilia","text":"Today's job was not born this morning. On Tuesday Bram, the client's maintenance manager, asked us to radiograph two welds on a large pressure vessel that had failed its visual inspection. The same afternoon we received, in writing, what the decree requires from him: his justification of the technique—why radiography and not another method—and his justification of the location, together with the information from his own risk analysis and the job details, numbers and dimensions included. The decree wants that information at least twenty-four hours before the work, so that we have time to prepare the worksite; we had it on Tuesday for a job on Thursday. As head of service I checked that the choice of technique had been justified by someone competent in the different non-destructive methods, and on Wednesday we completed our own risk analysis.","screen_text":["Tuesday: request + written justifications + job details","Wednesday: our risk analysis","≥ 24 h before the work"],"start_visual":"Planner: Tuesday entry opens the original request DOC-REQ and the two justifications (thumbnails); Wednesday entry: our risk analysis line; current day Thursday.","beats":[{"at":"On Tuesday Bram","show":"Tuesday entry: DOC-REQ thumbnail"},{"at":"his justification of the technique","show":"DOC-TECH-JUST thumbnail"},{"at":"his justification of the location","show":"DOC-LOC-JUST thumbnail"},{"at":"at least twenty-four hours before","show":"24 h marker between Tuesday and Thursday"},{"at":"on Wednesday we completed","show":"Wednesday entry"}],"documents":["DOC-PLANNER","DOC-REQ","DOC-TECH-JUST","DOC-LOC-JUST"],"characters":["Bram"],"clip":"B1.6-S02-P1"},{"cue":"B1.6-S02-P2","speaker":"Emilia","text":"Nothing about the location was decided by habit either. The vessel is installed in the hall and cannot be moved, so the rule for small movable workpieces—always in a bunker—does not apply to it. For a larger or heavier workpiece the decree still prefers a bunker, then an irradiation infrastructure on the client's site, and only when neither is reasonably feasible, another place. Bram's written assessment answers that for both options, with reasons: dismantling and transport to a bunker for two repair welds assessed and judged unreasonable; no irradiation infrastructure present, and arranging fixed shielding around the vessel for these welds assessed—access, crane traffic, duration—and judged not reasonably feasible. Only on that documented assessment, plus a risk analysis by the client and by us, does the hall become the place, and both analyses say so in writing. Notice what the reasoning rests on: the assessed constraints of this vessel and this site, not on the fact that the vessel is fixed or that the client happens not to own an irradiation infrastructure. Had radiography in a shielded structure been reasonably feasible, the hall would not have been the answer.","screen_text":["Location: both options assessed with reasons → neither reasonably feasible → the hall, after both risk analyses"],"start_visual":"DOC-LOC-JUST overview → close-up on the two assessment blocks → conclusion → back to the planner.","beats":[{"at":"Bram's written assessment","show":"DOC-LOC-JUST overview"},{"at":"dismantling and transport","show":"Bunker block"},{"at":"arranging fixed shielding","show":"Infrastructure block"},{"at":"Only on that documented assessment","show":"Conclusion line"}],"documents":["DOC-LOC-JUST"],"clip":"B1.6-S02-P2"},{"cue":"B1.6-S02-P3","speaker":"Emilia","text":"Then, at ten past eight on Thursday, the manager calls again. The visual inspection of the next vessel has thrown up a doubtful nozzle weld. 'You're here anyway—can you add it today?' That is where the pressure arrives, and the three questions from the opening lesson still have to be asked. Is this use of radiation justified? For the two welds, yes, in writing. For the nozzle weld, nothing is in writing yet. How will exposure be kept as low as reasonably achievable? Our plan covers two welds in known positions; a third weld on another vessel changes geometry, perimeter and time. Are the limits respected? A forecast below a limit is the third question, not the first two. And the decree is specific about timing: the client's written information comes at least twenty-four hours before, and neither the client nor the site employer may impose time constraints that prevent us from working safely. So my answer to the manager is not a refusal of the work; it is a refusal of the timing. Send the written justification and the job details for the nozzle weld today, and we plan it for the next slot with its own risk analysis.","screen_text":["08:10 — new request: nozzle weld on the next vessel","Prepared scope: two welds on V-2"],"start_visual":"08:10 on the planner: Bram's phone request appears as a second request slip (DOC-REQ 'nozzle weld, next vessel') beside the original — visibly outside the prepared scope; the three question labels from B1.1 return.","beats":[{"at":"the manager calls again","show":"Second request slip appears beside the original"},{"at":"Is this use of radiation justified","show":"Label 1"},{"at":"How will exposure be kept","show":"Label 2"},{"at":"Are the limits respected","show":"Label 3"},{"at":"a refusal of the timing","show":"Slip marked 'next slot — written justification and job details needed'"}],"documents":["DOC-REQ"],"characters":["Bram"],"clip":"B1.6-S02-P3"}],"interaction":{"id":"B1.6-I01","type":"single_choice","prompt_spoken_once":"At 08:10 the client asks us to add a third weld, on another vessel, to today's prepared job. What applies?","behaviour":"The prompt is spoken automatically exactly once when the activity opens; the narration lead-in never reads it. Manual 'Hear the question' replay. Each option has its own spoken and written feedback (evidence, then next step). Retry without replaying narration; keyboard equivalents (labelled radio controls, Check, Try again, Continue); no auto-advance; no colour-only cues; no timer. Feedback never invents a dose, cause, approval or successful contact.","situation_visible_text":"Original request: two welds on V-2, justified and prepared since Tuesday. New request: nozzle weld on the next vessel, today.","options":[{"id":"timing","text":"His written justification and job details must reach us at least 24 hours before; the weld goes to a later slot.","correct":true,"feedback":{"spoken":"Yes. The decree requires the client's correct written information at least twenty-four hours in advance so that the worksite can be prepared, and the location justification is given per type of assignment with risk-analysis information for our own analysis. Today's two welds were prepared that way; the nozzle weld is a new job, and urgency does not shorten the rule—the client may not impose time constraints that prevent safe work. Bram sends the papers today; we plan the next slot.","screen":"New job → written justification + job details ≥ 24 h before → next slot."},"clip":"B1.6-I01-timing"},{"id":"covered","text":"Add it today: the hall's justification and our risk analysis for the two welds cover any weld there.","correct":false,"feedback":{"spoken":"The justification and the two risk analyses are real and they do cover today's work—two welds in known positions on one vessel. A weld on another vessel changes the geometry, the perimeter and the exposure time, and the decree's twenty-four-hour written information has not been given for it. 'Same hall' is not 'same assignment'.","screen":"Prepared for two welds on V-2; a different vessel is a different assignment."},"clip":"B1.6-I01-covered"},{"id":"dose","text":"Add it today if our dose estimate for the hall stays below the limit.","correct":false,"feedback":{"spoken":"A forecast below a limit answers the third question, and it is worth having. It does not justify the new weld, it does not replace the client's written information for preparing the worksite, and it does not show how exposure for that weld will be kept as low as reasonably achievable. You met this in the opening lesson: a reassuring number cannot stand in for the other two questions.","screen":"Forecast = dose limitation only."},"clip":"B1.6-I01-dose"}],"placement":"Both request slips stay visible on the planner.","clip":"B1.6-I01-prompt"},"sequence":{"cues_before_interaction":["B1.6-S02-P1","B1.6-S02-P2","B1.6-S02-P3"],"interaction_after_cue":"B1.6-S02-P3","interaction_id":"B1.6-I01","post_interaction_cues":[],"rule":"Play cues_before_interaction in order; open the interaction immediately after interaction_after_cue (it speaks its prompt once); post_interaction_cues play only when their condition is met; nothing in post_interaction_cues is spoken before the interaction."}},{"id":"S03","title":"08:40 — who goes, and who is the agent","paragraphs":[{"cue":"B1.6-S03-P1","speaker":"Emilia","text":"Planning for the two welds was finished on Wednesday, but one line is open again this morning because a colleague has called in sick: who goes with Daniel? Radiography outside a bunker is done by at least two radiographers, so the team is two people. Available are Daniel, and Clara, the subcontracted radiographer you met two lessons ago, who has been working in our bunker. Clara has more worksite experience than Daniel. The planner suggests sending both and 'letting Clara be the agent, since she has done more of this'.","screen_text":["Team: two radiographers outside a bunker","Available: Daniel (our staff, trained) · Clara (external, instructed on our bunker)"],"start_visual":"Dispatch planning DOC-PLANNING: team lines with correct employment and instruction status captions: Daniel — our staff, agent-trained; Clara — external worker, instruction: bunker X-ray set. Designated-agent line empty.","beats":[{"at":"who goes with Daniel","show":"Planning sheet"},{"at":"Available are Daniel, and Clara","show":"Two team lines with status captions"},{"at":"letting Clara be the agent","show":"Planner's suggestion as a speech line"}],"documents":["DOC-PLANNING"],"characters":["Daniel","Clara"],"clip":"B1.6-S03-P1"},{"cue":"B1.6-S03-P2","speaker":"Emilia","text":"Two different rules answer that. First, the decree says the company designates on every worksite a radiation protection agent from the industrial radiographers present who belong to its staff and have followed the agent training. Clara is an external worker here; she is not on our staff, however experienced—her own employer may well designate her on its jobs, but not we on ours. Second, Clara's specific instruction with us covered the bunker and the bunker X-ray set; the client's hall with the portable X-ray set is a different place, different equipment and a different task, so her workstation training does not stretch to it without the instruction the change requires—and the operational protection of an external worker on a job we run is a question I settle with her employer under our agreement, not by assuming.","screen_text":["Rule 1: agent from the company's own trained radiographers present","Rule 2: instruction covers the task it was given for"],"start_visual":"Two criteria labels; Clara's instruction record thumbnail (bunker scope) at rule 2.","beats":[{"at":"Two different rules answer that","show":"Criteria labels"},{"at":"Clara is an external worker here","show":"Clara's status caption pulses"},{"at":"Clara's specific instruction with us covered the bunker","show":"DOC-INSTRUCTION-RECORD thumbnail"}],"documents":["DOC-INSTRUCTION-RECORD"],"clip":"B1.6-S03-P2"},{"cue":"B1.6-S03-P3","speaker":"Emilia","text":"So the decision is: Daniel is designated as the agent for the worksite, recorded in the planning. Clara comes as the second radiographer only if her employer and I arrange the instruction for this task first—which, since the job is prepared and the procedure is written, we can do this morning; otherwise she stays on the bunker job she was prepared for and a colleague from another team goes. Nobody's experience is being disrespected. Experience makes a person eligible for things; it does not designate them.","screen_text":["Designated agent: Daniel — recorded","Clara: second radiographer only after the instruction for this task is arranged"],"start_visual":"Designated-agent line fills 'Daniel'; Clara's line gets 'instruction for this task: to arrange with her employer'.","beats":[{"at":"Daniel is designated as the agent","show":"Agent line filled"},{"at":"Clara comes as the second radiographer only if","show":"Clara line annotated"}],"clip":"B1.6-S03-P3"}],"interaction":{"id":"B1.6-I02","type":"single_choice","prompt_spoken_once":"Two radiographers are available for the client's worksite. Who can be the designated radiation protection agent there?","behaviour":"The prompt is spoken automatically exactly once when the activity opens; the narration lead-in never reads it. Manual 'Hear the question' replay. Each option has its own spoken and written feedback (evidence, then next step). Retry without replaying narration; keyboard equivalents (labelled radio controls, Check, Try again, Continue); no auto-advance; no colour-only cues; no timer. Feedback never invents a dose, cause, approval or successful contact.","situation_visible_text":"Daniel — our staff, agent-trained, present. Clara — external worker, instructed on our bunker only. Emilia — head of service, not on site.","options":[{"id":"daniel","text":"Daniel — a trained radiographer on our own staff who will be present on the site.","correct":true,"feedback":{"spoken":"Right. The company designates the worksite agent from the industrial radiographers present who belong to its staff and have followed the agent training. Daniel meets all three conditions, and the designation is recorded on the planning sheet in front of you.","screen":"Own staff · trained · present → designated and recorded."},"clip":"B1.6-I02-daniel"},{"id":"clara","text":"Clara — she has far more worksite experience than anyone else available.","correct":false,"feedback":{"spoken":"Experience is real and it matters for how well the job goes. The decree still requires the worksite agent to be one of the company's own radiographers. Clara is an external worker here, employed by another company, so she cannot be our designated agent—her own employer may designate her on its jobs. And her instruction with us covered the bunker, not this task.","screen":"External worker → not our designated agent; experience ≠ designation."},"clip":"B1.6-I02-clara"},{"id":"emilia","text":"Emilia — as head of the physical control service she is the agent on every worksite.","correct":false,"feedback":{"spoken":"Heading the service is a real function and it is mine: I make sure the designation has been made and recorded. It is a different function from being the agent on a worksite. The agent is designated among the radiographers who are actually present; coordinating the service is not the same as holding that designation.","screen":"Head of service coordinates; the agent is designated among those present."},"clip":"B1.6-I02-emilia"}],"placement":"Planning sheet stays visible.","clip":"B1.6-I02-prompt"},"sequence":{"cues_before_interaction":["B1.6-S03-P1","B1.6-S03-P2","B1.6-S03-P3"],"interaction_after_cue":"B1.6-S03-P3","interaction_id":"B1.6-I02","post_interaction_cues":[],"rule":"Play cues_before_interaction in order; open the interaction immediately after interaction_after_cue (it speaks its prompt once); post_interaction_cues play only when their condition is met; nothing in post_interaction_cues is spoken before the interaction."}},{"id":"S04","title":"10:30 — before the first exposure","paragraphs":[{"cue":"B1.6-S04-P1","speaker":"Emilia","text":"On site, Daniel and Clara set up as the approved procedure says: the perimeter marked out so it can be watched for the whole job, the warning signs placed, the client's contact person named and present, each radiographer's electronic dosimeter and the survey meter function-tested, and a last-minute risk analysis before the first exposure. The decree asks for exactly these preparations, and each is also one of the agent's frequent and systematic checks—that the rules and procedures are followed, that the protective means and instruments are available and working—carried out on the basis of a procedure the recognised expert approved. The record Daniel keeps is his observation on that day; it is not a new approval, and it does not need to be.","screen_text":["Perimeter marked and watchable · signs · contact person present · dosimeter and survey meter function-tested · last-minute risk analysis"],"start_visual":"Client's hall with the supplied equipment imagery: portable X-ray generator on its stand, control unit, perimeter kit with trefoil signs; Daniel with handheld, EPD and TLD; Clara at the boundary; Bram present; a concise approved check-record view (DOC-CHECK-SHEET lines ticked as the narration names them — only what the script establishes).","beats":[{"at":"the perimeter marked out","show":"EQ-PERIMETER-KIT and the perimeter line on DOC-SITE-PLAN"},{"at":"the warning signs placed","show":"Trefoil signs"},{"at":"the client's contact person named and present","show":"Bram marker"},{"at":"electronic dosimeter and the survey meter function-tested","show":"Check-record lines: EPD · survey meter — function-tested"},{"at":"a last-minute risk analysis","show":"Check-record line: LMRA"}],"documents":["DOC-CHECK-SHEET","DOC-SITE-PLAN"],"equipment":["EQ-XRAY-GENERATOR","EQ-XRAY-CONTROL-UNIT","EQ-PERIMETER-KIT","EQ-HANDHELD-SURVEY","EQ-EPD-LEFT-CHEST","EQ-TLD-RIGHT-UPPER-CHEST"],"characters":["Daniel","Clara","Bram"],"clip":"B1.6-S04-P1"},{"cue":"B1.6-S04-P2","speaker":"Emilia","text":"Notice that nothing today has required anyone to approve anything new. The licence, the procedure, the designation, the client's justification and the two risk analyses were all in place before the first exposure. That is what a quiet morning looks like in this trade: the evidence was there before the pressure arrived.","screen_text":["Already in place: licence · procedure · designation · justifications · two risk analyses"],"start_visual":"The five documents as thumbnails in a row, each already 'in place'.","beats":[{"at":"nothing today has required anyone to approve anything new","show":"Thumbnail row"},{"at":"the evidence was there before the pressure arrived","show":"Row settles"}],"clip":"B1.6-S04-P2"}],"sequence":{"cues_before_interaction":["B1.6-S04-P1","B1.6-S04-P2"],"interaction_after_cue":null,"interaction_id":null,"post_interaction_cues":[]}},{"id":"S05","title":"11:40 — the worksite does not behave","paragraphs":[{"cue":"B1.6-S05-P1","speaker":"Emilia","text":"Then the morning stops being quiet. Twice in ten minutes, plant workers walk across the perimeter line to reach a store behind the hall, ignoring the signs and Clara at the boundary. The client's contact person has gone to take a call. Daniel has not started the exposure. He now has a decision that does not need a meeting.","screen_text":["Twice in ten minutes: plant workers cross the perimeter · contact person away · exposure NOT started"],"start_visual":"Familiar site drawing DOC-SITE-PLAN: two crossing marks on the perimeter line toward the store; Bram marker absent; the generator shown not emitting; HELD badge: 'Exposure held'. Reported workers remain outside any active emission; no accident spectacle.","beats":[{"at":"plant workers walk across the perimeter line","show":"Crossing marks on the drawing"},{"at":"The client's contact person has gone","show":"Bram marker greyed"},{"at":"Daniel has not started the exposure","show":"HELD badge"}],"documents":["DOC-SITE-PLAN"],"characters":["Daniel","Clara"],"clip":"B1.6-S05-P1"},{"cue":"B1.6-S05-P2","speaker":"Emilia","text":"The decree gives it to him in one sentence: industrial radiographers stop the radiography if it cannot be carried out safely, and they report that immediately, with the reason, to their hierarchical superior, to the head of the physical control service and to the client's contact person. That duty is Daniel's as a radiographer; as the designated agent he also informs me and, through our service, the expert of the abnormal situation. The decree also places a duty on the site: the responsible employer of the site makes sure that his own staff and third parties present respect the safety measures for the radiography, and the client's contact person is to be reachable throughout. And there is a further step that belongs to the company, not to Daniel: if radiographers stop or do not start a worksite and the situation cannot be resolved, the company contacts the Agency immediately.","screen_text":["Radiographers stop when unsafe → report with the reason to superior, head of service, client contact","Site employer ensures his staff and third parties respect the measures","Unresolved → the company contacts the Agency"],"start_visual":"Three short labels in turn; Daniel with phone at the drawing.","beats":[{"at":"The decree gives it to him in one sentence","show":"Label 1"},{"at":"the responsible employer of the site","show":"Label 2"},{"at":"the company contacts the Agency immediately","show":"Label 3 with FANC logo"}],"equipment":["EQ-FANC-LOGO"],"characters":["Daniel"],"clip":"B1.6-S05-P2"}],"interaction":{"id":"B1.6-I03","type":"single_choice","prompt_spoken_once":"Plant workers keep crossing the perimeter and the client's contact person has left. The exposure has not started. What does Daniel do?","behaviour":"The prompt is spoken automatically exactly once when the activity opens; the narration lead-in never reads it. Manual 'Hear the question' replay. Each option has its own spoken and written feedback (evidence, then next step). Retry without replaying narration; keyboard equivalents (labelled radio controls, Check, Try again, Continue); no auto-advance; no colour-only cues; no timer. Feedback never invents a dose, cause, approval or successful contact.","situation_visible_text":"Drawing: two crossings on the perimeter; contact person away; exposure held.","options":[{"id":"hold_report","text":"Hold the radiography and report at once, with the reason, to Luc, to Emilia and to Bram.","correct":true,"feedback":{"spoken":"Yes. The decree says radiographers stop the radiography when it cannot be done safely and report immediately, with the reason, to those three people—his supervisor, the head of service and the client's contact person; as agent he also informs the service, which informs the expert. The job resumes only after the client has restored control of the route and our team has verified, under the procedure, that the perimeter can be held and the agreed safety measures are in place. If it cannot be resolved, the company contacts the Agency immediately.","screen":"Hold; report with the reason to Luc, Emilia, Bram; resume only after verification."},"clip":"B1.6-I03-hold_report"},{"id":"shout","text":"Start the exposure with Clara shouting warnings — the dose rate at the line is low anyway.","correct":false,"feedback":{"spoken":"A low reading at the line is what the perimeter is for, and Clara at the boundary is doing her job. It says nothing about someone walking inside the line during an exposure. Safe working is not possible while people cross the perimeter, and the decree's answer to that is to stop and report, not to compensate with shouting.","screen":"Low at the line ≠ safe inside it; stop and report."},"clip":"B1.6-I03-shout"},{"id":"shrink","text":"Move the barriers closer to the vessel so there is less perimeter line to watch and fewer crossings.","correct":false,"feedback":{"spoken":"Reducing crossings is the right aim, and the client will do it by closing the route. The perimeter itself is the controlled area defined by the approved procedure and the risk analysis for this exposure; it is not a convenience that shrinks when supervision gets harder. Changing the protection arrangement on the spot is exactly the kind of improvisation the agent's instructions do not allow.","screen":"The perimeter is set by the procedure and risk analysis; the route is the client's to close."},"clip":"B1.6-I03-shrink"}],"placement":"Drawing with the HELD badge stays visible.","clip":"B1.6-I03-prompt"},"sequence":{"cues_before_interaction":["B1.6-S05-P1","B1.6-S05-P2"],"interaction_after_cue":"B1.6-S05-P2","interaction_id":"B1.6-I03","post_interaction_cues":[],"rule":"Play cues_before_interaction in order; open the interaction immediately after interaction_after_cue (it speaks its prompt once); post_interaction_cues play only when their condition is met; nothing in post_interaction_cues is spoken before the interaction."},"status_badges":[{"kind":"held","label":"Exposure held","explanation":"Safe working is not possible while people cross the perimeter and the contact person is away; the exposure has not started and does not start until the route is controlled and the team has verified the perimeter under the procedure."}]},{"id":"S06","title":"12:00 — the handover, and what it is not","paragraphs":[{"cue":"B1.6-S06-P1","speaker":"Emilia","text":"Daniel's call to me is the handover you have practised twice: 'Two plant workers crossed the perimeter twice; the contact person was away; I have not started the exposure and the radiography is on hold; I've told my supervisor, and the client's contact person has just called back; I don't know yet whether the plant can keep the route closed.' Observed, done, contacted, unknown. No exposure has occurred, nobody has been in a beam, and nothing has failed. My side of the call: I note the stop and its reason, I make sure the expert hears through our service, and I tell Daniel what has to be true before anyone resumes.","screen_text":["Observed · Done · Contacted · Unknown"],"start_visual":"Daniel's phone handover to Emilia; DOC-EVENT-RECORD lines fill: observation (crossings), status (held, no exposure), contacted (Luc; Bram called back), unknown (can the route be kept closed?).","beats":[{"at":"Two plant workers crossed the perimeter twice","show":"Record: observation"},{"at":"the radiography is on hold","show":"Record: status HELD"},{"at":"I've told my supervisor","show":"Record: contacted — Luc; Bram"},{"at":"I don't know yet whether the plant can keep the route closed","show":"Record: unknown"}],"documents":["DOC-EVENT-RECORD"],"characters":["Daniel","Emilia"],"clip":"B1.6-S06-P1"},{"cue":"B1.6-S06-P2","speaker":"Emilia","text":"Keep the lanes apart here too. This is a stopped worksite with a reason—the decree's route. Whether it is also a significant event under the Agency's criteria is for the responsible assessment with the expert; Daniel does not classify it, and nobody writes 'Agency notified' because a phone call was made to me. By half past twelve the client's contact person has closed the route with a locked gate and posted someone at it. That is the client's part. Ours is not to take his word for it: Daniel and Clara check that the perimeter can now be watched along its whole length and that the safety measures from the risk analyses are in place, they repeat the last-minute risk analysis, and Daniel confirms to me that safe working is possible again. Only then does the radiography resume under the procedure. The stop, its reason and the verification go into our records—the decree wants the company's findings documented in the physical control system—and I note it for the expert's next visit.","screen_text":["Stopped worksite (decree route) ≠ 'Agency notified'","12:30 — route closed by the client · team verifies · LMRA repeated · resume under the procedure · recorded"],"start_visual":"Return to the worksite status rather than an exercise: drawing shows the gate closed with a person posted (client's action); then Daniel and Clara's verification; the HELD badge is released only at 'Only then does the radiography resume'; record line 'stop · reason · verification' added.","beats":[{"at":"nobody writes 'Agency notified'","show":"FACT badge: 'Emilia informed; Agency: not applicable unless unresolved'"},{"at":"closed the route with a locked gate","show":"Gate closed; posted person marker"},{"at":"Daniel and Clara check","show":"Verification markers along the perimeter"},{"at":"Only then does the radiography resume","show":"HELD badge released"},{"at":"go into our records","show":"Record line added"}],"documents":["DOC-SITE-PLAN","DOC-EVENT-RECORD"],"characters":["Daniel","Clara"],"clip":"B1.6-S06-P2"}],"sequence":{"cues_before_interaction":["B1.6-S06-P1","B1.6-S06-P2"],"interaction_after_cue":null,"interaction_id":null,"post_interaction_cues":[]},"status_badges":[{"kind":"fact","label":"Stopped worksite — reported","explanation":"Daniel reported the stop and its reason to Luc, Emilia and Bram; Emilia informs the expert through the service. Whether this is also a significant event is for the responsible assessment with the expert; no Agency notification is claimed."}]},{"id":"S07","title":"15:00 — the planner wants to make next time easier","paragraphs":[{"cue":"B1.6-S07-P1","speaker":"Emilia","text":"Back in the office, the planner has an idea born of a stressful morning: 'That hall is fine now—can we put it on a list of approved locations, so next time we skip the justification?' I understand the wish. But look at what the rule actually says. The client justifies the location in writing for each type of assignment. A vessel fixed in the hall today does not make the same hall a justified location for a casting next month. A movable casting that fits within one cubic metre and weighs under 500 kilograms is radiographed in a bunker—the mandatory condition from the licence lesson—and for anything else the feasibility reasoning starts again. And it is the client—not us, not our expert—who gives that justification. Our part is to assess it, do our risk analysis and refuse if it does not hold.","screen_text":["Location justification: by the client, in writing, per type of assignment","Movable, within 1 m³ and under 500 kg → always in a bunker; otherwise the assessment starts again"],"start_visual":"Office: the job-specific dossier (DOC-LOC-JUST for V-2) beside the next workpiece — a small casting image; the planner's suggestion as a speech line.","beats":[{"at":"put it on a list of approved locations","show":"Speech line"},{"at":"A vessel fixed in the hall today","show":"Dossier thumbnail"},{"at":"A movable casting","show":"Casting image beside it"}],"documents":["DOC-LOC-JUST"],"clip":"B1.6-S07-P1"},{"cue":"B1.6-S07-P2","speaker":"Emilia","text":"What we can do is keep today's dossier so that the next justification and risk analysis are quicker to review—the hall's layout, the routes, the gate that solved our problem. That is good practice. It is not a standing approval, and there is no document in our licence folder that could become one.","screen_text":["Keep today's dossier for a quicker review — not a standing approval"],"start_visual":"Dossier filed; no 'approved locations' list exists in the licence folder (folder shown without such a document).","beats":[{"at":"keep today's dossier","show":"Dossier filed"},{"at":"no document in our licence folder","show":"Licence folder tabs shown"}],"clip":"B1.6-S07-P2"}],"interaction":{"id":"B1.6-I04","type":"single_choice","prompt_spoken_once":"The planner wants the client's hall on a list of approved locations so future jobs there skip the justification. What applies?","behaviour":"The prompt is spoken automatically exactly once when the activity opens; the narration lead-in never reads it. Manual 'Hear the question' replay. Each option has its own spoken and written feedback (evidence, then next step). Retry without replaying narration; keyboard equivalents (labelled radio controls, Check, Try again, Continue); no auto-advance; no colour-only cues; no timer. Feedback never invents a dose, cause, approval or successful contact.","situation_visible_text":"Today's dossier: location justification for V-2 (two options assessed). Next workpiece: a movable casting.","options":[{"id":"each_type","text":"The client justifies the location in writing for each type of assignment; today's job does not pre-approve the hall.","correct":true,"feedback":{"spoken":"Right. The decree places the location justification on the client, in writing, for each type of assignment, with his risk-analysis information to us. Keeping today's dossier makes the next review faster; it does not replace it, and a different workpiece—a movable casting belongs in a bunker—is a different question.","screen":"Per type of assignment; dossier helps, does not replace."},"clip":"B1.6-I04-each_type"},{"id":"standing","text":"Once radiography has been done there, the hall counts as a justified location for future work.","correct":false,"feedback":{"spoken":"Today's dossier is genuinely useful next time—the layout, the routes, the gate. Justification, though, attaches to a type of assignment, not to a room. The reasoning that, for this fixed vessel, neither a bunker nor an irradiation infrastructure was reasonably feasible says nothing about the next workpiece, and the decree requires the written justification for each type of assignment.","screen":"Justification attaches to the assignment type, not the room."},"clip":"B1.6-I04-standing"},{"id":"expert","text":"Our recognised expert can approve the hall once, and that approval then covers future jobs.","correct":false,"feedback":{"spoken":"The recognised expert does approve real things: procedures, risk analyses and acceptances. She does not justify a client's location. That duty sits with the client, in writing, for each type of assignment. Moving it to our expert would misplace the responsibility and still not make it standing.","screen":"Expert approves procedures and acceptances; the client justifies the location."},"clip":"B1.6-I04-expert"}],"placement":"Dossier and casting stay visible.","clip":"B1.6-I04-prompt"},"sequence":{"cues_before_interaction":["B1.6-S07-P1","B1.6-S07-P2"],"interaction_after_cue":"B1.6-S07-P2","interaction_id":"B1.6-I04","post_interaction_cues":[],"rule":"Play cues_before_interaction in order; open the interaction immediately after interaction_after_cue (it speaks its prompt once); post_interaction_cues play only when their condition is met; nothing in post_interaction_cues is spoken before the interaction."}},{"id":"S08","title":"The same reasoning with a sealed source","paragraphs":[{"cue":"B1.6-S08-P1","speaker":"Emilia","text":"Today's job used a portable X-ray set. Most of the decisions would have been the same with a gamma projector: the client's justifications, the twenty-four-hour information, the designation of the agent, the specific instruction for a changed task, stopping when the perimeter cannot be held. One thing changes with a sealed source, and you know what it is. A gamma projector holds a radioactive substance, so the security decree applies to it—including during temporary work on the client's site—with the delegate for radiological security, the duty of anyone who sees a malicious act to inform the operator or the ARB at once, and the police-and-Agency route for security incidents. An X-ray set has none of that, because it holds no radioactive substance.","screen_text":["Same: justifications · 24 h · designation · instruction · stop when unsafe","Added with a sealed source: the security decree — ARB · anyone reports a malicious act · police-and-Agency route"],"start_visual":"Switch the equipment image from the X-ray generator to the supplied gamma projector EQ-GAMMA-PROJECTOR; the unchanged protection labels stay; the security labels appear beside the projector.","beats":[{"at":"Today's job used a portable X-ray set","show":"EQ-XRAY-GENERATOR"},{"at":"A gamma projector holds a radioactive substance","show":"Switch to EQ-GAMMA-PROJECTOR"},{"at":"the security decree applies to it","show":"Security labels"},{"at":"An X-ray set has none of that","show":"X-ray image with 'no radioactive substance'"}],"equipment":["EQ-XRAY-GENERATOR","EQ-GAMMA-PROJECTOR"],"clip":"B1.6-S08-P1"},{"cue":"B1.6-S08-P2","speaker":"Emilia","text":"Here is the transfer in one decision. Imagine the same client and the same vessel, but the welds need gamma radiography and the projector will stay on Bram's site overnight in temporary storage. Today's protection reasoning stays exactly as it was; keep the roles in mind—the operator, its delegate for radiological security, and the agent.","screen_text":["Same client · same vessel · gamma projector stored overnight on site"],"start_visual":"Projector image with a 'temporary storage on the client's site' label; no storage arrangement depicted.","beats":[{"at":"stay on Bram's site overnight","show":"Label"}],"equipment":["EQ-GAMMA-PROJECTOR"],"clip":"B1.6-S08-P2"}],"interaction":{"id":"B1.6-R01","type":"single_choice","prompt_spoken_once":"Which additional question arises when this job uses a sealed radioactive source?","behaviour":"The prompt is spoken automatically exactly once when the activity opens; the narration lead-in never reads it. Manual 'Hear the question' replay. Each option has its own spoken and written feedback (evidence, then next step). Retry without replaying narration; keyboard equivalents (labelled radio controls, Check, Try again, Continue); no auto-advance; no colour-only cues; no timer. Feedback never invents a dose, cause, approval or successful contact.","situation_visible_text":"Gamma projector with a sealed source; overnight temporary storage on the client's site. Radiation protection reasoning unchanged.","options":[{"id":"security","text":"Which security responsibilities apply to this source — including on the client's site and overnight — and who is informed: the operator or its delegate for radiological security.","correct":true,"feedback":{"spoken":"Yes. A gamma projector holds a radioactive substance, so the security decree applies to it, including during temporary work on the client's site: the operator's delegate for radiological security, the duty of anyone who sees a malicious act to inform the operator or the ARB at once, and the police-and-Agency route for security incidents. All of today's radiation-protection decisions stay in force beside it. What the arrangements are is for the ARB and the operator, not for this lesson.","screen":"Security decree applies to the source; ARB and the reporting route; protection reasoning unchanged."},"clip":"B1.6-R01-security"},{"id":"agent_covers","text":"Whether Daniel's agent designation now also covers security, since he is the agent on site.","correct":false,"feedback":{"spoken":"Daniel's designation is real and it continues with a gamma projector: his checks on the equipment and the perimeter are the same. It is a radiation-protection designation by the company. Security responsibilities belong to the operator and its delegate for radiological security, an appointment the Agency approves; the agent does not automatically hold the ARB role.","screen":"Agent = radiation protection; ARB = separate appointment."},"clip":"B1.6-R01-agent_covers"},{"id":"skip_location","text":"Whether the client's location justification can be skipped, because the projector's container is shielded.","correct":false,"feedback":{"spoken":"The projector's shielded container is one of the protection means, and it matters for the dose outside it. It does not change the decree's rule that the client justifies the location in writing for each type of assignment—that applied to the X-ray job this morning and applies here too. The question that is new with a sealed source is security.","screen":"Shielding is a protection means; location justification still applies; security is the new question."},"clip":"B1.6-R01-skip_location"}],"replaces":"B1.6 S08 R01 (private reflection) — replaced one-for-one as one compact decision","placement":"Projector image stays visible.","clip":"B1.6-R01-prompt"},"sequence":{"cues_before_interaction":["B1.6-S08-P1","B1.6-S08-P2"],"interaction_after_cue":"B1.6-S08-P2","interaction_id":"B1.6-R01","post_interaction_cues":[],"rule":"Play cues_before_interaction in order; open the interaction immediately after interaction_after_cue (it speaks its prompt once); post_interaction_cues play only when their condition is met; nothing in post_interaction_cues is spoken before the interaction."}},{"id":"S09","title":"What the module has given you","paragraphs":[{"cue":"B1.6-S09-P1","speaker":"Emilia","text":"That was one Thursday. Look back at what you used. From the opening lesson, the three questions, and the rule that the client justifies technique and location in writing while we check and refuse when a justification does not hold—with the decree's twenty-four hours for the written job information. From the lesson on people, the designation of the agent from our own trained staff, and the difference between a check record and an approval. From the licence lesson, the location tiers: movable workpieces within one cubic metre and under 500 kilograms always in a bunker; larger or heavier ones preferably in a bunker, then an irradiation infrastructure on the client's site, and only when neither is reasonably feasible another place, after a joint risk analysis. From the external-worker lesson, that Clara's experience does not make her our agent and that her instruction covers the task it was given for. And from the lesson on things going wrong, the stop-and-report duty, the three people who hear about it, the verification before anyone resumes, the company's route to the Agency when a stop cannot be resolved, and the discipline of saying what is not yet known.","screen_text":["Three questions · designation · location tiers · external worker · stop-and-report"],"start_visual":"Connected job story recap on the planner: each lesson's element pulses at its phrase (the request, the planning line, the location dossier, Clara's instruction record, the held drawing).","beats":[{"at":"From the opening lesson","show":"Request thumbnail"},{"at":"From the lesson on people","show":"Planning line"},{"at":"From the licence lesson","show":"Location dossier"},{"at":"From the external-worker lesson","show":"Clara's instruction record"},{"at":"from the lesson on things going wrong","show":"Held drawing and record"}],"clip":"B1.6-S09-P1"},{"cue":"B1.6-S09-P2","speaker":"Emilia","text":"A good decision is neither a permanent yes nor a permanent no. It connects a particular conclusion to particular evidence and to the people who hold the next responsibility. Finishing this module does not designate you as an agent, authorise an installation or replace the practical experience, the workplace instruction and the medical surveillance that real work requires—you know by now exactly which documents would show those things. The rest of the course turns to the science behind the decisions: what radiation is, how it interacts with matter and with people, and how we measure it. Keep one question with you into those lessons: what does this information actually allow me to conclude? Thank you for working through this module with me.","screen_text":["Finishing this module does not designate, authorise or replace practical experience, instruction or medical surveillance","Next: the science behind the decisions"],"start_visual":"Emilia to camera; calm route to the next subject (stop 2 of the course route).","beats":[{"at":"Finishing this module does not designate you","show":"Boundary label"},{"at":"The rest of the course turns to the science","show":"Course route: stop 2 highlighted"}],"clip":"B1.6-S09-P2"}],"sequence":{"cues_before_interaction":["B1.6-S09-P1","B1.6-S09-P2"],"interaction_after_cue":null,"interaction_id":null,"post_interaction_cues":[]}}]}]};
